INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vjrivmon/handwriting-ocr/affordances', 'affordances', 'vjrivmon', 'handwriting-ocr', 'community', 'affordances vjrivmon handwriting-ocr community Affordances is a design concept that suggests how an object can be used, benefiting developers and users alike by creating intuitive interfaces. Affordances 是指对象的属性，暗示了其使用方式。了解 Affordances 有助于设计更好的 AI 交互体验 Affordances は、オブジェクトの属性であり、その使用方法を暗示します。Affordances を理解することで、より良い AI インタラクション体験を設計できます Affordances 는 객체의 속성으로, 사용 방법을 암시합니다. Affordances 를 이해하면 더 나은 AI 상호작용 경험을 설계할 수 있습니다 Las affordances son propiedades de un objeto que sugieren cómo puede ser usado, mejorando la usabilidad en aplicaciones de reconocimiento de escritura manuscrita Les affordances sont des propriétés d''un objet qui suggèrent comment il peut être utilisé, améliorant ainsi l''expérience utilisateur dans les applications de reconnaissance d''écriture manuscrite Affordances sind Eigenschaften eines Objekts, die darauf hindeuten, wie es verwendet werden kann, und verbessern so die Benutzerfreundlichkeit in Handschrifterkennungs-Anwendungen As affordances são propriedades de um objeto que sugerem como ele pode ser usado, melhorando a interação com ferramentas de IA. Affordances - это свойства объекта, которые предполагают, как он может быть использован, улучшая взаимодействие с ИИ Агентами. الافورданس هيخصائصلكائن التي تشير إلى كيفية استخدامها، مما يحسن التفاعل مع أدوات الذكاء الاصطناعي. what is affordances how to use affordances in design affordances vs usability affordances design principles install affordances library affordances setup guide for AI agents affordances alternative design concepts applying affordances to AI interfaces affordances and human-computer interaction affordances in UI/UX design Affordances 设计 AI 交互体验 用户体验优化 人机交互 LLMs 应用 benchmarking 实践 AI エージェント 交互效率 设计指南 Supports physical affordances as defined by James J. Gibson Applies Don Norman''s design principles for intuitive interfaces Provides benchmarking of Large Language Models (LLMs) for optimization Enables recognition of handwritten text through customized app development Utilizes concepts from ''The Design of Everyday Things'' by Don Norman Allows for the creation of objects with clear usage suggestions Affordances is a property of an object that suggests its possible uses, originally coined by James J. Gibson in 1966 and later applied to design by Don Norman.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('udecode/plate/lfg', 'community', 'udecode', 'plate', 'udecode/plate', 'lfg', 15967, 953, 31, '2026-02-28T00:47:18Z', '2026-02-28T12:48:05.891Z', '9ab08fa53db637559144777db9918a5c9af0273824aa93a6524f90da924a5dfd', '{"id":"udecode/plate/lfg","name":"lfg","description":{"zh":"lfg是一款基于AI的富文本编辑器，集成了MCP和shadcn/ui，支持React和TypeScript","ja":"lfgはAIエージェントを搭載したリッチテキストエディターで、MCPとshadcn/uiを統合しています","ko":"lfg는 AI 에이전트를 탑재한 리치 텍스트 편집기로서 MCP 및 shadcn/ui를 통합하였습니다","es":"lfg es un editor de texto enriquecido (WYSIWYG) de código abierto para React, construido con Slate.js y TypeScript. Integra capacidades de IA a través de MCP y utiliza los componentes de shadcn/ui para una interfaz moderna y accesible.","fr":"lfg est un éditeur de texte enrichi (WYSIWYG) open source pour React, construit avec Slate.js et TypeScript. Il intègre des capacités d''IA via MCP et utilise les composants shadcn/ui pour une interface moderne et accessible.","de":"lfg ist ein Open-Source Rich-Text Editor (WYSIWYG) für React, erbaut mit Slate.js und TypeScript. Es integriert KI-Fähigkeiten über MCP und nutzt shadcn/ui Komponenten für eine moderne und zugängliche Oberfläche.","pt":"O lfg é um editor de texto rico com recursos de IA, MCP e shadcn/ui, permitindo uma edição avançada.","ru":"Lfg - это редактор с ИИ, MCP и shadcn/ui, обеспечивающий продвинутую редакцию.","ar":"lfg هو محرر نص غني مع ميزات الذكاء الاصطناعي، MCP، و shadcn/ui، مما يسمح بالتحرير المتقدم.","en":"Rich-text editor with AI, MCP, and shadcn/ui"},"seo":{"title":{"zh":"AI智能编辑器lfg - 集成MCP和shadcn/ui","ja":"AIエージェント lfg - MCPとshadcn/uiを搭載したリッチテキストエディター","ko":"AI 에이전트 lfg - MCP 및 shadcn/ui가 통합된 리치 텍스트 편집기","es":"lfg: Editor de texto enriquecido con IA y MCP para React","fr":"lfg: Éditeur de texte enrichi avec IA et MCP pour React","de":"lfg: Rich-Text Editor mit KI und MCP für React","pt":