INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('udecode/plate/lfg', 'lfg', 'udecode', 'plate', 'community', 'lfg udecode plate community ai mcp react shadcn-ui slate typescript wysiwyg lfg是一款基于AI的富文本编辑器，集成了MCP和shadcn/ui，支持React和TypeScript lfgはAIエージェントを搭載したリッチテキストエディターで、MCPとshadcn/uiを統合しています lfg는 AI 에이전트를 탑재한 리치 텍스트 편집기로서 MCP 및 shadcn/ui를 통합하였습니다 lfg es un editor de texto enriquecido (WYSIWYG) de código abierto para React, construido con Slate.js y TypeScript. Integra capacidades de IA a través de MCP y utiliza los componentes de shadcn/ui para una interfaz moderna y accesible. lfg est un éditeur de texte enrichi (WYSIWYG) open source pour React, construit avec Slate.js et TypeScript. Il intègre des capacités d''IA via MCP et utilise les composants shadcn/ui pour une interface moderne et accessible. lfg ist ein Open-Source Rich-Text Editor (WYSIWYG) für React, erbaut mit Slate.js und TypeScript. Es integriert KI-Fähigkeiten über MCP und nutzt shadcn/ui Komponenten für eine moderne und zugängliche Oberfläche. O lfg é um editor de texto rico com recursos de IA, MCP e shadcn/ui, permitindo uma edição avançada. Lfg - это редактор с ИИ, MCP и shadcn/ui, обеспечивающий продвинутую редакцию. lfg هو محرر نص غني مع ميزات الذكاء الاصطناعي، MCP، و shadcn/ui، مما يسمح بالتحرير المتقدم. Rich-text editor with AI, MCP, and shadcn/ui 如何使用lfg 什么是AI编辑器 lfg替代品 lfg vs 其他编辑器 lfg安装指南 lfg设置教程 AI编辑器工具 富文本编辑器 Rich-text editor with AI, MCP, and shadcn/ui');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('selhorys/dataspoke-baseline/kubectl', 'community', 'selhorys', 'dataspoke-baseline', 'selhorys/dataspoke-baseline', 'kubectl', 14, 0, 31, '2026-03-01T12:15:36Z', '2026-03-01T12:50:29.623Z', '3dec97d2fb2d08b4ac604147b8ca2a35fb67ef01c12b540e400c01f46a8c83b5', '{"id":"selhorys/dataspoke-baseline/kubectl","name":"kubectl","description":{"zh":"kubectl AI数据目录入门工具是一款用于简化数据管理和集成的工具。它提供了一种简单的方式来管理和集成数据","ja":"kubectl AIエージェントデータカタログスターターは、データ管理と統合を簡素化するためのツールです。データの管理と統合を簡単に行うことができます","ko":"kubectl AI 에이전트 데이터 카탈로그 시작하기는 데이터 관리와 통합을 간소화하는 도구입니다. 데이터를 관리하고 통합하는 간단한 방법을 제공합니다","es":"kubectl es una herramienta de línea de comandos para interactuar con clusters de Kubernetes, ideal para desarrolladores que buscan integrar la inteligencia artificial en sus proyectos","fr":"kubectl est un outil en ligne de commande pour interagir avec des clusters Kubernetes, idéal pour les développeurs qui cherchent à intégrer l''intelligence artificielle dans leurs projets","de":"kubectl ist ein Kommandozeilen-Tool zum Interagieren mit Kubernetes-Clustern, ideal für Entwickler, die künstliche Intelligenz in ihre Projekte integrieren möchten","pt":"O kubectl é uma ferramenta de linha de comando para gerenciar clusters Kubernetes, ideal para catálogos de dados de IA.","ru":"kubectl - это командная строка для управления кластерами Kubernetes, идеальна для каталогов данных ИИ.","ar":"kubectl هو أداة سطر أوامر لتنظيم مجموعات Kubernetes، مثالية لكتالوجات البيانات الذكاء الاصطناعي.","en":"AI Data Catalog Starter"},"seo":{"title":{"zh":"kubectl AI数据目录入门工具","ja":"kubectl AIエージェントデータカタログスターター","ko":"kubectl AI 에이전트 데이터 카탈로그 시작하기","es":"kubectl: Herramientas de AI para Desarrolladores","fr":"kubectl: Outils d''IA pour Développeurs","de":"kubectl: KI-Tools für Entwickler","pt":"Ferramentas de IA: kubectl para Catálogo de Dados","ru":"ИИ Агенты: ku