INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('selhorys/dataspoke-baseline/kubectl', 'kubectl', 'selhorys', 'dataspoke-baseline', 'community', 'kubectl selhorys dataspoke-baseline community kubectl AI数据目录入门工具是一款用于简化数据管理和集成的工具。它提供了一种简单的方式来管理和集成数据 kubectl AIエージェントデータカタログスターターは、データ管理と統合を簡素化するためのツールです。データの管理と統合を簡単に行うことができます kubectl AI 에이전트 데이터 카탈로그 시작하기는 데이터 관리와 통합을 간소화하는 도구입니다. 데이터를 관리하고 통합하는 간단한 방법을 제공합니다 kubectl es una herramienta de línea de comandos para interactuar con clusters de Kubernetes, ideal para desarrolladores que buscan integrar la inteligencia artificial en sus proyectos kubectl est un outil en ligne de commande pour interagir avec des clusters Kubernetes, idéal pour les développeurs qui cherchent à intégrer l''intelligence artificielle dans leurs projets kubectl ist ein Kommandozeilen-Tool zum Interagieren mit Kubernetes-Clustern, ideal für Entwickler, die künstliche Intelligenz in ihre Projekte integrieren möchten O kubectl é uma ferramenta de linha de comando para gerenciar clusters Kubernetes, ideal para catálogos de dados de IA. kubectl - это командная строка для управления кластерами Kubernetes, идеальна для каталогов данных ИИ. kubectl هو أداة سطر أوامر لتنظيم مجموعات Kubernetes، مثالية لكتالوجات البيانات الذكاء الاصطناعي. AI Data Catalog Starter kubectl AI工具 数据目录管理 数据集成和同步 kubectl命令行工具 AI数据目录入门工具 数据管理和集成 kubectl安装 kubectl设置指南 AI Data Catalog Starter');
