INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arbgjr/satra/reference-indexer', 'reference-indexer', 'arbgjr', 'satra', 'community', 'reference-indexer arbgjr satra community reference-indexer是一种实时监控B3资产波动性的AI智能代理系统，帮助开发者快速发现市场机会 reference-indexerは、B3資産のボラティリティをリアルタイムで監視するAIエージェントシステムであり、開発者が市場の機会を迅速に発見するのに役立ちます reference-indexer는 실시간으로 B3 자산의 변동성을 감시하는 AI 에이전트 시스템으로 개발자가 시장 기회를 신속하게 발견하도록 도와줍니다 Reference-indexer es un sistema de alertas en tiempo real para volatilidad de ativos de la B3, diseñado para desarrolladores Reference-indexer est un système d''alertes en temps réel pour la volatilité des actifs de la B3, conçu pour les développeurs Reference-indexer ist ein Echtzeit-Alertsystem für B3-Volatilität, entwickelt für Entwickler O reference-indexer é uma ferramenta de IA que fornece alertas em tempo real para volatilidade de ativos da B3, ajudando desenvolvedores a tomar decisões informadas. Reference-indexer - это инструмент ИИ, который предоставляет реальные оповещения о волатильности активов B3, помогающий разработчикам принимать обоснованные решения. reference-indexer هي أداة ذكاء اصطناعي تقدم تنبيهات الوقت الحقيقي لتحليلات B3، مما يساعد المطورين على اتخاذ قرارات مدروسة. Sistema de alertas em tempo real para volatilidade de ativos da B3 如何使用reference-indexer 什么是AI智能代理 reference-indexer替代品 reference-indexer vs 其他AI工具 安装reference-indexer reference-indexer设置指南 Python开发者工具 Node.js开发者工具 Sistema de alertas em tempo real para volatilidade de ativos da B3');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Syedaashnaghazanfar/full-stack-todo-app/notification-ui', 'community', 'Syedaashnaghazanfar', 'full-stack-todo-app', 'Syedaashnaghazanfar/full-stack-todo-app', 'notification-ui', 0, 0, 31, '2026-03-05T06:20:06.276Z', '2026-03-05T08:14:11.638Z', 'b1470954596364db57b123d0b13f4d053961314448b77eb12a1c68d7bf378715', '{"id":"Syedaashnaghazanfar/full-stack-todo-app/notification-ui","name":"notification-ui","description":{"zh":"notification-ui是一种AI智能通知界面，用于构建Todo应用程序，提供强大的用户体验","ja":"notification-uiは、AIエージェントによる通知UIで、Todoアプリケーションを構築し、強力なユーザーエクスペリエンスを提供する","ko":"notification-ui는 Todo 애플리케이션을 구축하기 위한 AI 에이전트 알림 UI로, 강력한 사용자 경험을 제공합니다","es":"La interfaz de notificación es crucial para aplicaciones Todo. Aprende a integrar notificaciones efectivas con nuestra guía","fr":"L''interface de notification est essentielle pour les applications Todo. Apprenez à intégrer des notifications efficaces avec notre guide","de":"Die Benachrichtigungs-Oberfläche ist entscheidend für Todo-Anwendungen. Lernen Sie, wie Sie effektive Benachrichtigungen integrieren, mit unserer Anleitung","pt":"A ferramenta de notificação UI é uma solução para criar notificações personalizadas em aplicativos Todo. Ela oferece uma interface de usuário intuitiva para desenvolvedores","ru":"Инструмент Notification-UI является решением для создания настраиваемых уведомлений в Todo-приложениях. Он предлагает интуитивно понятный интерфейс для разработчиков","ar":"أداة واجهة المستخدم للإشعارات هي حل لإنشاء إشعارات مخصصة في تطبيقات Todo. إنها توفر واجهة مستخدم متوافقة مع مطوري البرمجيات","en":"Todo-Application"},"seo":{"title":{"zh":"AI智能通知界面 - Todo 应用程序","ja":"AIエージェントによる通知UI - Todoアプリケーション","ko":"AI 에이전트 알림 UI - Todo 애플리케이션","es":"Herramientas de notificación para aplicaciones Todo","fr":"Outils de notification pour applications Todo","de":"Benachrichtigungstools für Todo-Anwendungen","pt":"Ferramentas de Notificação UI para Desenvolvedores","ru":"ИИ Агенты: Notification-UI для Разработчиков","ar":"أدوات الإشعارات واجهة المستخدم لل مطورين","en":"notification-ui"},"description":{"zh":"notification-ui是一种AI智能通知界面，用于构建Todo应用程序，提供强大的用户体验","ja":"notification-uiは、AIエージェントによる通知UIで、Todoアプリケーションを構築し、強力なユーザーエクスペリエンスを提供する","ko":"notification-ui는 Todo 애플리케이션을 구축하기 위한 AI 에이전트 알림 UI로, 강력한 사용자 경험을 제공합니다","es":"La interfaz de notificación es crucial para aplicaciones Todo. Aprende a integrar notificaciones efectivas con nuestra guía","fr":"L''interface de notification est essentielle pour les applications Todo. Apprenez à intégrer des notifications efficaces avec notre guide","de":"Die Benachrichtigungs-Oberfläche ist entscheidend für Todo-Anwendungen. Lernen Sie, wie Sie effektive Benachrichtigungen integrieren, mit unserer Anleitung","pt":"A ferramenta de notificação UI é uma solução para criar notificações personalizadas em aplicativos Todo. Ela oferece uma interface de usuário intuitiva para ...","ru":"Инструмент Notification-UI является решением для создания настраиваемых уведомлений в Todo-приложениях. Он предлагает интуитивно понятный интерфейс для разра...","ar":"أداة واجهة المستخدم للإشعارات هي حل لإنشاء إشعارات مخصصة في تطبيقات Todo. إنها توفر واجهة مستخدم متوافقة مع مطوري البرمجيات","en":"Todo-Application"},"definition":{"en":"Todo-Application"},"features":{"zh":["使用React构建强大的通知界面","支持Node.js和Python","提供CLI工具进行快速开发","兼容多种设备和浏览器","支持自定义通知样式","提供实时通知更新"],"ja":["Reactを使用して強力な通知UIを構築","Node.jsとPythonをサポート","CLIツールを使用して迅速に開発","多くのデバイスとブラウザをサポート","通知スタイルをカスタマイズ","リアルタイム通知更新を提供"],"ko":["React를 사용하여 강력한 알림 UI를 구축","Node.js와 Python을 지원","CLI 툴을 사용하여 빠르게 개발","다양한 장치와 브라우저를 지원","알림 스타일을 사용자 지정","실시간 알림 업데이트를 제공"],"es":["Integración con APIs de notificación","Personalización de notificaciones para aplicaciones Todo","Compatibilidad con múltiples plataformas","Notificaciones en tiempo real","Soporte para notificaciones push"],"fr":["Intégration avec les API de notification","Personnalisation des notifications pour les applications Todo","Compatibilité avec plusieurs plateformes","Notifications en temps réel","Prise en charge des notifications push"],"de":["Integration mit Benachrichtigungs-APIs","Anpassung von Benachrichtigungen für Todo-Anwendungen","Kompatibilität mit mehreren Plattformen","Echtzeit-Benachrichtigungen","Unterstützung für Push-Benachrichtigungen"],"pt":["Criação de notificações personalizadas","Interface de usuário intuitiva","Integração fácil em aplicativos Todo","Suporte a múltiplos formatos de notificação","Personalização de layout e design"],"ru":["Создание настраиваемых уведомлений","Интуитивно понятный интерфейс","Легкая интеграция в Todo-приложениях","Поддержка нескольких форматов уведомлений","Настройка макета и дизайна"],"ar":["إنشاء إشعارات مخصصة","واجهة مستخدم متوافقة","دمج سهل في تطبيقات Todo","دعم لمسارات الإشعارات المتعددة","تخصيص التصميم والتخطيط"]},"keywords":{"zh":["AI智能通知界面","Todo应用程序","React构建通知界面","Node.js和Python支持","CLI工具","通知界面设计","实时通知更新","如何使用notification-ui","notification-ui安装指南"],"ja":["AIエージェントによる通知UI","Todoアプリケーション","Reactを使用して通知UIを構築","Node.jsとPythonのサポート","CLIツール","通知UIデザイン","リアルタイム通知更新","notification-uiの使い方","notification-uiのインストールガイド"],"ko":["AI 에이전트 알림 UI","Todo 애플리케이션","React를 사용하여 알림 UI를 구축","Node.js와 Python 지원","CLI 툴","알림 UI 디자인","실시간 알림 업데이트","notification-ui 사용법","notification-ui 설치 가이드"],"es":["herramientas de notificación","aplicaciones Todo","notificaciones push","cómo integrar notificaciones","alternativas a OneSignal","guía de notificaciones para desarrolladores","notificaciones en tiempo real","personalización de notificaciones","integración con APIs de notificación"],"fr":["outils de notification","applications Todo","notifications push","comment intégrer des notifications","alternatives à OneSignal","guide de notifications pour développeurs","notifications en temps réel","personnalisation des notifications","intégration avec les API de notification"],"de":["Benachrichtigungstools","Todo-Anwendungen","Push-Benachrichtigungen","wie man Benachrichtigungen integriert","Alternativen zu OneSignal","Anleitung für Entwickler","Echtzeit-Benachrichtigungen","Anpassung von Benachrichtigungen","Integration mit Benachrichtigungs-APIs"],"pt":["ferramentas de notificação UI","como usar notificação UI","o que é notificação UI","notificação UI vs outras ferramentas","instalar notificação UI","guia de configuração notificação UI","desenvolvimento de aplicativos com notificação UI"],"ru":["ИИ Агенты","инструменты уведомлений","как использовать Notification-UI","что такое Notification-UI","Notification-UI альтернатива","установка Notification-UI","руководство по настройке Notification-UI","разработка приложений с Notification-UI"],"ar":["أدوات الإشعارات واجهة المستخدم","كيفية استخدام أداة الإشعارات","ما هي أداة الإشعارات واجهة المستخدم","أداة الإشعارات واجهة المستخدم بديل","تثبيت أداة الإشعارات واجهة المستخدم","دليل إعداد أداة الإشعارات واجهة المستخدم","تطوير التطبيقات مع أداة الإشعارات واجهة المستخدم"]}},"owner":"Syedaashnaghazanfar","repo":"full-stack-todo-app","repoPath":"Syedaashnaghazanfar/full-stack-todo-app","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.276Z","topics":[],"category":"community","skillMd":{"name":"notification-ui","description":"Renders notification bell icon with unread count badge, pulse animations for new notifications, and dropdown panel (320px × max 400px) displaying notification items with purple theme for VERY IMPORTANT tasks. Includes mark-as-read interaction and empty state handling.","bodyPreview":"# Notification UI Skill\n\n## Overview\n\nThe notification UI skill provides the visual interface for displaying notifications, including a bell icon with badge, animated indicators, and an interactive notification panel.\n\n## When to Apply\n\nApply this skill:\n- When rendering the app header (bell icon)\n- When displaying unread notification count\n- When showing notification panel/dropdown\n- When animating new notification arrivals\n- When user interacts with notifications (click to mark as read)\n- When","body":"# Notification UI Skill\n\n## Overview\n\nThe notification UI skill provides the visual interface for displaying notifications, including a bell icon with badge, animated indicators, and an interactive notification panel.\n\n## When to Apply\n\nApply this skill:\n- When rendering the app header (bell icon)\n- When displaying unread notification count\n- When showing notification panel/dropdown\n- When animating new notification arrivals\n- When user interacts with notifications (click to mark as read)\n- When displaying empty state (no notifications)\n\n## Bell Icon Specifications\n\n### Icon Size and Position\n\n- **Size**: 24px × 24px\n- **Position**: Top-right header\n- **Color**: Default #374151 (gray), hover #1F2937 (dark gray)\n\n```jsx\nfunction BellIcon({ unreadCount, onClick }) {\n  return (\n    <button\n      className=\"bell-icon-button\"\n      onClick={onClick}\n      aria-label={`Notifications (${unreadCount} unread)`}\n    >\n      <svg\n        width=\"24\"\n        height=\"24\"\n        viewBox=\"0 0 24 24\"\n        fill=\"none\"\n        xmlns=\"http://www.w3.org/2000/svg\"\n        className=\"bell-icon\"\n      >\n        <path\n          d=\"M15 17H20L18.5951 15.5951C18.2141 15.2141 18 14.6973 18 14.1585V11C18 8.38757 16.3304 6.16509 14 5.34142V5C14 3.89543 13.1046 3 12 3C10.8954 3 10 3.89543 10 5V5.34142C7.66962 6.16509 6 8.38757 6 11V14.1585C6 14.6973 5.78595 15.2141 5.40493 15.5951L4 17H9M15 17V18C15 19.6569 13.6569 21 12 21C10.3431 21 9 19.6569 9 18V17M15 17H9\"\n          stroke=\"currentColor\"\n          strokeWidth=\"2\"\n          strokeLinecap=\"round\"\n          strokeLinejoin=\"round\"\n        />\n      </svg>\n      {unreadCount > 0 && (\n        <span className=\"badge\">{unreadCount > 99 ? ''99+'' : unreadCount}</span>\n      )}\n    </button>\n  );\n}\n```\n\n### Bell Icon Styling\n\n```css\n.bell-icon-button {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 8px;\n  background: transparent;\n  border: none;\n  cursor: pointer;\n  border-radius: 6px;\n  transition: background-color 0.2s ease;\n}\n\n.bell-icon-button:hover {\n  background-color: #F3F4F6;\n}\n\n.bell-icon {\n  color: #374151;\n  transition: color 0.2s ease;\n}\n\n.bell-icon-button:hover .bell-icon {\n  color: #1F2937;\n}\n```\n\n## Unread Count Badge\n\n### Badge Specifications\n\n- **Shape**: Circular\n- **Background**: #DC2626 (red)\n- **Text**: White (#FFFFFF)\n- **Display**: Count up to 99, then \"99+\"\n- **Position**: Top-right corner of bell icon\n\n```css\n.badge {\n  position: absolute;\n  top: 4px;\n  right: 4px;\n  min-width: 18px;\n  height: 18px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: #DC2626; /* Red */\n  color: #FFFFFF; /* White */\n  font-size: 10px;\n  font-weight: 700;\n  border-radius: 50%;\n  padding: 0 4px;\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);\n}\n```\n\n### Badge Display Logic\n\n```javascript\nfunction getBadgeText(count) {\n  if (count === 0) return null; // No badge\n  if (count > 99) return ''99+'';\n  return count.toString();\n}\n```\n\n## Pulse Animation\n\n### Animation Specifications\n\n- **Duration**: 2 seconds\n- **Effect**: Purple glow (#8B5CF6)\n- **Trigger**: On new notification arrival\n- **Iterations**: 3 times, then stop\n\n```css\n@keyframes pulse {\n  0%, 100% {\n    box-shadow: 0 0 0 0 rgba(139, 92, 246, 0.7);\n  }\n  50% {\n    box-shadow: 0 0 0 8px rgba(139, 92, 246, 0);\n  }\n}\n\n.bell-icon-button.pulsing {\n  animation: pulse 2s ease-in-out 3;\n}\n```\n\n### Animation Trigger\n\n```jsx\nfunction NotificationBell({ notifications }) {\n  const [isPulsing, setIsPulsing] = useState(false);\n  const prevCountRef = useRef(notifications.length);\n\n  useEffect(() => {\n    // Detect new notification\n    if (notifications.length > prevCountRef.current) {\n      setIsPulsing(true);\n\n      // Stop animation after 6 seconds (3 iterations × 2s)\n      setTimeout(() => setIsPulsing(false), 6000);\n    }\n\n    prevCountRef.current = notifications.length;\n  }, [notifications.length]);\n\n  return (\n    <BellIcon\n      className={isPulsing ? ''pulsing'' : ''''}\n      unreadCount={notifications.filter(n => !n.read).length}\n    />\n  );\n}\n```\n\n## Notification Dropdown Panel\n\n### Panel Specifications\n\n- **Width**: 320px\n- **Max Height**: 400px\n- **Scrollable**: Yes (overflow-y: auto)\n- **Position**: Dropdown below bell icon\n- **Elevation**: Shadow for depth\n\n```css\n.notification-dropdown {\n  position: absolute;\n  top: calc(100% + 8px);\n  right: 0;\n  width: 320px;\n  max-height: 400px;\n  overflow-y: auto;\n  background-color: #FFFFFF;\n  border: 1px solid #E5E7EB;\n  border-radius: 8px;\n  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1),\n              0 4px 6px -2px rgba(0, 0, 0, 0.05);\n  z-index: 1000;\n}\n\n.notification-dropdown-header {\n  padding: 16px;\n  border-bottom: 1px solid #E5E7EB;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.notification-dropdown-title {\n  font-size: 16px;\n  font-weight: 600;\n  color: #111827;\n}\n\n.mark-all-read {\n  font-size: 12px;\n  color: #8B5CF6;\n  background: none;\n  border: none;\n  cursor: pointer;\n  font-weight: 600;\n}\n\n.mark-all-read:hover {\n  color: #7C3AED;\n  text-decoration: underline;\n}\n```\n\n## Notification Item Styling\n\n### Item Specifications\n\n- **Padding**: 16px\n- **Border**: Bottom separator (1px solid #F3F4F6)\n- **Hover**: Background change to #F9FAFB\n- **Purple Theme**: VERY IMPORTANT notifications use #8B5CF6 accent\n\n```css\n.notification-item {\n  padding: 16px;\n  border-bottom: 1px solid #F3F4F6;\n  cursor: pointer;\n  transition: background-color 0.15s ease;\n}\n\n.notification-item:hover {\n  background-color: #F9FAFB;\n}\n\n.notification-item:last-child {\n  border-bottom: none;\n}\n\n.notification-item.unread {\n  background-color: #FAF5FF; /* Very light purple */\n}\n\n.notification-item.unread:hover {\n  background-color: #F3E8FF; /* Light purple */\n}\n\n.notification-content {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.notification-header {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n}\n\n.notification-priority-indicator {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background-color: #8B5CF6; /* Purple for VERY IMPORTANT */\n  margin-top: 6px;\n  flex-shrink: 0;\n}\n\n.notification-message {\n  font-size: 14px;\n  color: #374151;\n  line-height: 1.5;\n  flex: 1;\n}\n\n.notification-item.unread .notification-message {\n  font-weight: 600;\n  color: #111827;\n}\n\n.notification-time {\n  font-size: 12px;\n  color: #9CA3AF;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n\n.unread-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background-color: #8B5CF6; /* Purple */\n}\n```\n\n## Complete Notification Item Component\n\n```jsx\nfunction NotificationItem({ notification, onMarkAsRead }) {\n  const handleClick = () => {\n    if (!notification.read) {\n      onMarkAsRead(notification.id);\n    }\n  };\n\n  const relativeTime = formatRelativeTime(notification.timestamp);\n\n  return (\n    <div\n      className={`notification-item ${notification.read ? '''' : ''unread''}`}\n      onClick={handleClick}\n    >\n      <div className=\"notification-content\">\n        <div className=\"notification-header\">\n          <div className=\"notification-priority-indicator\" />\n          <p className=\"notification-message\">{notification.message}</p>\n        </div>\n        <div className=\"notification-time\">\n          {!notification.read && <span className=\"unread-dot\" />}\n          <span>{relativeTime}</span>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction formatRelativeTime(timestamp) {\n  const now = Date.now();\n  const diff = now - timestamp;\n  const minutes = Math.floor(diff / (1000 * 60));\n  const hours = Math.floor(diff / (1000 * 60 * 60));\n  const days = Math.floor(diff / (1000 * 60 * 60 * 24));\n\n  if (minutes < 1) return ''Just now'';\n  if (minutes < 60) return `${minutes}m ago`;\n  if (hours < 24) return `${hours}h ago`;\n  return `${days}d ago`;\n}\n```\n\n## Mark-as-Read Interaction\n\n### Click to Mark Read\n\nClicking an unread notification marks it as read:\n\n```jsx\nfunction handleNotificationClick(notification) {\n  if (!notification.read) {\n    // Mark as read\n    notificationPersistence.markAsRead(notification.id);\n\n    // Update UI state\n    setNotifications(notificationPersistence.getAll());\n    setUnreadCount(notificationPersistence.getUnreadCount());\n\n    // Optional: Navigate to task\n    navigateToTask(notification.taskId);\n  }\n}\n```\n\n### Visual Feedback\n\n```jsx\nfunction NotificationItem({ notification, onMarkAsRead }) {\n  const [isMarking, setIsMarking] = useState(false);\n\n  const handleClick = async () => {\n    if (!notification.read && !isMarking) {\n      setIsMarking(true);\n      await onMarkAsRead(notification.id);\n      setIsMarking(false);\n    }\n  };\n\n  return (\n    <div\n      className={`notification-item ${notification.read ? '''' : ''unread''} ${isMarking ? ''marking'' : ''''}`}\n      onClick={handleClick}\n    >\n      {/* ... */}\n    </div>\n  );\n}\n```\n\n## Empty State\n\n### Empty State Component\n\n```jsx\nfunction EmptyState() {\n  return (\n    <div className=\"notification-empty-state\">\n      <div className=\"empty-icon\">🔔</div>\n      <p className=\"empty-title\">No notifications</p>\n      <p className=\"empty-description\">\n        You''re all caught up! Notifications for VERY IMPORTANT tasks will appear here.\n      </p>\n    </div>\n  );\n}\n```\n\n### Empty State Styling\n\n```css\n.notification-empty-state {\n  padding: 48px 24px;\n  text-align: center;\n  color: #6B7280;\n}\n\n.empty-icon {\n  font-size: 48px;\n  margin-bottom: 16px;\n  opacity: 0.4;\n}\n\n.empty-title {\n  font-size: 16px;\n  font-weight: 600;\n  color: #374151;\n  margin-bottom: 8px;\n}\n\n.empty-description {\n  font-size: 14px;\n  color: #9CA3AF;\n  line-height: 1.5;\n}\n```\n\n## Complete Notification System\n\n```jsx\nfunction NotificationSystem() {\n  const [isOpen, setIsOpen] = useState(false);\n  const [notifications, setNotifications] = useState([]);\n  const [unreadCount, setUnreadCount] = useState(0);\n  const dropdownRef = useRef(null);\n\n  // Load notifications\n  useEffect(() => {\n    const loaded = notificationPersistence.getAll();\n    setNotifications(loaded);\n    setUnreadCount(notificationPersistence.getUnreadCount());\n  }, []);\n\n  // Close dropdown when clicking outside\n  useEffect(() => {\n    function handleClickOutside(event) {\n      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {\n        setIsOpen(false);\n      }\n    }\n\n    document.addEventListener(''mousedown'', handleClickOutside);\n    return () => document.removeEventListener(''mousedown'', handleClickOutside);\n  }, []);\n\n  const handleMarkAsRead = (id) => {\n    notificationPersistence.markAsRead(id);\n    setNotifications(notificationPersistence.getAll());\n    setUnreadCount(notificationPersistence.getUnreadCount());\n  };\n\n  const handleMarkAllAsRead = () => {\n    notificationPersistence.markAllAsRead();\n    setNotifications(notificationPersistence.getAll());\n    setUnreadCount(0);\n  };\n\n  return (\n    <div className=\"notification-system\" ref={dropdownRef}>\n      <NotificationBell\n        unreadCount={unreadCount}\n        onClick={() => setIsOpen(!isOpen)}\n        notifications={notifications}\n      />\n\n      {isOpen && (\n        <div className=\"notification-dropdown\">\n          <div className=\"notification-dropdown-header\">\n            <h3 className=\"notification-dropdown-title\">Notifications</h3>\n            {unreadCount > 0 && (\n              <button className=\"mark-all-read\" onClick={handleMarkAllAsRead}>\n                Mark all as read\n              </button>\n            )}\n          </div>\n\n          {notifications.length === 0 ? (\n            <EmptyState />\n          ) : (\n            <div className=\"notification-list\">\n              {notifications.map(notification => (\n                <NotificationItem\n                  key={notification.id}\n                  notification={notification}\n                  onMarkAsRead={handleMarkAsRead}\n                />\n              ))}\n            </div>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n```\n\n## Responsive Behavior\n\n### Mobile Adjustments\n\n```css\n@media (max-width: 640px) {\n  .notification-dropdown {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    width: 100%;\n    max-height: 100%;\n    border-radius: 0;\n  }\n\n  .notification-dropdown-header {\n    position: sticky;\n    top: 0;\n    background-color: #FFFFFF;\n    z-index: 1;\n  }\n}\n```\n\n## Integration Points\n\nThis skill integrates with:\n- **Notification Persistence Skill**: Reads notification data\n- **Notification Trigger Skill**: Displays triggered notifications\n- **Priority Classification Skill**: Uses purple theme for VERY IMPORTANT\n- **Notification Experience Agent**: Coordinates UI interactions\n\n## Accessibility\n\n- Bell icon button has aria-label with unread count\n- Keyboard navigation supported (Enter/Space to open/close)\n- Focus management in dropdown\n- Screen reader announcements for new notifications\n- Sufficient color contrast ratios (WCAG AA)\n\n## Performance Considerations\n\n- Dropdown renders only when open (conditional rendering)\n- Virtual scrolling for large notification lists (>50)\n- Debounced mark-as-read operations\n- Memoized components to prevent unnecessary re-renders\n"},"lastSynced":"2026-03-05T08:14:11.638Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring interactive notification systems with animated indicators and bell icons","zh":"适用于需要交互式通知系统的前端代理，具有动画指示器和铃铛图标","ja":"フロントエンドエージェントが対話型の通知システムを必要とする場合に適しています。アニメーションインジケータとベルアイコンが含まれます","ko":"대화형 알림 시스템과 애니메이션 지시자 및 벨 아이콘을 필요로 하는 프론트엔드 에이전트에 적합합니다","es":"Ideal para Agentes Frontend que requieren sistemas de notificación interactivos con indicadores animados y iconos de campana","fr":"Idéal pour les agents Frontend nécessitant des systèmes de notification interactifs avec des indicateurs animés et des icônes de cloche","de":"Ideal für Frontend-Agents, die interaktive Benachrichtigungssysteme mit animierten Indikatoren und Glocken-Symbols benötigen","pt":"Ideal para Agentes Frontend que requerem sistemas de notificação interativos com indicadores animados e ícones de sino","ru":"Идеально для фронтенд-агентов, требующих интерактивных систем уведомлений с анимированными индикаторами и колокольчиками","ar":"مثالي للوكلاء الأماميين الذين يتطلبون أنظمة إعلام تفاعلية مع مؤشرات متحركة وأيقونات جرس"},"recommendation":{"en":"Empowers agents to display unread notification counts, animate new notification arrivals, and provide interactive notification panels using HTML, CSS, and JavaScript, while integrating with existing app headers and dropdown menus","zh":"赋予代理显示未读通知数、动画化新通知到达，并提供交互式通知面板，使用HTML、CSS和JavaScript，同时与现有的应用程序头部和下拉菜单集成","ja":"未読通知数の表示、新しい通知の到着をアニメーション化し、HTML、CSS、JavaScriptを使用してインタラクティブな通知パネルを提供し、既存のアプリケーションヘッダーとドロップダウンメニューと統合する","ko":"에이전트가 읽지 않은 알림 수를 표시하고 새로운 알림 도착을 애니메이션화하며 HTML, CSS 및 JavaScript를 사용하여 대화형 알림 패널을 제공하고 기존 애플리케이션 헤더 및 드롭다운 메뉴와 통합하는 기능을 제공합니다","es":"Habilita a los agentes a mostrar recuentos de notificaciones no leídas, animar la llegada de nuevas notificaciones y proporcionar paneles de notificación interactivos utilizando HTML, CSS y JavaScript, mientras se integra con los encabezados de aplicaciones y menús desplegables existentes","fr":"Permet aux agents d''afficher des comptes de notifications non lus, d''animer l''arrivée de nouvelles notifications et de fournir des panneaux de notification interactifs en utilisant HTML, CSS et JavaScript, tout en s''intégrant avec les en-têtes d''application et les menus déroulants existants","de":"Ermächtigt Agenten, ungelesene Benachrichtigungsanzahlen anzuzeigen, die Ankunft neuer Benachrichtigungen zu animieren und interaktive Benachrichtigungspanels unter Verwendung von HTML, CSS und JavaScript bereitzustellen, während sie sich in bestehende App-Header und Dropdown-Menüs integrieren","pt":"Habilita os agentes a exibir contagens de notificações não lidas, animar a chegada de novas notificações e fornecer painéis de notificação interativos usando HTML, CSS e JavaScript, enquanto se integra com os cabeçalhos e menus suspensos existentes do aplicativo","ru":"Наделяет агентов возможностью отображать счетчики непрочитанных уведомлений, анимировать прибытие новых уведомлений и предоставлять интерактивные панели уведомлений, используя HTML, CSS и JavaScript, а также интегрироваться с существующими заголовками и выпадающими меню приложения","ar":"تمكين الوكلاء من عرض عدد الإشعارات غير المقروءة، وتحريك وصول الإشعارات الجديدة، وتقديم لوحات إعلام تفاعلية باستخدام HTML و CSS وJavaScript، مع التكامل مع رؤوس وменوس الإسقاط التابعة للتطبيقات الحالية"},"useCases":{"en":["Rendering dynamic notification badges","Animating notification panel openings","Handling user interactions with notification items"],"zh":["渲染动态通知徽章","动画化通知面板打开","处理用户与通知项的交互"],"ja":["動的通知バッジのレンダリング","通知パネルのアニメーション化された開き","通知アイテムとのユーザーインタラクションの処理"],"ko":["동적 알림 배지 렌더링","알림 패널 애니메이션 오픈","사용자와 알림 항목의 상호 작용 처리"],"es":["Renderizado de insignias de notificación dinámicas","Animación de aperturas de paneles de notificación","Manipulación de interacciones de usuario con elementos de notificación"],"fr":["Renderisation de badges de notification dynamiques","Animation de l''ouverture de panneaux de notification","Gestion des interactions de l''utilisateur avec les éléments de notification"],"de":["Rendering dynamischer Benachrichtigungs-Badges","Animation des Öffnens von Benachrichtigungs-Panel","Handhabung von Benutzerinteraktionen mit Benachrichtigungselementen"],"pt":["Renderização de distintivos de notificação dinâmicos","Animação de aberturas de painéis de notificação","Tratamento de interações do usuário com itens de notificação"],"ru":["Рендеринг динамических значков уведомлений","Анимация открытий панелей уведомлений","Обработка взаимодействий пользователя с элементами уведомлений"],"ar":["تجسيد شارات الإعلام الديناميكية","تحريك فتحات لوحات الإعلام","معالجة تفاعلات المستخدم مع عناصر الإعلام"]},"limitations":{"en":["Requires DOM access for rendering","Limited to web-based applications","Needs CSS for styling and animations"],"zh":["需要DOM访问来渲染","仅限于基于Web的应用程序","需要CSS用于样式和动画"],"ja":["レンダリングするためにDOMへのアクセスが必要","Webベースのアプリケーションに限定される","スタイルとアニメーションのためにCSSが必要"],"ko":["렌더링하려면 DOM 액세스가 필요합니다","웹 기반 응용 프로그램에만 제한됩니다","스타일 및 애니메이션을 위해 CSS가 필요합니다"],"es":["Requiere acceso a DOM para renderizar","Limitado a aplicaciones web","Necesita CSS para estilo y animaciones"],"fr":["Nécessite un accès au DOM pour le rendu","Limité aux applications web","Nécessite CSS pour le style et les animations"],"de":["Benötigt DOM-Zugriff für Rendering","Begrenzt auf webbasierte Anwendungen","Benötigt CSS für Stil und Animationen"],"pt":["Requer acesso ao DOM para renderização","Limitado a aplicações baseadas na web","Necessita CSS para estilização e animações"],"ru":["Требует доступа к DOM для рендеринга","Ограничен веб-приложениями","Требует CSS для стилизации и анимаций"],"ar":["يتطلب الوصول إلى DOM لعرض","محدود للتطبيقات القائمة على الويب","يحتاج إلى CSS للأسلوب والتحريك"]},"version":3},"contentHash":"b1470954596364db57b123d0b13f4d053961314448b77eb12a1c68d7bf378715","qualityScore":31}');
