INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Syedaashnaghazanfar/full-stack-todo-app/notification-ui', 'notification-ui', 'Syedaashnaghazanfar', 'full-stack-todo-app', 'community', 'notification-ui Syedaashnaghazanfar full-stack-todo-app community notification-ui是一种AI智能通知界面，用于构建Todo应用程序，提供强大的用户体验 notification-uiは、AIエージェントによる通知UIで、Todoアプリケーションを構築し、強力なユーザーエクスペリエンスを提供する notification-ui는 Todo 애플리케이션을 구축하기 위한 AI 에이전트 알림 UI로, 강력한 사용자 경험을 제공합니다 La interfaz de notificación es crucial para aplicaciones Todo. Aprende a integrar notificaciones efectivas con nuestra guía L''interface de notification est essentielle pour les applications Todo. Apprenez à intégrer des notifications efficaces avec notre guide Die Benachrichtigungs-Oberfläche ist entscheidend für Todo-Anwendungen. Lernen Sie, wie Sie effektive Benachrichtigungen integrieren, mit unserer Anleitung A ferramenta de notificação UI é uma solução para criar notificações personalizadas em aplicativos Todo. Ela oferece uma interface de usuário intuitiva para desenvolvedores Инструмент Notification-UI является решением для создания настраиваемых уведомлений в Todo-приложениях. Он предлагает интуитивно понятный интерфейс для разработчиков أداة واجهة المستخدم للإشعارات هي حل لإنشاء إشعارات مخصصة في تطبيقات Todo. إنها توفر واجهة مستخدم متوافقة مع مطوري البرمجيات Todo-Application AI智能通知界面 Todo应用程序 React构建通知界面 Node.js和Python支持 CLI工具 通知界面设计 实时通知更新 如何使用notification-ui notification-ui安装指南 Todo-Application');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('UmmItKin/ummit.dev/vitest', 'community', 'UmmItKin', 'ummit.dev', 'UmmItKin/ummit.dev', 'vitest', 0, 0, 31, '2026-03-05T06:20:06.284Z', '2026-03-05T08:25:56.608Z', '87c8cf025987d1f1a0e9c0fd0b8605946a0ebd5478676471ce296d8f0adc0f07', '{"id":"UmmItKin/ummit.dev/vitest","name":"vitest","description":{"zh":"Vitest是一个美丽的个人作品集主题，提供了丰富的功能和高效的开发体验","ja":"Vitestは美しい個人のポートフォリオテーマで、豊富な機能と効率的な開発体験を提供します","ko":"Vitest는 아름다운 개인 포트폴리오 테마로, 풍부한 기능과 효율적인 개발 경험을 제공합니다","pt":"Vitest é um tema de portfolio personalizado forked do Vitesse com recursos estendidos para desenvolvedores","ru":"Vitest - это красивый личный тема портфолио, созданный на основе Vitesse с расширенными функциями для разработчиков","ar":"Vitest هو موضوع محفظة شخصي جميل تم إنشاؤه من Vitesse مع ميزات موسعة للمطورين","en":"A beautiful personal portfolio theme forked from the Vitesse theme with extended features"},"seo":{"title":{"zh":"Vitest AI工具：一个美丽的个人作品集主题","ja":"Vitest AIエージェント：美しい個人のポートフォリオテーマ","ko":"Vitest AI 에이전트: 아름다운 개인 포트폴리오 테마","pt":"Ferramentas de IA: Vitest, um tema de portfolio personali...","ru":"ИИ Агенты: Vitest, красивый личный тема портфолио","ar":"أدوات الذكاء الاصطناعي: Vitest، موضوع محفظة شخصي جميل","en":"vitest"},"description":{"zh":"Vitest是一个美丽的个人作品集主题，提供了丰富的功能和高效的开发体验","ja":"Vitestは美しい個人のポートフォリオテーマで、豊富な機能と効率的な開発体験を提供します","ko":"Vitest는 아름다운 개인 포트폴리오 테마로, 풍부한 기능과 효율적인 개발 경험을 제공합니다","pt":"Vitest é um tema de portfolio personalizado forked do Vitesse com recursos estendidos para desenvolvedores","ru":"Vitest - это красивый личный тема портфолио, созданный на основе Vitesse с расширенными функциями для разработчиков","ar":"Vitest هو موضوع محفظة شخصي جميل تم إنشاؤه من Vitesse مع ميزات موسعة للمطورين","en":"A beautiful personal portfolio theme forked from the Vitesse theme with extended features"},"definition":{"en":"A beautiful personal portfolio theme forked from the Vitesse theme with extended features"},"features":{"zh":["基于Vitesse主题","提供了更多的功能和自定义选项","支持快速开发和部署","拥有漂亮的UI设计","易于使用和扩展"],"ja":["Vitesseテーマをベースに","より多くの機能とカスタマイズオプションを提供","迅速な開発とデプロイをサポート","美しいUIデザインを備えている","使用と拡張が簡単"],"ko":["Vitesse 테마를 기반으로","더 많은 기능과 사용자 정의 옵션을 제공","신속한 개발과 배포를 지원","아름다운 UI 디자인을 갖추고","사용과 확장이 용이"],"pt":["Tema personalizado para portfolio","Recursos estendidos do Vitesse","Perfeito para desenvolvedores","Fácil de usar e personalizar","Compatível com React e outras tecnologias"],"ru":["Красивый личный тема портфолио","Расширенные функции Vitesse","Идеально для разработчиков","Легко использовать и настраивать","Поддерживает React и другие технологии"],"ar":["موضوع محفظة شخصي جميل","ميزات موسعة من Vitesse","مثالي للمطورين","سهل الاستخدام والتخصيص","متوافق مع React وتكنولوجيات أخرى"]},"keywords":{"zh":["Vitest AI工具","个人作品集主题","Vitesse主题","快速开发","如何使用Vitest","Vitest与Vitesse的区别","Vitest安装指南"],"ja":["Vitest AIエージェント","個人のポートフォリオテーマ","Vitesseテーマ","迅速な開発","Vitestの使い方","VitestとVitesseの違い","Vitestのセットアップガイド"],"ko":["Vitest AI 에이전트","개인 포트폴리오 테마","Vitesse 테마","신속한 개발","Vitest 사용법","Vitest와 Vitesse의 차이","Vitest 설치 가이드"],"pt":["como usar Vitest","o que é Vitest","Vitest alternativa","Vitest vs Vitesse","instalar Vitest","guia de configuração do Vitest","desenvolvimento web com Vitest"],"ru":["как использовать Vitest","что такое Vitest","альтернативы Vitest","Vitest vs Vitesse","установить Vitest","руководство по настройке Vitest","веб-разработка с Vitest"],"ar":["كيفية استخدام Vitest","ما هو Vitest","بديل Vitest","Vitest مقابل Vitesse","تثبيت Vitest","دليل إعداد Vitest","تطوير الويب مع Vitest"]}},"owner":"UmmItKin","repo":"ummit.dev","repoPath":"UmmItKin/ummit.dev","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.284Z","topics":[],"category":"community","skillMd":{"name":"vitest","description":"Vitest fast unit testing framework powered by Vite with Jest-compatible API. Use when writing tests, mocking, configuring coverage, or working with test filtering and fixtures.","version":"2026.1.28","bodyPreview":"Vitest is a next-generation testing framework powered by Vite. It provides a Jest-compatible API with native ESM, TypeScript, and JSX support out of the box. Vitest shares the same config, transformers, resolvers, and plugins with your Vite app.\n\n**Key Features:**\n- Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates\n- Jest-compatible: Drop-in replacement for most Jest test suites\n- Smart watch mode: Only reruns affected tests based on module graph\n- Native ESM, TypeS","body":"Vitest is a next-generation testing framework powered by Vite. It provides a Jest-compatible API with native ESM, TypeScript, and JSX support out of the box. Vitest shares the same config, transformers, resolvers, and plugins with your Vite app.\n\n**Key Features:**\n- Vite-native: Uses Vite''s transformation pipeline for fast HMR-like test updates\n- Jest-compatible: Drop-in replacement for most Jest test suites\n- Smart watch mode: Only reruns affected tests based on module graph\n- Native ESM, TypeScript, JSX support without configuration\n- Multi-threaded workers for parallel test execution\n- Built-in coverage via V8 or Istanbul\n- Snapshot testing, mocking, and spy utilities\n\n> The skill is based on Vitest 3.x, generated at 2026-01-28.\n\n## Core\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Configuration | Vitest and Vite config integration, defineConfig usage | [core-config](references/core-config.md) |\n| CLI | Command line interface, commands and options | [core-cli](references/core-cli.md) |\n| Test API | test/it function, modifiers like skip, only, concurrent | [core-test-api](references/core-test-api.md) |\n| Describe API | describe/suite for grouping tests and nested suites | [core-describe](references/core-describe.md) |\n| Expect API | Assertions with toBe, toEqual, matchers and asymmetric matchers | [core-expect](references/core-expect.md) |\n| Hooks | beforeEach, afterEach, beforeAll, afterAll, aroundEach | [core-hooks](references/core-hooks.md) |\n\n## Features\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Mocking | Mock functions, modules, timers, dates with vi utilities | [features-mocking](references/features-mocking.md) |\n| Snapshots | Snapshot testing with toMatchSnapshot and inline snapshots | [features-snapshots](references/features-snapshots.md) |\n| Coverage | Code coverage with V8 or Istanbul providers | [features-coverage](references/features-coverage.md) |\n| Test Context | Test fixtures, context.expect, test.extend for custom fixtures | [features-context](references/features-context.md) |\n| Concurrency | Concurrent tests, parallel execution, sharding | [features-concurrency](references/features-concurrency.md) |\n| Filtering | Filter tests by name, file patterns, tags | [features-filtering](references/features-filtering.md) |\n\n## Advanced\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| Vi Utilities | vi helper: mock, spyOn, fake timers, hoisted, waitFor | [advanced-vi](references/advanced-vi.md) |\n| Environments | Test environments: node, jsdom, happy-dom, custom | [advanced-environments](references/advanced-environments.md) |\n| Type Testing | Type-level testing with expectTypeOf and assertType | [advanced-type-testing](references/advanced-type-testing.md) |\n| Projects | Multi-project workspaces, different configs per project | [advanced-projects](references/advanced-projects.md) |\n"},"lastSynced":"2026-03-05T08:25:56.608Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript Agents requiring high-performance testing with native ESM and TypeScript support.","zh":"适合需要高性能测试的JavaScript代理，支持原生ESM和TypeScript。","ja":"高性能テストが必要なJavaScriptエージェントに適しています。ネイティブESMとTypeScriptをサポートしています。","ko":"고성능 테스트가 필요한 자바스크립트 에이전트에 적합합니다. 네이티브 ESM 및 TypeScript를 지원합니다.","es":"Ideal para agentes de JavaScript que requieren pruebas de alto rendimiento con soporte nativo para ESM y TypeScript.","fr":"Idéal pour les agents JavaScript nécessitant des tests de haute performance avec un support natif pour ESM et TypeScript.","de":"Ideal für JavaScript-Agents, die Hochleistungs-Tests mit nativem ESM- und TypeScript-Unterstützung erfordern.","pt":"Ideal para agentes JavaScript que exigem testes de alto desempenho com suporte nativo ESM e TypeScript.","ru":"Идеально подходит для агентов JavaScript, требующих высокопроизводительного тестирования с родной поддержкой ESM и TypeScript.","ar":"مثالي لعمليات وكيل JavaScript التي تتطلب اختبارات أداء عالي مع دعم أصلي ESM و TypeScript."},"recommendation":{"en":"Empowers agents to leverage Vite-native testing with Jest-compatible APIs, enabling fast HMR-like test updates and smart watch modes that only rerun affected tests based on module graphs, utilizing native ESM and TypeScript support.","zh":"赋予代理使用Vite原生测试功能，通过Jest兼容的API实现快速的HMR样式测试更新和智能监视模式，只重新运行受影响的测试，基于模块图，利用原生ESM和TypeScript支持。","ja":"エージェントにViteネイティブテストを使用する機能を提供し、Jest互換のAPIを使用して、HMRのような高速なテスト更新と、モジュールグラフに基づいて影響を受けたテストのみを再実行するスマートなウォッチモードを実現します。ネイティブESMとTypeScriptをサポートしています。","ko":"에이전트가 Vite 네이티브 테스트를 사용할 수 있도록 하여 Jest와 호환되는 API를 통해 빠른 HMR 같은 테스트 업데이트 및 모듈 그래프에 따라 영향을 받은 테스트만 다시 실행하는 스마트 감시 모드를 활성화하고, 네이티브 ESM 및 TypeScript를 지원합니다.","es":"Habilita a los agentes a aprovechar las pruebas nativas de Vite con APIs compatibles con Jest, lo que permite actualizaciones de pruebas rápidas similares a HMR y modos de vigilancia inteligentes que solo vuelven a ejecutar las pruebas afectadas en función de los gráficos de módulos, utilizando el soporte nativo para ESM y TypeScript.","fr":"Permet aux agents d''exploiter les tests natifs Vite avec des API compatibles Jest, permettant des mises à jour de tests rapides similaires à HMR et des modes de surveillance intelligents qui ne réexécutent que les tests affectés en fonction des graphiques de modules, en utilisant le support natif pour ESM et TypeScript.","de":"Ermächtigt die Agents, Vite-native Tests mit Jest-kompatiblen APIs zu nutzen, wodurch schnelle HMR-ähnliche Test-Updates und intelligente Beobachtungsmodi ermöglicht werden, die nur betroffene Tests basierend auf Modulgraphen neu ausführen, unter Nutzung des nativen ESM- und TypeScript-Supports.","pt":"Habilita os agentes a aproveitar testes nativos Vite com APIs compatíveis com Jest, permitindo atualizações de teste rápidas semelhantes ao HMR e modos de observação inteligentes que apenas reexecutam os testes afetados com base em gráficos de módulos, utilizando suporte nativo ESM e TypeScript.","ru":"Наделяет агентов возможностью использовать тестирование на основе Vite с API, совместимыми с Jest, что обеспечивает быстрые обновления тестов, аналогичные HMR, и умные режимы слежения, которые только пере запускают затронутые тесты на основе модульных графиков, используя родную поддержку ESM и TypeScript.","ar":"تمكين الوكلاء من الاستفادة من اختبارات Vite الأصلية مع واجهات برمجة التطبيقات المتوافقة مع Jest، مما يسمح بتحديثات اختبار سريعة تشبه HMR ووضع مراقبة ذكية التي تعيد تشغيل الاختبارات المتأثرة فقط بناءً على رسوم بيانية للمكونات الإضافية، مع استخدام دعم أصلي ESM و TypeScript."},"useCases":{"en":["Rerunning affected tests with smart watch mode","Utilizing Vite''s transformation pipeline for fast test updates","Migrating Jest test suites to Vitest for improved performance"],"zh":["使用智能监视模式重新运行受影响的测试","利用Vite的转换管道实现快速测试更新","将Jest测试套件迁移到Vitest以提高性能"],"ja":["スマートウォッチモードを使用して影響を受けたテストを再実行する","Viteの変換パイプラインを使用して高速なテスト更新を実現する","JestテストスイートをVitestに移行してパフォーマンスを向上させる"],"ko":["스마트 감시 모드를 사용하여 영향을 받은 테스트를 다시 실행하는 것","Vite의 변환 파이프라인을 사용하여 빠른 테스트 업데이트를 구현하는 것","Jest 테스트 스위트를 Vitest로 마이그레이션하여 성능을 향상시키는 것"],"es":["Volver a ejecutar las pruebas afectadas con el modo de vigilancia inteligente","Utilizar la canalización de transformación de Vite para actualizaciones de pruebas rápidas","Migrar suites de pruebas de Jest a Vitest para mejorar el rendimiento"],"fr":["Réexécuter les tests affectés avec le mode de surveillance intelligent","Utiliser la pipeline de transformation de Vite pour des mises à jour de tests rapides","Migrer les suites de tests Jest vers Vitest pour améliorer les performances"],"de":["Neu ausführen von betroffenen Tests mit dem intelligenten Beobachtungsmodus","Nutzen der Vite-Transformationspipeline für schnelle Test-Updates","Migration von Jest-Test-Suiten zu Vitest für verbesserte Leistung"],"pt":["Reexecutar testes afetados com modo de observação inteligente","Utilizar o pipeline de transformação do Vite para atualizações de teste rápidas","Migrar conjuntos de testes Jest para Vitest para melhorar o desempenho"],"ru":["Перезапускать затронутые тесты в режиме умного слежения","Использовать конвейер преобразования Vite для быстрых обновлений тестов","Мигрировать наборы тестов Jest в Vitest для улучшения производительности"],"ar":["إعادة تشغيل الاختبارات المتأثرة مع وضع المراقبة الذكية","استخدام خط أنابيب تحويل Vite لتحديثات الاختبار السريعة","نقل مجموعات اختبار Jest إلى Vitest لتحسين الأداء"]},"limitations":{"en":["Requires Vite app configuration","Limited to JavaScript and TypeScript projects"],"zh":["需要Vite应用配置","仅限于JavaScript和TypeScript项目"],"ja":["Viteアプリの構成が必要","JavaScriptとTypeScriptプロジェクトのみに限定される"],"ko":["Vite 애플리케이션 구성이 필요함","자바스크립트와 타입스크립트 프로젝트에만 제한됨"],"es":["Requiere configuración de la aplicación Vite","Limitado a proyectos de JavaScript y TypeScript"],"fr":["Nécessite une configuration d''application Vite","Limité aux projets JavaScript et TypeScript"],"de":["Benötigt Vite-App-Konfiguration","Begrenzt auf JavaScript- und TypeScript-Projekte"],"pt":["Requer configuração de aplicativo Vite","Limitado a projetos JavaScript e TypeScript"],"ru":["Требует конфигурации приложения Vite","Ограничен проектами JavaScript и TypeScript"],"ar":["يتطلب تكوين تطبيق Vite","محدود بمشاريع JavaScript و TypeScript"]},"version":3},"contentHash":"87c8cf025987d1f1a0e9c0fd0b8605946a0ebd5478676471ce296d8f0adc0f07","qualityScore":31}