INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('UmmItKin/ummit.dev/vitest', 'vitest', 'UmmItKin', 'ummit.dev', 'community', 'vitest UmmItKin ummit.dev community Vitest是一个美丽的个人作品集主题，提供了丰富的功能和高效的开发体验 Vitestは美しい個人のポートフォリオテーマで、豊富な機能と効率的な開発体験を提供します Vitest는 아름다운 개인 포트폴리오 테마로, 풍부한 기능과 효율적인 개발 경험을 제공합니다 Vitest é um tema de portfolio personalizado forked do Vitesse com recursos estendidos para desenvolvedores Vitest - это красивый личный тема портфолио, созданный на основе Vitesse с расширенными функциями для разработчиков Vitest هو موضوع محفظة شخصي جميل تم إنشاؤه من Vitesse مع ميزات موسعة للمطورين A beautiful personal portfolio theme forked from the Vitesse theme with extended features Vitest AI工具 个人作品集主题 Vitesse主题 快速开发 如何使用Vitest Vitest与Vitesse的区别 Vitest安装指南 A beautiful personal portfolio theme forked from the Vitesse theme with extended features');
