INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('upstash/workflow-js/upstash/workflow TypeScript SDK Skill', 'upstash/workflow TypeScript SDK Skill', 'upstash', 'workflow-js', 'community', 'upstash/workflow TypeScript SDK Skill upstash workflow-js community Upstash 工作流 TypeScript SDK 为开发人员提供了构建持久、可靠、高速的无服务器函数的能力，适用于复杂的工作流和数据处理场景 Upstash ワークフロー TypeScript SDK は、開発者が耐久性、信頼性、パフォーマンスの高いサーバーレス関数を構築できるようにします Upstash 워크플로 TypeScript SDK는 개발자가 지속성, 신뢰성, 고성능의 서버리스 함수를 구축할 수 있게 해줍니다 El SDK de upstash/workflow para TypeScript ofrece funciones serverless duraderas, confiables y de alto rendimiento Le SDK upstash/workflow pour TypeScript propose des fonctions serverless durables, fiables et performantes Das upstash/workflow-SDK für TypeScript bietet zuverlässige und leistungsstarke Serverless-Funktionen O upstash/workflow TypeScript SDK oferece funções sem servidor duráveis, confiáveis e de alto desempenho para desenvolvedores ИИ Агенты: upstash/workflow TypeScript SDK предоставляет надежные и производительные серверные функции أدوات الذكاء الاصطناعي: upstash/workflow TypeScript SDK توفر وظائف خادم أقل معتمده وذكية وأداء عالية Durable, Reliable and Performant Serverless Functions Upstash 工作流 TypeScript SDK 无服务器函数 持久、可靠、高速 工作流和数据处理 AIエージェント Upstash 工作流 alternative 如何使用 Upstash 工作流 Durable, Reliable and Performant Serverless Functions');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ruvnet/ruflo/agent-gossip-coordinator', 'community', 'ruvnet', 'ruflo', 'ruvnet/ruflo', 'agent-gossip-coordinator', 16653, 1887, 30, '2026-03-01T05:06:35Z', '2026-03-06T06:24:07.330Z', '8b61bbbebc16144c99354d7a4d204dbeccc307183839eb966bcc548716ff2515', '{"id":"ruvnet/ruflo/agent-gossip-coordinator","name":"agent-gossip-coordinator","description":{"en":"The agent-gossip-coordinator skill enables developers to deploy intelligent multi-agent swarms and coordinate autonomous workflows. It benefits developers working with Claude and conversational AI systems.","zh":"agent-gossip-coordinator是一种AI多代理协调平台，支持分布式系统构建和集群部署","ja":"Gossip Coordinatorは、AIエージェントのためのスケーラブルな分散システム構築プラットフォームです","ko":"agent-gossip-coordinator는 AI 에이전트를 위한 고급 클러스터링 플랫폼입니다","es":"El agente-gossip-coordinator es una plataforma de orquestación de agentes para Claude que permite la coordinación de flujos de trabajo autónomos y la creación de sistemas de IA conversacional","fr":"L''agent-gossip-coordinator est une plateforme d''orchestration d''agents pour Claude qui permet la coordination de flux de travail autonomes et la création de systèmes d''IA conversationnels","de":"Der agent-gossip-coordinator ist eine Agenten-Orchestrierungsplattform für Claude, die die Koordination autonomer Workflows und die Erstellung von konversationellen KI-Systemen ermöglicht","pt":"O Agent Gossip Coordinator é uma plataforma de orquestração de agentes para Claude, permitindo a implantação de enxames de agentes inteligentes e a coordenação de fluxos de trabalho autônomos","ru":"Координатор Слухов - это ведущая платформа для оркестровки агентов ИИ, обеспечивающая возможность развертывания интеллектуальных роев агентов и координации автономных рабочих процессов","ar":"وكيل النمط الإشعاعي هو منصة رائدة لتنسيق الوكلاء، تمكن من نشر مجموعات من الوكلاء الذكية والمتواصلة و