INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ruvnet/ruflo/agent-gossip-coordinator', 'agent-gossip-coordinator', 'ruvnet', 'ruflo', 'community', 'agent-gossip-coordinator ruvnet ruflo community agentic-ai agentic-engineering agentic-framework agentic-rag agentic-workflow agents ai-assistant ai-tools anthropic-claude autonomous-agents claude-code claude-code-skills codex huggingface mcp-server model-context-protocol multi-agent multi-agent-systems swarm swarm-intelligence The agent-gossip-coordinator skill enables developers to deploy intelligent multi-agent swarms and coordinate autonomous workflows. It benefits developers working with Claude and conversational AI systems. agent-gossip-coordinator是一种AI多代理协调平台，支持分布式系统构建和集群部署 Gossip Coordinatorは、AIエージェントのためのスケーラブルな分散システム構築プラットフォームです agent-gossip-coordinator는 AI 에이전트를 위한 고급 클러스터링 플랫폼입니다 El agente-gossip-coordinator es una plataforma de orquestación de agentes para Claude que permite la coordinación de flujos de trabajo autónomos y la creación de sistemas de IA conversacional L''agent-gossip-coordinator est une plateforme d''orchestration d''agents pour Claude qui permet la coordination de flux de travail autonomes et la création de systèmes d''IA conversationnels Der agent-gossip-coordinator ist eine Agenten-Orchestrierungsplattform für Claude, die die Koordination autonomer Workflows und die Erstellung von konversationellen KI-Systemen ermöglicht O Agent Gossip Coordinator é uma plataforma de orquestração de agentes para Claude, permitindo a implantação de enxames de agentes inteligentes e a coordenação de fluxos de trabalho autônomos Координатор Слухов - это ведущая платформа для оркестровки агентов ИИ, обеспечивающая возможность развертывания интеллектуальных роев агентов и координации автономных рабочих процессов وكيل النمط الإشعاعي هو منصة رائدة لتنسيق الوكلاء، تمكن من نشر مجموعات من الوكلاء الذكية والمتواصلة وتنسيق سير عملها how to use agent-gossip-coordinator agent-gossip-coordinator alternative agent-gossip-coordinator setup guide what is agent-gossip-coordinator agent-gossip-coordinator vs Hugging Face agent-gossip-coordinator install gossip-based consensus protocols multi-agent systems autonomous workflows Claude Code integration AIエージェント agent-gossip-coordinator 分布式系统 集群部署 协调 企业级架构 RAG集成 Claude Code Codex Epidemic dissemination for scalable data sharing Peer selection for optimized network communication State synchronization for consistent system state Conflict resolution for robust error handling Scalability optimization for high-performance systems agent-gossip-coordinator is a leading agent orchestration platform that coordinates gossip-based consensus protocols for scalable eventually consistent systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('limehawk/rmm-scripts/sync', 'community', 'limehawk', 'rmm-scripts', 'limehawk/rmm-scripts', 'sync', 16, 3, 30, '2026-02-18T10:23:26Z', '2026-03-06T06:42:57.894Z', '843d4e29ade3512b1998c2368f29745a995e4dc3a32a6fe888304c8923913a04', '{"id":"limehawk/rmm-scripts/sync","name":"sync","description":{"en":"The sync skill automates the syncing of modified PowerShell and Bash scripts to RMM platforms, benefiting MSPs and IT professionals. It checks for uncommitted changes, commits them, and runs a sync script to push updates to SuperOps.","zh":"Sync AI Agent 提供生产就绪的 PowerShell 和 Bash 脚本，用于 RMM 平台的自动同步","ja":"Sync AIエージェントは、RMM プラットフォーム用の自動同期を可能にする、生产就绪の PowerShell と Bash スクリプトを提供します","ko":"Sync AI 에이전트는 RMM 플랫폼을 위한 자동 동기화를 가능하게 하는 생산 준비 PowerShell 및 Bash 스크립트를 제공합니다","es":"El skill ''sync'' permite sincronizar scripts modificados con SuperOps utilizando PowerShell y Bash. Incluye scripts de producción listos para RMM.","fr":"Le skill ''sync'' permet de synchroniser des scripts modifiés avec SuperOps en utilisant PowerShell et Bash. Il comprend des scripts de production prêts pour RMM.","de":"Das Skill ''sync'' ermöglicht die Synchronisierung von modifizierten Skripten mit SuperOps mithilfe von PowerShell und Bash. Es enthält Produktions-Skripte, die für RMM bereit sind.","pt":"O Sync é uma ferramenta de automação que sincroniza scripts modificados em plataformas de RMM como SuperOps. Ele utiliza PowerShell e Bash para garantir a integração perfeita.","ru":"Sync - это инструмент автоматизации, который синхронизирует измененные скрипты на платформах RMM, таких как SuperOps, используя PowerShell и Bash для идеальной интеграции и поддержки ИИ Агентов","ar":"Sync هو أداة أتمتة تزامن السكريبتات المعدلة على منصات إدارة الشبكات مثل SuperOps، وتستخدم PowerShell و Bash لضمان التكامل المثالي مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"sync: Automated Script Syncing for RMM Platforms | AI Age...","zh":"Sync Setup Guide: PowerShell 和 Bash 脚本同步","ja":"Sync の設定方法: PowerShell と Bash スクリプトの同期","ko":"Sync 설정 가이드: PowerShell 및 Bash 스크립트 동기화","es":"Guía de configuración de sincronización de scripts para S...","fr":"Guide de configuration de synchronisation de scripts pour...","de":"Einrichtungsanleitung für die Synchronisierung von Skript...","pt":"Guia de Configuração do Sync: Scripts de Automatização pa...","ru":"Настройка Sync: скрипты автоматизации для SuperOps и ИИ А...","ar":"دليل إعداد Sync: سكريبتات أتمتة لمنصات SuperOps و أدوات ا..."},"description":{"en":"Streamline your workflow with sync, the AI agent skill that automates script syncing for SuperOps, Datto, and NinjaRMM - get started now!","zh":"使用 Sync AI Agent 实现 PowerShell 和 Bash 脚本的自动同步，适用于 SuperOps、Datto 和 NinjaRMM 平台","ja":"Sync AIエージェントを使用して PowerShell と Bash スクリプトを自動同期します。SuperOps、Datto、NinjaRMM プラットフォームに対応","ko":"Sync AI 에이전트를 사용하여 PowerShell 및 Bash 스크립트를 자동으로 동기화합니다. SuperOps, Datto, NinjaRMM 플랫폼 지원","es":"Sincronice sus scripts modificados con SuperOps utilizando PowerShell y Bash. Obtenga más información sobre la implementación y la ejecución.","fr":"Synchronisez vos scripts modifiés avec SuperOps en utilisant PowerShell et Bash. Découvrez plus d''informations sur la mise en œuvre et l''exécution.","de":"Synchronisieren Sie Ihre modifizierten Skripte mit SuperOps mithilfe von PowerShell und Bash. Erfahren Sie mehr über die Implementierung und Ausführung.","pt":"Aprenda a configurar o Sync para automatizar scripts em plataformas de RMM como SuperOps, Datto e NinjaRMM","ru":"Узнайте, как настроить Sync для автоматизации скриптов на платформах RMM, таких как SuperOps, Datto и NinjaRMM, с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Sync لتشغيل سكريبتات أتمتة على منصات إدارة الشبكات مثل SuperOps و Datto و NinjaRMM مع أدوات الذكاء الاصطناعي"},"definition":{"en":"sync is a PowerShell and Bash script automation tool for RMM platforms, enabling seamless script syncing and version control","zh":"Sync 是一种 AI Agent，用于自动同步 PowerShell 和 Bash 脚本到 RMM 平台","ja":"Sync は、PowerShell と Bash スクリプトを RMM プラットフォームに自動同期する AIエージェントです","ko":"Sync는 PowerShell 및 Bash 스크립트를 RMM 플랫폼에 자동으로 동기화하는 AI 에이전트입니다","es":"Sincronización de scripts es un proceso que actualiza los scripts modificados en SuperOps utilizando herramientas como PowerShell y Bash.","fr":"La synchronisation de scripts est un processus qui met à jour les scripts modifiés dans SuperOps en utilisant des outils tels que PowerShell et Bash.","de":"Die Skript-Synchronisierung ist ein Prozess, der die modifizierten Skripte in SuperOps mithilfe von Tools wie PowerShell und Bash aktualisiert.","pt":"O Sync é uma ferramenta de automação que sincroniza scripts em plataformas de RMM","ru":"Sync - это инструмент автоматизации, который синхронизирует скрипты на платформах RMM","ar":"Sync هو أداة أتمتة تزامن السكريبتات على منصات إدارة الشبكات"},"features":{"en":["Checks for uncommitted changes using Git status","Commits changes with descriptive messages using Git add and commit","Runs a sync script using Python to push updates to SuperOps","Reports sync results to the user","Supports automation for SuperOps, Datto, and NinjaRMM platforms"],"zh":["支持 SuperOps、Datto 和 NinjaRMM 平台","自动检查和提交更改","使用 Git 进行版本控制","支持 PowerShell 和 Bash 脚本","使用 Python 运行同步脚本"],"ja":["SuperOps、Datto、NinjaRMM プラットフォームをサポート","変更を自動的に確認してコミット","Git を使用したバージョン管理","PowerShell と Bash スクリプトをサポート","Python を使用した同期スクリプトの実行"],"ko":["SuperOps, Datto, NinjaRMM 플랫폼 지원","변경 사항 자동 확인 및 커밋","Git 사용 버전 관리","PowerShell 및 Bash 스크립트 지원","Python 사용 동기화 스크립트 실행"],"es":["Sincronización de scripts modificados con SuperOps","Uso de PowerShell y Bash para la sincronización","Incluye scripts de producción listos para RMM","Compatibilidad con plataformas como Datto y NinjaRMM","Reporte de resultados de sincronización","Ejecución de comandos Git para la gestión de versiones"],"fr":["Synchronisation de scripts modifiés avec SuperOps","Utilisation de PowerShell et Bash pour la synchronisation","Comprend des scripts de production prêts pour RMM","Compatibilité avec des plateformes telles que Datto et NinjaRMM","Rapport de résultats de synchronisation","Exécution de commandes Git pour la gestion de versions"],"de":["Synchronisierung von modifizierten Skripten mit SuperOps","Verwendung von PowerShell und Bash für die Synchronisierung","Enthält Produktions-Skripte, die für RMM bereit sind","Kompatibilität mit Plattformen wie Datto und NinjaRMM","Bericht über die Synchronisierungsergebnisse","Ausführung von Git-Befehlen für die Versionsverwaltung"],"pt":["Suporte a plataformas de RMM como SuperOps, Datto e NinjaRMM","Utilização de PowerShell e Bash para automação","Sincronização de scripts modificados","Integração com Git para controle de versão","Relatórios de resultados de sincronização"],"ru":["Поддержка платформ RMM, таких как SuperOps, Datto и NinjaRMM","Использование PowerShell и Bash для автоматизации","Синхронизация измененных скриптов","Интеграция с Git для контроля версий","Отчеты о результатах синхронизации и поддержка ИИ Агентов"],"ar":["دعم منصات إدارة الشبكات مثل SuperOps و Datto و NinjaRMM","استخدام PowerShell و Bash لأتمتة السكريبتات","تزامن السكريبتات المعدلة","التكامل مع Git لمراقبة الإصدارات","تقارير عن نتائج التزامن مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use sync for RMM platforms","sync alternative for MSPs","sync vs Datto script syncing","sync install guide for SuperOps","what is sync in automation","sync setup for NinjaRMM","automating script syncing with sync","sync for IT professionals","RMM platform automation with sync"],"zh":["Sync AI Agent","PowerShell 脚本同步","Bash 脚本同步","RMM 平台","SuperOps","Datto","NinjaRMM","自动同步","Git 版本控制"],"ja":["Sync AIエージェント","PowerShell スクリプトの同期","Bash スクリプトの同期","RMM プラットフォーム","SuperOps","Datto","NinjaRMM","自動同期","Git バージョン管理"],"ko":["Sync AI 에이전트","PowerShell 스크립트 동기화","Bash 스크립트 동기화","RMM 플랫폼","SuperOps","Datto","NinjaRMM","자동 동기화","Git 버전 관리"],"es":["sincronización de scripts","SuperOps","PowerShell","Bash","RMM","Datto","NinjaRMM","skript synchronisieren","herramientas de automatización","gestión de versiones"],"fr":["synchronisation de scripts","SuperOps","PowerShell","Bash","RMM","Datto","NinjaRMM","synchroniser des scripts","outils d''automatisation","gestion de versions"],"de":["Skript-Synchronisierung","SuperOps","PowerShell","Bash","RMM","Datto","NinjaRMM","Skripte synchronisieren","Automatisierungstools","Versionsverwaltung"],"pt":["sync","automação","RMM","SuperOps","Datto","NinjaRMM","PowerShell","Bash","scripts","Git"],"ru":["sync","автоматизация","RMM","SuperOps","Datto","NinjaRMM","PowerShell","Bash","скрипты","Git","ИИ Агенты"],"ar":["sync","أتمتة","إدارة الشبكات","SuperOps","Datto","NinjaRMM","PowerShell","Bash","سكريبتات","Git","أدوات الذكاء الاصطناعي"]}},"owner":"limehawk","repo":"rmm-scripts","repoPath":"limehawk/rmm-scripts","stars":16,"forks":3,"updatedAt":"2026-02-18T10:23:26Z","topics":["automation","bash","datto","msp","ninjarmm","powershell","rmm","scripts","superops"],"category":"community","skillMd":{"name":"sync","description":"Sync scripts to SuperOps - commits changes and pushes to SuperOps platform","bodyPreview":"Sync all modified scripts to SuperOps.\n\n## Steps\n\n1. Check for uncommitted changes\n2. If changes exist, commit them with a descriptive message\n3. Run the sync script to push to SuperOps\n4. Report results\n\n## Execution\n\n```bash\n# Check status\ngit status --short\n\n# If there are changes, commit them\ngit add -A\ngit commit -m \"Update scripts\"\n\n# Run sync\npython ~/dev/superops-script-sync/sync.py sync\n```\n\nReport the sync results to the user.","body":"Sync all modified scripts to SuperOps.\n\n## Steps\n\n1. Check for uncommitted changes\n2. If changes exist, commit them with a descriptive message\n3. Run the sync script to push to SuperOps\n4. Report results\n\n## Execution\n\n```bash\n# Check status\ngit status --short\n\n# If there are changes, commit them\ngit add -A\ngit commit -m \"Update scripts\"\n\n# Run sync\npython ~/dev/superops-script-sync/sync.py sync\n```\n\nReport the sync results to the user.\n"},"lastSynced":"2026-03-06T06:42:57.894Z","agentAnalysis":{"suitability":{"en":"Ideal for Automation Agents requiring seamless Git version control and RMM platform synchronization.","zh":"适用于需要无缝Git版本控制和RMM平台同步的自动化代理。","ja":"Gitのバージョン管理とRMMプラットフォームの同期が必要な自動化エージェントに最適です。","ko":"무결점한 Git 버전 관리와 RMM 플랫폼 동기화가 필요한 자동화 에이전트에 적합합니다.","es":"Ideal para Agentes de Automatización que requieren un control de versión Git sin problemas y una sincronización de plataforma RMM.","fr":"Idéal pour les agents d''automatisation nécessitant un contrôle de version Git sans interruption et une synchronisation de plateforme RMM.","de":"Ideal für Automatisierungsagenten, die eine nahtlose Git-Versionierung und eine RMM-Plattform-Synchronisierung benötigen.","pt":"Ideal para Agentes de Automação que requerem controle de versão Git sem interrupções e sincronização da plataforma RMM.","ru":"Идеально для агентов автоматизации, требующих бесшовный контроль версий Git и синхронизацию платформы RMM.","ar":"مثالي لوكلاء التأهيل الذين يتطلبون التحكم في الإصدار Git دون انقطاع وتزامن منصة RMM."},"recommendation":{"en":"Empowers agents to automate syncing of modified PowerShell and Bash scripts to SuperOps via Git, utilizing protocols like git status and python script execution, ensuring efficient updates to RMM platforms.","zh":"赋予代理人自动同步修改后的PowerShell和Bash脚本到SuperOps的能力，利用git status和Python脚本执行等协议，确保对RMM平台的高效更新。","ja":"PowerShellとBashのスクリプトをSuperOpsに同期するためのエージェントの自動化を可能にし、git statusやPythonスクリプトの実行などのプロトコルを利用して、RMMプラットフォームの効率的な更新を保証します。","ko":"수퍼옵스에서 수정된 파워쉘과 배시 스크립트를 자동 동기화할 수 있는 에이전트의 능력을 부여하고, git 상태 및 파이썬 스크립트 실행 등의 프로토콜을 사용하여 RMM 플랫폼의 효율적인 업데이트를 보장합니다.","es":"Habilita a los agentes a automatizar la sincronización de scripts de PowerShell y Bash modificados con SuperOps a través de Git, utilizando protocolos como git status y ejecución de scripts de Python, lo que garantiza actualizaciones eficientes de las plataformas RMM.","fr":"Permet aux agents d''automatiser la synchronisation des scripts PowerShell et Bash modifiés vers SuperOps via Git, en utilisant des protocoles tels que git status et l''exécution de scripts Python, garantissant ainsi des mises à jour efficaces des plateformes RMM.","de":"Ermöglicht es Agenten, die Synchronisierung von geänderten PowerShell- und Bash-Skripten mit SuperOps über Git zu automatisieren, indem Protokolle wie git status und Python-Skriptausführung verwendet werden, um effiziente Updates der RMM-Plattformen zu gewährleisten.","pt":"Concede poder aos agentes para automatizar a sincronização de scripts PowerShell e Bash modificados para o SuperOps via Git, utilizando protocolos como git status e execução de scripts python, garantindo atualizações eficientes para plataformas RMM.","ru":"Наделяет агентов возможностью автоматизировать синхронизацию измененных скриптов PowerShell и Bash в SuperOps через Git, используя протоколы như git status и выполнение python-скриптов, обеспечивая эффективные обновления платформ RMM.","ar":"يمنح الوكلاء القدرة على توفير التزامن التلقائي للبرامج النصية PowerShell وBash المعدلة إلى SuperOps عبر Git ، باستخدام بروتوكولات مثل حالة git وتنفيذ سكرايبتات python ، مما يضمن تحديثات فعالة لمنصات RMM."},"useCases":{"en":["Automating script updates to SuperOps","Syncing modified PowerShell scripts","Committing uncommitted Bash script changes"],"zh":["自动同步脚本更新到SuperOps","同步修改后的PowerShell脚本","提交未提交的Bash脚本更改"],"ja":["SuperOpsへのスクリプト更新の自動同期","変更されたPowerShellスクリプトの同期","コミットされていないBashスクリプトの変更のコミット"],"ko":["수퍼옵스에서 스크립트 업데이트를 자동 동기화","수정된 파워쉘 스크립트를 동기화","커밋되지 않은 배시 스크립트의 변경 사항을 커밋"],"es":["Automatizar actualizaciones de scripts en SuperOps","Sincronizar scripts de PowerShell modificados","Confirmar cambios de scripts de Bash no confirmados"],"fr":["Automatiser les mises à jour de scripts vers SuperOps","Synchroniser les scripts PowerShell modifiés","Valider les modifications de scripts Bash non validées"],"de":["Automatisierung von Skriptaktualisierungen in SuperOps","Synchronisierung von geänderten PowerShell-Skripten","Bestätigen von nicht bestätigten Bash-Skriptänderungen"],"pt":["Automatizar atualizações de scripts para o SuperOps","Sincronizar scripts PowerShell modificados","Confirmar alterações de scripts Bash não confirmados"],"ru":["Автоматизировать обновления скриптов в SuperOps","Синхронизировать измененные скрипты PowerShell","Зафиксировать незафиксированные изменения скриптов Bash"],"ar":["توفير تحديثات البرامج النصية تلقائيًا إلى SuperOps","مزامنة برامج نصية PowerShell المعدلة","إلزام التغييرات غير الملزمة لبرامج نصية Bash"]},"limitations":{"en":["Requires Git installation","Python 3.x compatibility needed","SuperOps RMM platform access required"],"zh":["需要Git安装","需要Python 3.x兼容性","需要SuperOps RMM平台访问"],"ja":["Gitのインストールが必要","Python 3.xとの互換性が必要","SuperOps RMMプラットフォームへのアクセスが必要"],"ko":["Git 설치가 필요합니다","파이썬 3.x 호환성이 필요합니다","수퍼옵스 RMM 플랫폼 액세스가 필요합니다"],"es":["Requiere instalación de Git","Se requiere compatibilidad con Python 3.x","Se requiere acceso a la plataforma RMM de SuperOps"],"fr":["Nécessite l''installation de Git","Nécessite la compatibilité Python 3.x","Nécessite l''accès à la plateforme RMM de SuperOps"],"de":["Benötigt Git-Installation","Benötigt Python 3.x-Kompatibilität","Benötigt Zugriff auf die SuperOps-RMM-Plattform"],"pt":["Requer instalação do Git","Compatibilidade com Python 3.x necessária","Acesso à plataforma RMM do SuperOps necessário"],"ru":["Требуется установка Git","Необходима совместимость с Python 3.x","Требуется доступ к платформе RMM SuperOps"],"ar":["يتطلب تثبيت Git","مطلوبة التوافق مع Python 3.x","مطلوب الوصول إلى منصة RMM لبرنامج SuperOps"]},"version":4},"contentHash":"843d4e29ade3512b1998c2368f29745a995e4dc3a32a6fe888304c8923913a04","qualityScore":30}');
