INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kubony/openclaw-gcp-setup/gcp-iam', 'gcp-iam', 'kubony', 'openclaw-gcp-setup', 'community', 'gcp-iam kubony openclaw-gcp-setup community The gcp-iam skill automates GCP infrastructure management, enabling developers to create service accounts, grant roles, and generate JSON keys. It benefits developers and DevOps teams working with GCP. GCP IAM 是一种服务账户管理和自动化工具，支持创建、角色赋予和密钥管理。使用 Claude Code 可以轻松实现 GCP IAM 自动化 GCP IAM はサービスアカウント管理と自動化ツールで、作成、役割付与、キーの管理をサポートします。Claude Code を使用すると、GCP IAM 自動化を簡単に実装できます GCP IAM은 서비스 계정 관리 및 자동화 도구로, 생성, 역할 부여, 키 관리를 지원합니다. Claude Code를 사용하면 GCP IAM 자동화를 쉽게 구현할 수 있습니다 GCP IAM es un conjunto de habilidades de Claude Code para la automatización de infraestructura en la nube de Google. Crea y gestiona servicios de cuenta y roles. GCP IAM est un ensemble de compétences de Claude Code pour l''automatisation de l''infrastructure dans le cloud de Google. Créez et gérez des services de compte et des rôles. GCP IAM ist ein Satz von Fähigkeiten von Claude Code für die Automatisierung der Infrastruktur in der Google-Cloud. Erstellen und verwalten Sie Dienstkonto und Rollen. O gcp-iam é uma coleção de habilidades para automação de infraestrutura na nuvem. Crie contas de serviço, atribua papéis e gerencie chaves com facilidade. Gcp-iam - это набор навыков для автоматизации инфраструктуры в облаке. Создавайте сервисные аккаунты, назначайте роли и управляйте ключами легко. ال gcp-iam هي مجموعة من المهارات لتحسين أتمتة البنية التحتية السحابية. أنشئ حسابات الخدمة، وحدد الأدوار، وإدارة المفاتيح بسهولة. how to use gcp-iam gcp-iam setup guide gcp-iam alternative gcp-iam vs terraform gcp-iam install gcp iam management gcp service account creation gcp role assignment gcp json key generation GCP IAM 服务账户管理 自动化 Claude Code GCP 服务账户 服务账户创建 角色赋予 密钥管理 Creates service accounts using the `/gcp-iam create` command Grants roles to service accounts with the `/gcp-iam grant` command Generates JSON keys for service accounts using the `/gcp-iam key` command Lists service accounts with the `gcloud iam service-accounts list` command Supports role assignment with the `--format"table(email,displayName,disabled)"` option Manages service accounts with the `gcloud iam service-accounts` command gcp-iam is a skill for automating GCP IAM management, providing commands for service account creation, role assignment, and key management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bpodwinski/World42/world42-origin-camera', 'community', 'bpodwinski', 'World42', 'bpodwinski/World42', 'world42-origin-camera', 6, 0, 30, '2026-03-04T00:25:22Z', '2026-03-06T06:53:51.609Z', 'e0184de72c02d4267b1e55c6bcccb6f499ee6f9689d13e89294e6a0b70ca90f8', '{"id":"bpodwinski/World42/world42-origin-camera","name":"world42-origin-camera","description":{"en":"The world42-origin-camera skill enables developers to create immersive, real-scale planet experiences using Babylon.js and WebGL2. It provides a Quadtree LOD system for efficient rendering.","zh":"World42 Origin Camera 是一个使用 Babylon.js 构建的 WebGL2 项目，实现 Quadtree LOD 实时渲染","ja":"World42 Origin Camera は Babylon.js で構築された WebGL2 プロジェクトで、Quadtree LOD のリアルタイムレンダリングを実現","ko":"World42 Origin Camera는 Babylon.js로 구축된 WebGL2 프로젝트로 Quadtree LOD 실시간 렌더링을 구현합니다","es":"world42-origin-camera es un proyecto WebGL2 que utiliza Quadtree LOD para renderizar planetas a escala real con Babylon.js","fr":"world42-origin-camera est un projet WebGL2 qui utilise Quadtree LOD pour rendre des planètes à échelle réelle avec Babylon.js","de":"world42-origin-camera ist ein WebGL2-Projekt, das Quadtree LOD verwendet, um Planeten im Maßstab 1:1 mit Babylon.js zu rendern","pt":"O world42-origin-camera é um projeto WebGL2 que utiliza Quadtree LOD e Babylon.js para renderizar planetas em escala real","ru":"World42-origin-camera - это проект WebGL2, использующий Quadtree LOD и Babylon.js для рендеринга планет в реальном масштабе","ar":"world42-origin-camera هو مشروع WebGL2 يستخدم Quadtree LOD و Babylon.js لتحسين جودة عرض الكواكب في المقاييس الحقيقية"},"seo":{"title":{"en":"world42-origin-camera: Quadtree LOD Setup Guide | AI Agen...","zh":"World42 Origin Camera Setup Guide - Babylon.js WebGL2 项目","ja":"World42 Origin Camera セットアップガイド - Babylon.js WebGL2 プロジェクト","ko":"World42 Origin Camera 설