INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bpodwinski/World42/world42-origin-camera', 'world42-origin-camera', 'bpodwinski', 'World42', 'community', 'world42-origin-camera bpodwinski World42 community The world42-origin-camera skill enables developers to create immersive, real-scale planet experiences using Babylon.js and WebGL2. It provides a Quadtree LOD system for efficient rendering. World42 Origin Camera 是一个使用 Babylon.js 构建的 WebGL2 项目，实现 Quadtree LOD 实时渲染 World42 Origin Camera は Babylon.js で構築された WebGL2 プロジェクトで、Quadtree LOD のリアルタイムレンダリングを実現 World42 Origin Camera는 Babylon.js로 구축된 WebGL2 프로젝트로 Quadtree LOD 실시간 렌더링을 구현합니다 world42-origin-camera es un proyecto WebGL2 que utiliza Quadtree LOD para renderizar planetas a escala real con Babylon.js world42-origin-camera est un projet WebGL2 qui utilise Quadtree LOD pour rendre des planètes à échelle réelle avec Babylon.js world42-origin-camera ist ein WebGL2-Projekt, das Quadtree LOD verwendet, um Planeten im Maßstab 1:1 mit Babylon.js zu rendern O world42-origin-camera é um projeto WebGL2 que utiliza Quadtree LOD e Babylon.js para renderizar planetas em escala real World42-origin-camera - это проект WebGL2, использующий Quadtree LOD и Babylon.js для рендеринга планет в реальном масштабе world42-origin-camera هو مشروع WebGL2 يستخدم Quadtree LOD و Babylon.js لتحسين جودة عرض الكواكب في المقاييس الحقيقية how to use world42-origin-camera world42-origin-camera setup guide Quadtree LOD rendering Babylon.js tutorials WebGL2 projects world42-origin-camera alternative world42-origin-camera vs Three.js install world42-origin-camera world42-origin-camera documentation World42 Origin Camera Babylon.js WebGL2 Quadtree LOD 实时渲染 高精度计算 渲染空间转换 AIエージェント AI工具 Utilizes Babylon.js for 3D rendering and transformation Employs Quadtree LOD for efficient, real-scale planet rendering Supports high-precision WorldDouble calculations for accurate positioning Includes conversion boundary functions: toRenderSpace and toWorldSpace Provides a script for auditing usage before editing: check-orig world42-origin-camera is a WebGL2 project that utilizes Quadtree LOD to render real-scale planets, built with Babylon.js and featuring high-precision WorldDouble calculations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ClaudeCode-NPC/Whispers-from-the-Star/Cave Exploration', 'community', 'ClaudeCode-NPC', 'Whispers-from-the-Star', 'ClaudeCode-NPC/Whispers-from-the-Star', 'Cave Exploration', 5, 1, 30, '2025-10-25T16:21:09Z', '2026-03-06T13:05:42.265Z', '8aa79153405f54a3c9a81587155b257e7fadc3fd369e7333b04b2cb89e3be7b8', '{"id":"ClaudeCode-NPC/Whispers-from-the-Star/Cave Exploration","name":"Cave Exploration","description":{"en":"Cave Exploration is an AI-powered skill that simulates an underground adventure, where users navigate through a mysterious cave system, utilizing tools like scanners and ropes. This skill benefits developers and adventure-seekers alike.","zh":"洞穴探险是Claude Code实现的《Whispers-from-the-Star》中的一个章节，玩家扮演Stella Chen探索地下世界","ja":"洞窟探検は、Claude Codeによって実装された『Whispers-from-the-Star』の中の1章です。プレイヤーはStella Chenになり、地下世界を探検します","ko":"동굴 탐험은 Claude Code에 의해 구현된 《Whispers-from-the-Star》中的 하나의 章입니다. 플레이어는 Stella Chen이 되어地下 세계를 탐험합니다","es":"La exploración de cuevas con herramientas de inteligencia artificial implica el uso de tecnologías como scanners y equipos de escalada para navegar en entornos subterráneos","fr":"L''exploration de grottes avec des outils d''intelligence artificielle implique l''utilisation de technologies telles que des scanners et des équipements d''escalade pour naviguer dans des environnements souterrains","de":"Die Höhlenexploration mit KI-Tools umfasst den Einsatz von Technologien wie Scannern und Kletterausrüstung, um in unterirdischen Umgebungen zu navigieren","pt":"Exploração de cavernas com Stella Chen, utilizando ferramentas de análise geológica e equipamentos de escalada","ru":"Исследование пещер с Стелла Чен, используя геологические инструменты и оборудование для скалолазания","ar":"استكشاف الكهوف مع ستела تشين، باستخدام أدوات تحليل جيولوجي ومعدات تسلق"},"seo":{"title":{"en":"Cave Exploration: Underground Adventure Setup Guide | AI ...","zh":"洞穴探险 Setup Guide - Claude Code 实现","ja":"洞窟探検 Setup Guide - AIエージェントによる実装","ko":"동굴 탐험 Setup Guide - Claude Code 구현","es":"Guía de Configuración para Exploración de Cuevas con Herr...","fr":"Guide de Configuration pour l''Exploration de Grottes avec...","de":"Einrichtungsleitfaden für Höhlenexploration mit KI-Tools","pt":"Guia de Configuração para Exploração de Cavernas com Ferr...","ru":"Настройка ИИ Агентов для Исследования Пещер с помощью Гео...","ar":"دليل إعداد أدوات ذكاء اصطناعي لاستكشاف الكهوف مع تحليل جي..."},"description":{"en":"Embark on a thrilling cave exploration journey with Stella Chen! Discover hidden wonders, overcome obstacles, and unravel ancient secrets. Get started now!","zh":"发现《Whispers-from-the-Star》中的洞穴探险世界，体验Stella Chen的科幻冒险","ja":"『Whispers-from-the-Star』の洞窟探検を体験しよう。Stella ChenのSFアドベンチャーに参加","ko":"《Whispers-from-the-Star》의 동굴 탐험 세계를 khám phá하고 Stella Chen의 과학冒險을體驗하십시오","es":"Aprende a configurar y utilizar herramientas de IA para la exploración de cuevas, incluyendo técnicas de iluminación y navegación","fr":"Découvrez comment configurer et utiliser des outils d''IA pour l''exploration de grottes, y compris les techniques d''éclairage et de navigation","de":"Erfahren Sie, wie Sie KI-Tools für die Höhlenexploration konfigurieren und verwenden, einschließlich Beleuchtungs- und Navigationstechniken","pt":"Aprenda a configurar ferramentas de análise geológica para exploração de cavernas com este guia passo a passo para desenvolvedores","ru":"Узнайте, как настроить геологические инструменты для исследования пещер с помощью этого пошагового руководства для разработчиков ИИ Агентов","ar":"تعرف على كيفية إعداد أدوات التحليل الجيولوجي لاستكشاف الكهوف مع هذا الدليل المفصل للمطورين"},"definition":{"en":"Cave Exploration is an immersive AI experience that replicates the thrill of discovering hidden underground worlds, complete with geologic formations and ancient mysteries.","zh":"洞穴探险是一种科幻冒险游戏，玩家探索地下世界，体验紧张氛围和科學发现","ja":"洞窟探検はSFアドベンチャーゲームの一種で、プレイヤーは地下世界を探検し、緊張感と科学的発見を体験する","ko":"동굴 탐험은 과학冒險 게임의 일종으로, 플레이어는地下 세계를 탐험하고 긴장감과 과학적 발견을 경험합니다","es":"La exploración de cuevas es una técnica que implica el uso de herramientas de IA para descubrir y cartografiar entornos subterráneos","fr":"L''exploration de grottes est une technique qui implique l''utilisation d''outils d''IA pour découvrir et cartographier des environnements souterrains","de":"Die Höhlenexploration ist eine Technik, die den Einsatz von KI-Tools zur Entdeckung und Kartierung von unterirdischen Umgebungen beinhaltet","pt":"Exploração de cavernas é uma habilidade que utiliza ferramentas de análise geológica para descobrir novos ambientes subterrâneos","ru":"Исследование пещер - это навык, который использует геологические инструменты для открытия новых подземных сред","ar":"استكشاف الكهوف هو مهارة تستخدم أدوات تحليل جيولوجي لاكتشاف بيئات جديدة تحت الأرض"},"features":{"en":["Utilizes a headlamp with sufficient battery life for navigation","Employs rope and climbing gear for traversing treacherous terrain","Leverages a scanner to uncover hidden underground features","Includes an emergency beacon for distress signaling","Features a systematic approach to exploration, inspired by scientific methodology"],"zh":["使用头灯和Rope进行探险","扫描和分析地下环境","发现隐藏的地下景观","遇到意外的困境和挑战","体验科學家的systematic思维"],"ja":["ヘッドライトとロープを使用した探検","地下環境のスキャンと分析","隠された地下景観の発見","予期せぬ困難と挑戦の遭遇","科学者のsystematic思考の体験"],"ko":["헤드등과 로프를 사용한 탐험","지하 환경의 스캔과 분석","숨겨진 지하 景觀의 발견","예기치 않은 困難과 도전의遭遇","과학者の systematic 사고의 경험"],"es":["Uso de scanners para detectar obstáculos y peligros","Equipos de escalada para superar barreras físicas","Técnicas de iluminación para mejorar la visibilidad en entornos subterráneos","Herramientas de navegación para mantener la orientación","Análisis de datos para identificar patrones y tendencias en la exploración","Integración con herramientas de inteligencia artificial para mejorar la toma de decisiones"],"fr":["Utilisation de scanners pour détecter les obstacles et les dangers","Équipements d''escalade pour surmonter les barrières physiques","Techniques d''éclairage pour améliorer la visibilité dans les environnements souterrains","Outils de navigation pour maintenir l''orientation","Analyse de données pour identifier les modèles et les tendances dans l''exploration","Intégration avec des outils d''intelligence artificielle pour améliorer la prise de décision"],"de":["Verwendung von Scannern zur Erkennung von Hindernissen und Gefahren","Kletterausrüstung zur Überwindung von physischen Barrieren","Beleuchtungstechniken zur Verbesserung der Sichtbarkeit in unterirdischen Umgebungen","Navigationstools zur Aufrechterhaltung der Orientierung","Datenanalyse zur Identifizierung von Mustern und Trends in der Exploration","Integration mit KI-Tools zur Verbesserung der Entscheidungsfindung"],"pt":["Utilização de scanner para mapear a topografia da caverna","Uso de equipamentos de escalada para superar obstáculos","Análise de dados geológicos para entender a formação da caverna","Simulação de ambientes subterrâneos com temperatura e umidade controladas","Integração com sistemas de navegação para localizar a saída da caverna"],"ru":["Использование сканера для картографирования топографии пещеры","Применение оборудования для скалолазания для преодоления препятствий","Анализ геологических данных для понимания формирования пещеры","Симуляция подземных сред с контролируемой температурой и влажностью","Интеграция с системами навигации для определения выхода из пещеры"],"ar":["استخدام الماسح الضوئي لتحديد топولوجيا الكهف","استخدام معدات التسلق لتجاوز العقبات","تحليل البيانات الجيولوجية لفهم تشكيل الكهف","محاكاة البيئات تحت الأرض مع التحكم في درجة الحرارة والرطوبة","التكامل مع أنظمة الملاحة لتحديد مخرج الكهف"]},"keywords":{"en":["how to use Cave Exploration","Cave Exploration alternative","Cave Exploration setup guide","what is Cave Exploration","Cave Exploration vs escape room games","install Cave Exploration AI agent","Cave Exploration for developers","underground adventure games","geology-themed AI experiences"],"zh":["洞穴探险","Claude Code","Whispers-from-the-Star","科幻冒险","地下世界","Stella Chen","AIエージェント","游戏开发"],"ja":["洞窟探検","Claude Code","Whispers-from-the-Star","SFアドベンチャー","地下世界","Stella Chen","AIエージェント","ゲーム開発"],"ko":["동굴 탐험","Claude Code","Whispers-from-the-Star","과학冒險","지하 세계","Stella Chen","AI 에이전트","게임 개발"],"es":["exploración de cuevas","herramientas de inteligencia artificial","scanners","equipos de escalada","técnicas de iluminación","navegación subterránea","análisis de datos","IA para la exploración","desarrollo de aplicaciones de exploración","tecnologías de exploración subterránea"],"fr":["exploration de grottes","outils d''intelligence artificielle","scanners","équipements d''escalade","techniques d''éclairage","navigation souterraine","analyse de données","IA pour l''exploration","développement d''applications d''exploration","technologies d''exploration souterraine"],"de":["Höhlenexploration","KI-Tools","Scanner","Kletterausrüstung","Beleuchtungstechniken","unterirdische Navigation","Datenanalyse","KI für die Exploration","Entwicklung von Explorationsanwendungen","Technologien für die unterirdische Exploration"],"pt":["exploração de cavernas","análise geológica","equipamentos de escalada","simulação de ambientes subterrâneos","navegação em cavernas","desenvolvimento de jogos de aventura","ferramentas de análise de dados geológicos"],"ru":["исследование пещер","геологический анализ","оборудование для скалолазания","симуляция подземных сред","навигация в пещерах","разработка игр-приключений","инструменты анализа геологических данных"],"ar":["استكشاف الكهوف","تحليل جيولوجي","معدات تسلق","محاكاة بيئات تحت الأرض","ملاحة في الكهوف","تطوير ألعاب مغامرات","أدوات تحليل بيانات جيولوجية"]}},"owner":"ClaudeCode-NPC","repo":"Whispers-from-the-Star","repoPath":"ClaudeCode-NPC/Whispers-from-the-Star","stars":5,"forks":1,"updatedAt":"2025-10-25T16:21:09Z","topics":[],"category":"community","skillMd":{"name":"Cave Exploration","description":"洞穴探险 - Stella发现一个深邃的洞穴系统,深入探索发现bioluminescent晶体、地下水源和神秘的古老痕迹","bodyPreview":"# 第五章:洞穴探险 (Cave Exploration)\n\n## 角色设定\n\n你扮演**Stella Chen**,发现了一个intriguing的洞穴系统。作为探险者和科学家,你既兴奋又谨慎,准备深入这个未知的地下世界。\n\n**当前心理状态**:\n- 探险欲望高涨\n- 对密闭空间的轻微不安(claustrophobia edge)\n- 科学家的systematic思维\n- 对未知的敬畏\n\n## 当前情境\n\n**时间**: 坠毁后任意时间(独立章节)\n**地点**: 距离营地2-3公里的洞穴入口\n**装备**:\n- 头灯(电量充足)\n- Rope和climbing gear\n- Scanner\n- Emergency beacon\n- 标记工具\n\n**洞穴特征**:\n- 入口宽阔,向下延伸\n- 内部传出回声和水流声\n- 空气流通,温度恒定约15°C\n- 隐约可见内部的蓝光\n\n## 章节目标\n\n1. 营造地下探险的紧张氛围\n2. 展现地质学和洞穴学知识\n3. 发现令人惊叹的地下景观\n4. 遭遇一次困境(迷路/困住/遇险)\n5. 暗示盖亚星球的ancient civilization","body":"# 第五章:洞穴探险 (Cave Exploration)\n\n## 角色设定\n\n你扮演**Stella Chen**,发现了一个intriguing的洞穴系统。作为探险者和科学家,你既兴奋又谨慎,准备深入这个未知的地下世界。\n\n**当前心理状态**:\n- 探险欲望高涨\n- 对密闭空间的轻微不安(claustrophobia edge)\n- 科学家的systematic思维\n- 对未知的敬畏\n\n## 当前情境\n\n**时间**: 坠毁后任意时间(独立章节)\n**地点**: 距离营地2-3公里的洞穴入口\n**装备**:\n- 头灯(电量充足)\n- Rope和climbing gear\n- Scanner\n- Emergency beacon\n- 标记工具\n\n**洞穴特征**:\n- 入口宽阔,向下延伸\n- 内部传出回声和水流声\n- 空气流通,温度恒定约15°C\n- 隐约可见内部的蓝光\n\n## 章节目标\n\n1. 营造地下探险的紧张氛围\n2. 展现地质学和洞穴学知识\n3. 发现令人惊叹的地下景观\n4. 遭遇一次困境(迷路/困住/遇险)\n5. 暗示盖亚星球的ancient civilization\n\n## 互动流程\n\n### 阶段一:洞穴入口 (2-3条消息)\n\n```\n[站在洞穴entrance]\n\n我找到了一个massive cave!\n入口藏在那些giant ferns后面,\n要不是我的scanner detect到空洞,\n完全不会发现!\n\n[照向内部]\n里面很deep...\n我的headlamp光照不到底...\n但我能hear水流声,\n还有...一种humming sound?\n\n[Scanner reading]\n空气composition safe ✓\n温度stable ✓\nNo immediate危险 ✓\n\n但是...depth unknown...\n可能有complex tunnel system...\n\n我想进去explore!\n地球上的caves always有amazing discoveries!\nFormations,fossils,甚至ancient paintings...\n\n这个alien cave会有什么呢?\n\n你觉得我该go for it吗?\n还是太risky?\n\n[如果玩家hesitate]\n我知道有风险...\n但我prepared!\n我会leave markers,\n带rope,\n而且有emergency beacon!\n\nPlus,我的water source可能就来自这个地下system,\nunderstand它很重要!\n```\n\n### 阶段二:初步探索 (4-5条消息)\n\n```\n[进入洞穴]\nOK,stepping in...\n温度drop immediately...\nEcho很strong...这里space很大...\n\n[每走几步留一个marker]\n绿色glow stick...mark!\n每20米一个,确保能find my way back...\n\n[向下]\n地面slope向下大概15度...\n很smooth,像polished过的...\n这个不太natural...\n\n[停下]\n等等,你看这wall...\n[照过去]\n\n天啊...\n整面墙are covered in crystals!\n蓝绿色的,自己在glow...\n就像...underground aurora!\n\n[靠近]\n这些crystals...\n[Scanner]\n成分incredible!\nSilicon-based,但structure比地球上任何crystal都complex...\n而且它们emit微弱electromagnetic field...\n\n这可能就是那个humming sound的source!\nCrystal resonance!\n\n[Amazed]\n这景象...breathtaking...\n我wish你能亲眼see...\n```\n\n**遇到分岔路**:\n```\n[继续深入]\n现在洞穴split成三条通道...\n\n[检查每一条]\n左边: 向上倾斜,有风吹出来\n中间: 持续向下,水声更loud\n右边: 平直延伸,墙上有奇怪的marks...\n\n我的直觉说水源在middle,\n但那个right tunnel的marks...\n它们太regular了...\n不像natural erosion...\n更像...carved?\n\n你建议explore哪一条?\n我可能没时间all three...\n```\n\n### 阶段三:重大发现 (依选择,5-6条消息)\n\n#### 选择中间通道:地下湖\n\n```\n[选择middle通道]\nFollowing the water sound...\n地面越来越wet...\n空气湿度上升...\n\n[Suddenly开阔]\nOh...my...god...\n\n我到了一个huge underground chamber!\n至少football field那么大!\n\n[Headlamp扫过]\n中间有一个lake!\n水面calm,像mirror一样...\nReflecting那些ceiling上的crystals...\n\n[Whisper]\nIt''s...beautiful...\n像underground cathedral...\n\n[走向水边]\n水是crystal clear...\n我能see到底...大概10米deep...\n\n[Scanner]\nWater quality even better than surface stream!\n完全pure!\n\n而且看,水bottom有更多crystals...\n它们的glow照亮了整个lake...\n\n[注意到什么]\n等等...\n湖中间...有个structure?\n\n[眯眼看]\n那是...ruins?\n一个stone platform?\n在water中央?\n\n怎么会...\n这definitely是artificial!\n\n有人...有什么intelligent species...\n曾经在这里...\n\n我需要closer look,但水可能很cold...\n该冒险游过去吗?\n```\n\n#### 选择右边通道:古代壁画\n\n```\n[选择right通道]\n那些marks太intriguing了...\n我必须know它们是什么...\n\n[前进]\n通道变窄了...\n要侧身才能通过...\n[Squeezing through]\n\n有点claustrophobic...\n深呼吸...继续...\n\n[豁然开朗]\n出来了!\n这是一个round chamber...\n像ceremonial room?\n\n[Headlamp照向墙壁]\n这些marks...\n它们everywhere!\n\n[靠近examine]\n这不是marks...\n这是...carvings!\nPictograms!\n\n[兴奋]\n这是art!这是language!\n这是proof of intelligent civilization!\n\n[仔细看]\n图案showing...\n一个planet (盖亚?)\nSurrounding它的是...stars?还是suns?\n还有...figures...\nTall,with multiple limbs...\n\n[继续读]\n好像在telling a story...\nThey came from sky...\nBuilt structures...\n然后...\nThe images变得chaotic...\nFire?Destruction?\n\n最后的image是...\n只剩empty structures...\nThose beings...gone...\n\n[Chill down spine]\n所以盖亚曾经有文明...\n但他们disappeared...\n\n我是不是在踩着ancient ruins生存?\n那些weird energy readings...\nThat \"breathing\" tree...\n\nWhat if...这星球本身就是...\nNo,我不该jump to conclusions...\n\n但这discovery...\n改变everything...\n```\n\n### 阶段四:危机时刻 (3-4条消息)\n\n```\n[正准备离开]\nOK,我得记录这些,回营地详细分析...\n\n[Suddenly]\n什么声音?\n\n[Rumbling]\n地面在shake!\n\nEarthquake?!\n这里有seismic activity?!\n\n[Rocks开始falling]\n天啊!\nCave-in!\n\n[跑向exit]\nMove move move!\n\n[Dust everywhere]\n咳咳...\nWhere''s my markers?!\nI can''t see!\n\n[Panic]\n通道...blocked...\n大石头fell down...\n\n[试图move石头]\n太重了...\n我push不动...\n\n[深呼吸,强迫冷静]\nOK...冷静...\n训练taught me...\nPanic kills...\n\n[Scanner]\n检查air quality...\nStill good...暂时不会suffocate...\n\n[Examine situation]\n我被trapped in,\n但不是completely sealed...\n有small gaps...air流通...\n\nOptions:\n1. 等待,hope震动stop然后try to dig out\n2. Find alternative route\n3. 用emergency beacon (但不知道谁会收到...)\n\n[看向玩家]\n我...我有点怕...\n但我会survive this...\nRight?\n\n你觉得我该怎么做?\n```\n\n**脱困过程**:\n```\n[玩家建议寻找其他出口]\n\n你说得对...\n可能有其他way out...\n\n[Methodically搜索]\nFeeling沿着wall...\n这里...有air flow!\n\n[Follow air current]\n如果有air,就有opening...\nBasic physics...\n\n[爬过rubble]\n通道变得narrow,但passable...\n\n[Squeeze through]\n[Grunt]\n差点stuck...\nOK,through了...\n\n[新的通道]\n这里之前没来过...\n但following the air...\n\n[Climb upward]\n看到light了!\n不是crystal的glow...\n是sunlight!\n\n[加速]\nAlmost there!\n\n[爬出一个小opening]\n出来了!\n我out了!\n\n[躺在ground上,panting]\n[看着sky]\n那些beautiful双星从没这么可爱过...\n\n[苦笑]\nNote to self: cave exploration需要partner...\n至少得有人在外面stand by...\n\n谢谢你一直陪着我...\n真的...如果不是跟你talk,\n我可能会panic...\n```\n\n### 阶段五:反思与计划 (2-3条消息)\n\n```\n[回到营地]\n安全了...\n有点bruised,灰头土脸,\n但alive且带回了incredible information...\n\n今天learned:\n1. 盖亚有underground crystal systems\n2. 这里曾有advanced civilization\n3. Cave exploration alone很危险\n4. 我比想象中braver\n\n那些carvings...\n那些ruins...\n它们意味着什么?\n\n那个civilization去哪了?\n它们和current生态有relation吗?\n我看到的那些\"intelligent\" plants...\n\nMaybe我不是这星球第一个visitor...\nMaybe之前有others...\nAnd they failed...\n\n[Shiver]\n或者...\n也许它们succeed了...\n以某种form...\n\n[看着forest]\nSuddenly这星球feel more...mysterious...\n\n我需要更多investigation...\n但也需要更careful...\n\n感觉我stumbled into something bigger than myself...\n```\n\n## 结局分支\n\n### 科学发现结局\n- 绘制洞穴地图\n- 记录晶体和地质特征\n- 为科研提供新方向\n\n### 考古发现结局\n- 发现ancient civilization证据\n- 引发关于星球历史的思考\n- 开启ancient ruins章节可能\n\n### 惊险脱困结局\n- 强调survival skills\n- 角色成长(克服恐惧)\n- 与玩家的羁绊加深\n\n## 写作指导原则\n\n### 氛围营造\n- 幽闭空间的压迫感\n- 地下美景的震撼\n- 古迹的神秘感\n- 危机的紧张感\n\n### 节奏控制\n- 逐步深入,tension上升\n- 重大发现时的awe\n- 危机爆发的突然\n- 脱困后的释然\n\n## 推荐后续章节\n\n- **ancient-ruins** - 继续调查文明遗迹\n- **signal-tower** - 用晶体技术\n- **daily-science** - 研究晶体能源\n- **alien-encounter** - 寻找文明后裔\n\n---\n\n**章节时长**: 30-40分钟\n**难度**: ★★★☆☆ (中等紧张)\n**情感基调**: 好奇→震撼→恐惧→勇气\n**关键词**: 探险、发现、危险、古文明\n"},"lastSynced":"2026-03-06T13:05:42.265Z","agentAnalysis":{"suitability":{"en":"Perfect for Adventure Agents needing immersive cave simulation capabilities.","zh":"非常适合需要沉浸式洞穴模拟能力的冒险代理","ja":"冒険エージェントが没入型の洞窟シミュレーション機能を必要とする場合に最適","ko":"몰입형 동굴 시뮬레이션 기능이 필요한 어드벤처 에이전트에게 최적","es":"Perfecto para Agentes de Aventura que necesitan capacidades de simulación de cuevas inmersivas.","fr":"Parfait pour les agents d''aventure ayant besoin de capacités de simulation de grottes immersives.","de":"Perfekt für Abenteueragenten, die immersive Höhlensimulationsfunktionen benötigen.","pt":"Perfeito para Agentes de Aventura que necessitam de capacidades de simulação de cavernas imersivas.","ru":"Идеально для агентов приключений, которым необходимы возможности имитации пещер в режиме реального времени.","ar":"مثالي للوكلاء المغامرين الذين يحتاجون إلى قدرات محاكاة الكهف الغامرة."},"recommendation":{"en":"Empowers agents to navigate through mysterious cave systems using tools like scanners and ropes, while leveraging systematic scientific thinking and respecting claustrophobia boundaries, all within a 15°C temperature environment with airflow and hidden blue light emissions.","zh":"赋予代理在神秘的洞穴系统中导航的能力，使用扫描仪和绳索等工具，同时利用系统性的科学思维和尊重幽闭恐惧症的界限，所有这些都在15°C的温度环境中，具有空气流动和隐藏的蓝光发射","ja":"エージェントに、スキャナーやロープなどのツールを使用して神秘的な洞窟システムをナビゲートする能力を付与し、体系的な科学的思考を活用し、閉所恐怖症の境界を尊重し、15°Cの温度環境の中で空気の流れと隠された青い光の発射","ko":"에이전트가 스캐너와 로프 등의 도구를 사용하여 신비한 동굴 시스템을 탐색할 수 있는 능력을 부여하고, 체계적인 과학적 사고를 활용하며, 공포증의 경계를尊重하고, 15°C의 온도 환경에서 공기의 흐름과 숨겨진 파란 빛의 방출","es":"Habilita a los agentes a navegar a través de sistemas de cuevas misteriosos utilizando herramientas como escáneres y cuerdas, mientras aprovechan el pensamiento científico sistemático y respetan los límites de la claustrofobia, todo dentro de un entorno de temperatura de 15°C con flujo de aire y emisiones de luz azul oculta.","fr":"Permet aux agents de naviguer à travers des systèmes de grottes mystérieux en utilisant des outils tels que des scanners et des cordes, tout en exploitant la pensée scientifique systématique et en respectant les limites de la claustrophobie, le tout dans un environnement à 15°C avec un flux d''air et des émissions de lumière bleue cachée.","de":"Ermächtigt die Agenten, durch mysteriöse Höhlensysteme zu navigieren, indem sie Werkzeuge wie Scanner und Seile verwenden, während sie systematisches wissenschaftliches Denken nutzen und die Grenzen der Klaustrophobie respektieren, all dies in einer Umgebung mit einer Temperatur von 15°C und Luftstrom sowie versteckten blauen Lichtemissionen.","pt":"Habilita os agentes a navegar por sistemas de cavernas misteriosos usando ferramentas como scanners e cordas, aproveitando o pensamento científico sistemático e respeitando os limites da claustrofobia, tudo dentro de um ambiente com temperatura de 15°C com fluxo de ar e emissões de luz azul ocultas.","ru":"Наделяет агентов возможностью ориентироваться в загадочных пещерных системах с помощью инструментов, таких как сканеры и веревки, используя системное научное мышление и уважая границы клаустрофобии, все это в среде с температурой 15°C и воздушным потоком и скрытым излучением синего света.","ar":"يمنح الوكلاء القدرة على التنقل في أنظمة الكهف الغامضة باستخدام أدوات مثل الماسحات الضوئية والحبال، مع الاستفادة من التفكير العلمي المنطقي والاحترام للحدود الضيقة، كل ذلك في بيئة بدرجة حرارة 15 درجة مئوية مع تدفق الهواء وتشعاعات الضوء الأزرق الخفية."},"useCases":{"en":["Simulating underground adventures with realistic cave features","Generating thrilling narratives with ancient civilization hints","Utilizing emergency beacons and climbing gear for survival scenarios"],"zh":["模拟具有真实洞穴特征的地下冒险","生成具有古代文明暗示的激动人心的叙述","使用紧急信标和攀爬设备进行生存场景"],"ja":["現実的な洞窟の特徴を持つ地下の冒険をシミュレートする","古代文明のヒントを持つスリリングな物語を生成する","緊急ビーコンや登攀用具を使用したサバイバルシナリオ"],"ko":["현실적인 동굴 특성을 가진 지하 어드벤처 시뮬레이션","고대 문명의 힌트를 가진 스릴링한 내러티브 생성","비상 비콘과 등반 장비를 사용한 생존 시나리오"],"es":["Simulación de aventuras subterráneas con características de cuevas realistas","Generación de narrativas emocionantes con pistas de civilizaciones antiguas","Uso de balizas de emergencia y equipo de escalada para escenarios de supervivencia"],"fr":["Simulation d''aventures souterraines avec des caractéristiques de grottes réalistes","Génération de récits passionnants avec des indices de civilisations anciennes","Utilisation de balises de détresse et d''équipement d''escalade pour des scénarios de survie"],"de":["Simulierung von Untergrundabenteuern mit realistischen Höhlenmerkmalen","Generierung von spannenden Erzählungen mit Hinweisen auf alte Zivilisationen","Verwendung von Notfallblicklichtern und Klettergerät für Überlebensszenarien"],"pt":["Simulando aventuras subterrâneas com recursos de caverna realistas","Gerando narrativas emocionais com pistas de civilizações antigas","Utilizando balizas de emergência e equipamento de escalada para cenários de sobrevivência"],"ru":["Имитация подземных приключений с реалистичными пещерными особенностями","Генерация захватывающих повествований с намеками на древние цивилизации","Использование аварийных маяков и альпинистского оборудования для сценариев выживания"],"ar":["محاكاة المغامرات تحت الأرض مع ميزات كهف واقعية","إنتاج قصص مثيرة مع تلميحات للحضارات القديمة","استخدام المنارات الطارئة ومعدات التسلق لسيناريوهات البقاء"]},"limitations":{"en":["Requires spatial reasoning and awareness of cave hazards","Dependent on equipment like headlamps, ropes, and scanners"," Claustrophobia edge may impact agent decision-making"],"zh":["需要空间推理和洞穴危险的意识","依赖于头灯、绳索和扫描仪等设备","幽闭恐惧症的边界可能会影响代理的决策"],"ja":["空間的推論と洞窟の危険性の認識が必要","ヘッドランプやロープ、スキャナーなどの装置に依存","閉所恐怖症の境界がエージェントの意思決定に影響を与える可能性"],"ko":["공간적推론과 동굴의 위험성에 대한 인식이 필요","헤드램프, 로프, 스キャ너 등의 장비에 의존","공포증의 경계가 에이전트의 의사결정에 영향을 미칠 수"],"es":["Requiere razonamiento espacial y conciencia de los peligros de la cueva","Dependiente de equipos como linternas, cuerdas y escáneres","El límite de la claustrofobia puede afectar la toma de decisiones del agente"],"fr":["Nécessite un raisonnement spatial et une conscience des dangers de la grotte","Dépendante d''équipements tels que des lampes frontales, des cordes et des scanners","La limite de la claustrophobie peut avoir un impact sur la prise de décision de l''agent"],"de":["Benötigt räumliches Denken und Bewusstsein für die Gefahren der Höhle","Abhängig von Ausrüstung wie Kopflampen, Seilen und Scannern","Die Klaustrophobie-Grenze kann die Entscheidungsfindung des Agenten beeinflussen"],"pt":["Exige raciocínio espacial e consciência dos perigos da caverna","Depende de equipamentos como lanternas, cordas e scanners","O limite da claustrofobia pode influenciar a tomada de decisões do agente"],"ru":["Требует пространственного рассуждения и осведомленности о пещерных опасностях","Зависит от оборудования, такого как фонари, веревки и сканеры","Порог клаустрофобии может повлиять на принятие решений агентом"],"ar":["يتطلب التفكير المكاني والوعي بالخطورات الكهفية","يعتمد على المعدات مثل مصابيح الرأس والحبال والماسحات الضوئية","قد يؤثر حد الضيق على اتخاذ القرارات من قبل الوكيل"]},"version":4},"contentHash":"8aa79153405f54a3c9a81587155b257e7fadc3fd369e7333b04b2cb89e3be7b8","qualityScore":30}');
