INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ClaudeCode-NPC/Whispers-from-the-Star/Cave Exploration', 'Cave Exploration', 'ClaudeCode-NPC', 'Whispers-from-the-Star', 'community', 'Cave Exploration ClaudeCode-NPC Whispers-from-the-Star community Cave Exploration is an AI-powered skill that simulates an underground adventure, where users navigate through a mysterious cave system, utilizing tools like scanners and ropes. This skill benefits developers and adventure-seekers alike. 洞穴探险是Claude Code实现的《Whispers-from-the-Star》中的一个章节，玩家扮演Stella Chen探索地下世界 洞窟探検は、Claude Codeによって実装された『Whispers-from-the-Star』の中の1章です。プレイヤーはStella Chenになり、地下世界を探検します 동굴 탐험은 Claude Code에 의해 구현된 《Whispers-from-the-Star》中的 하나의 章입니다. 플레이어는 Stella Chen이 되어地下 세계를 탐험합니다 La exploración de cuevas con herramientas de inteligencia artificial implica el uso de tecnologías como scanners y equipos de escalada para navegar en entornos subterráneos L''exploration de grottes avec des outils d''intelligence artificielle implique l''utilisation de technologies telles que des scanners et des équipements d''escalade pour naviguer dans des environnements souterrains Die Höhlenexploration mit KI-Tools umfasst den Einsatz von Technologien wie Scannern und Kletterausrüstung, um in unterirdischen Umgebungen zu navigieren Exploração de cavernas com Stella Chen, utilizando ferramentas de análise geológica e equipamentos de escalada Исследование пещер с Стелла Чен, используя геологические инструменты и оборудование для скалолазания استكشاف الكهوف مع ستела تشين، باستخدام أدوات تحليل جيولوجي ومعدات تسلق how to use Cave Exploration Cave Exploration alternative Cave Exploration setup guide what is Cave Exploration Cave Exploration vs escape room games install Cave Exploration AI agent Cave Exploration for developers underground adventure games geology-themed AI experiences 洞穴探险 Claude Code Whispers-from-the-Star 科幻冒险 地下世界 Stella Chen AIエージェント 游戏开发 Utilizes a headlamp with sufficient battery life for navigation Employs rope and climbing gear for traversing treacherous terrain Leverages a scanner to uncover hidden underground features Includes an emergency beacon for distress signaling Features a systematic approach to exploration, inspired by scientific methodology Cave Exploration is an immersive AI experience that replicates the thrill of discovering hidden underground worlds, complete with geologic formations and ancient mysteries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dreamlx/codeindex/mo-arch', 'community', 'dreamlx', 'codeindex', 'dreamlx/codeindex', 'mo-arch', 4, 1, 30, '2026-02-20T05:16:03Z', '2026-03-06T06:56:31.766Z', '6119d043d381dcdb94039ad165630bfc352593620e92410354ab74282694cfd9', '{"id":"dreamlx/codeindex/mo-arch","name":"mo-arch","description":{"en":"mo-arch is a skill that enables querying of code architecture using README_AI.md index files. It benefits developers by providing a project overview and module listings.","zh":"mo-arch 是一个代码架构查询工具，使用 README_AI.md 索引文件快速找到所需的模块和目录","ja":"mo-arch はコードアーキテクチャ検索ツールであり、README_AI.md インデックスファイルを使用して必要なモジュールとディレクトリを見つける","ko":"mo-arch는 코드 아키텍처 조회 도구로 README_AI.md 인덱스 파일을 사용하여 필요한 모듈 및 디렉토리를 빠르게 찾습니다","es":"mo-arch es una herramienta que permite consultar la arquitectura de código utilizando archivos de índice generados por codeindex","fr":"mo-arch est un outil qui permet d''interroger l''architecture de code en utilisant des fichiers d''index générés par codeindex","de":"mo-arch ist ein Tool, das es ermöglicht, die Code-Architektur mithilfe von Indexdateien abzufragen, die von codeindex generiert werden","pt":"O mo-arch é uma ferramenta que consulta a arquitetura de código de projetos com README_AI.md. Ele fornece uma visão geral do projeto e lista todos os módulos.","ru":"Mo-arch - это инструмент для запроса кодовой архитектуры проектов с помощью README_AI.md. Он предоставляет обзор проекта и перечисляет все модули.","ar":"mo-arch هو أداة لاستعلام بنية التعليمات البرمجية لمشاريع باستخدام README_AI.md. يوفر نظرة عامة على المشروع ويسرد جميع الوحدات"},"seo":{"title":{"en":"mo-arch: Code Architecture Query Setup Guide | AI Agent S...","zh":"mo-arch 代码架构查询指南","ja":"mo-arch コードアーキテクチャ検索ガイド","ko":"mo-arch 코드 아키텍처 조회 가이드","es":"Guía de Configuración de mo-arch: Arquitectura de Código","fr":"Guide de Configuration de mo-arch: Architecture de Code","de":"Setup-Leitfaden für mo-arch: Code-Architektur","pt":"Guia de Configuração do mo-arch - Arquitetura de Código","ru":"Настройка mo-arch - Инструмент для запроса кодовой архите...","ar":"دليل إعداد mo-arch - بنية التعليمات البرمجية"},"description":{"en":"Discover how to query code architecture with mo-arch. Learn to navigate project indexes and module directories with ease. Get started now!","zh":"使用 mo-arch 查询代码架构，快速找到所需的模块和目录索引","ja":"mo-arch を使用してコードアーキテクチャを検索し、必要なモジュールとディレクトリインデックスを見つける","ko":"mo-arch를 사용하여 코드 아키텍처를 조회하고 필요한 모듈 및 디렉토리 인덱스를 빠르게 찾습니다","es":"Descubre cómo utilizar mo-arch para consultar la arquitectura de código y mejorar la organización de tus proyectos","fr":"Découvrez comment utiliser mo-arch pour interroger l''architecture de code et améliorer l''organisation de vos projets","de":"Erfahren Sie, wie Sie mo-arch verwenden, um die Code-Architektur abzufragen und die Organisation Ihrer Projekte zu verbessern","pt":"Aprenda a configurar o mo-arch para consultar a arquitetura de código de seus projetos com README_AI.md","ru":"Узнайте, как настроить mo-arch для запроса кодовой архитектуры ваших проектов с помощью README_AI.md и ИИ Агентов","ar":"تعرف على كيفية إعداد mo-arch لاستعلام بنية التعليمات البرمجية لمشاريعك باستخدام README_AI.md"},"definition":{"en":"mo-arch is a code architecture query skill that utilizes README_AI.md index files generated by codeindex to provide project insights.","zh":"mo-arch 是一个代码架构查询工具，用于快速找到代码中的模块和目录索引","ja":"mo-arch はコードアーキテクチャ検索ツールであり、コード内のモジュールとディレクトリインデックスを見つけるために使用される","ko":"mo-arch는 코드 아키텍처 조회 도구로 코드 내의 모듈 및 디렉토리 인덱스를 찾는 데 사용됩니다","es":"mo-arch es una herramienta de consulta de arquitectura de código que utiliza archivos de índice para proporcionar una visión general de los módulos de un proyecto","fr":"mo-arch est un outil de consultation d''architecture de code qui utilise des fichiers d''index pour fournir une vue d''ensemble des modules d''un projet","de":"mo-arch ist ein Tool zur Abfrage der Code-Architektur, das Indexdateien verwendet, um eine Übersicht über die Module eines Projekts zu liefern","pt":"O mo-arch é uma ferramenta de consulta de arquitetura de código que utiliza arquivos README_AI.md","ru":"Mo-arch - это инструмент для запроса кодовой архитектуры, использующий файлы README_AI.md","ar":"mo-arch هو أداة لاستعلام بنية التعليمات البرمجية باستخدام ملفات README_AI.md"},"features":{"en":["Checks project index using cat PROJECT_INDEX.md command","Finds directory indexes with find . -name \"README_AI.md\" -type f command","Reads relevant module indexes based on user''s question","Utilizes README_AI.md files for module information","Supports project overview with all modules listed","Enables location of specific modules using head -10 command"],"zh":["使用 README_AI.md 索引文件查询代码架构","快速找到所需的模块和目录","支持 cat 和 find 命令行工具","可以查看项目概述和模块列表","支持头 10 个目录索引的查找"],"ja":["README_AI.md インデックスファイルを使用してコードアーキテクチャを検索","必要なモジュールとディレクトリを見つける","cat と find コマンドラインツールをサポート","プロジェクト概要とモジュールリストを表示","先頭 10 個のディレクトリインデックスの検索をサポート"],"ko":["README_AI.md 인덱스 파일을 사용하여 코드 아키텍처를 조회","필요한 모듈 및 디렉토리를 빠르게 찾습니다","cat 및 find 명령줄 도구를 지원","프로젝트 개요 및 모듈 목록을 표시","최초 10개의 디렉토리 인덱스의 조회를 지원"],"es":["Consulta de arquitectura de código utilizando archivos de índice","Generación de archivos de índice con codeindex","Búsqueda de directorios y módulos relevantes","Lectura de archivos README_AI.md para obtener información detallada","Compatibilidad con comandos de línea de comandos como find y cat"],"fr":["Interrogation de l''architecture de code en utilisant des fichiers d''index","Génération de fichiers d''index avec codeindex","Recherche de répertoires et de modules pertinents","Lecture de fichiers README_AI.md pour obtenir des informations détaillées","Compatibilité avec des commandes de ligne de commande comme find et cat"],"de":["Abfrage der Code-Architektur mithilfe von Indexdateien","Generierung von Indexdateien mit codeindex","Suche nach Verzeichnissen und relevanten Modulen","Lesen von README_AI.md-Dateien für detaillierte Informationen","Kompatibilität mit Befehlszeilenbefehlen wie find und cat"],"pt":["Consulta a arquitetura de código de projetos com README_AI.md","Fornece uma visão geral do projeto e lista todos os módulos","Utiliza comandos CLI para localizar e ler arquivos README_AI.md","Permite a pesquisa de módulos específicos com base em perguntas do usuário","Suporta a indexação de projetos com arquivos PROJECT_INDEX.md"],"ru":["Запрос кодовой архитектуры проектов с помощью README_AI.md","Предоставляет обзор проекта и перечисляет все модули","Использует команды CLI для поиска и чтения файлов README_AI.md","Позволяет искать конкретные модули на основе вопросов пользователя","Поддерживает индексацию проектов с файлами PROJECT_INDEX.md и ИИ Агентами"],"ar":["استعلام بنية التعليمات البرمجية لمشاريع باستخدام README_AI.md","يوفر نظرة عامة على المشروع ويسرد جميع الوحدات","يستخدم أوامر CLI للعثور على ملفات README_AI.md وقراءتها","يسمح بالبحث عن وحدات محددة بناءً على أسئلة المستخدم","يدعم فهرسة المشاريع باستخدام ملفات PROJECT_INDEX.md"]},"keywords":{"en":["how to use mo-arch","what is mo-arch","mo-arch alternative","mo-arch vs codeindex","mo-arch install","mo-arch setup guide","code architecture query","README_AI.md index files","project index navigation"],"zh":["mo-arch","代码架构查询","README_AI.md","cat 命令","find 命令","代码索引","模块查询","目录索引","AI 代码工具","代码架构搜索"],"ja":["mo-arch","コードアーキテクチャ検索","README_AI.md","cat コマンド","find コマンド","コードインデックス","モジュール検索","ディレクトリインデックス","AI コードツール","コードアーキテクチャ検索"],"ko":["mo-arch","코드 아키텍처 조회","README_AI.md","cat 명령","find 명령","코드 인덱스","모듈 조회","디렉토리 인덱스","AI 코드 도구","코드 아키텍처 검색"],"es":["herramientas de arquitectura de código","codeindex","README_AI.md","consulta de arquitectura de código","organización de proyectos","desarrollo de software","Agente de IA","Herramientas de desarrollo"],"fr":["outils d''architecture de code","codeindex","README_AI.md","interrogation de l''architecture de code","organisation de projets","développement de logiciels","Agent IA","Outils de développement"],"de":["Code-Architektur-Tools","codeindex","README_AI.md","Abfrage der Code-Architektur","Projektorganisation","Software-Entwicklung","KI-Agent","Entwicklertools"],"pt":["mo-arch","arquitetura de código","README_AI.md","consulta de código","ferramenta de desenvolvimento","CLI","indexação de projetos","desenvolvimento de software"],"ru":["mo-arch","кодовая архитектура","README_AI.md","запрос кода","инструмент для разработки","CLI","индексация проектов","разработка программного обеспечения","ИИ Агенты"],"ar":["mo-arch","بنية التعليمات البرمجية","README_AI.md","استعلام التعليمات البرمجية","أداة تطوير","CLI","فهرسة المشاريع","تطوير البرمجيات"]}},"owner":"dreamlx","repo":"codeindex","repoPath":"dreamlx/codeindex","stars":4,"forks":1,"updatedAt":"2026-02-20T05:16:03Z","topics":[],"category":"community","skillMd":{"name":"mo-arch","description":"Query code architecture using README_AI.md index files. Use when user asks about project structure, where features are implemented, how modules work, or wants to understand codebase architecture. Triggered by questions like what does this do, where is X implemented, how does module Y work.","bodyPreview":"# mo-arch - Code Architecture Query\n\nQuery code architecture using README_AI.md index files generated by codeindex.\n\n## Workflow\n\n### Step 1: Check Project Index\n\n```bash\ncat PROJECT_INDEX.md 2>/dev/null\n```\n\nIf exists, this gives you the project overview with all modules listed.\n\n### Step 2: Find Directory Indexes\n\n```bash\nfind . -name \"README_AI.md\" -type f | head -10\n```\n\n### Step 3: Read Relevant Module Index\n\nBased on user''s question, locate the relevant module and read its README_AI.md:\n\n`","body":"# mo-arch - Code Architecture Query\n\nQuery code architecture using README_AI.md index files generated by codeindex.\n\n## Workflow\n\n### Step 1: Check Project Index\n\n```bash\ncat PROJECT_INDEX.md 2>/dev/null\n```\n\nIf exists, this gives you the project overview with all modules listed.\n\n### Step 2: Find Directory Indexes\n\n```bash\nfind . -name \"README_AI.md\" -type f | head -10\n```\n\n### Step 3: Read Relevant Module Index\n\nBased on user''s question, locate the relevant module and read its README_AI.md:\n\n```bash\n# Example: user asks about parser\ncat src/parser/README_AI.md\n```\n\n### Step 4: Trace Dependencies\n\nCheck the **Consumes** and **Provides** sections in README_AI.md to understand module relationships.\n\n### Step 5: Deep Dive (if needed)\n\nOnly read actual source files when README_AI.md doesn''t have enough detail.\n\n## Response Format\n\nWhen answering architecture questions:\n\n1. **Start with the module location** - \"The parser is in `src/codeindex/parser.py`\"\n2. **Explain its purpose** - From the Purpose section\n3. **Show relationships** - From Consumes/Provides\n4. **Provide code reference** - Line numbers if relevant\n\n## Example\n\n**User**: \"Where is the parser implemented?\"\n\n**Response**:\n```\nBased on README_AI.md, the parser is in `src/codeindex/parser.py`.\n\n**Purpose**: Tree-sitter based Python parser that extracts Symbol\n(classes, functions, methods) and Import statements into ParseResult.\n\n**Key exports**:\n- `parse_file()` - Parse a single Python file\n- `ParseResult` - Container for parsed data\n- `Symbol` - Represents a code symbol\n\n**Dependencies**: tree-sitter, tree-sitter-python\n```\n\n## When No Index Exists\n\nIf README_AI.md files don''t exist, suggest:\n\n```\nThis directory is not indexed. Run:\n  codeindex scan ./path/to/dir\n\nOr for the entire project:\n  codeindex list-dirs | xargs -P 4 -I {} codeindex scan {}\n  codeindex index\n```\n"},"lastSynced":"2026-03-06T06:56:31.766Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing comprehensive project overviews and module listings using README_AI.md index files.","zh":"适用于需要对项目进行全面概述和模块列表的代码分析代理，使用README_AI.md索引文件。","ja":"コード分析エージェントが包括的なプロジェクトの概要とモジュールのリストを必要とする場合に適しています。README_AI.mdインデックスファイルを使用します。","ko":"코드 분석 에이전트가 포괄적인 프로젝트 개요와 모듈 목록을 필요로 할 때 적합합니다. README_AI.md 인덱스 파일을 사용합니다.","es":"Perfecto para agentes de análisis de código que necesitan una visión general integral del proyecto y listados de módulos utilizando archivos de índice README_AI.md.","fr":"Parfait pour les agents d''analyse de code nécessitant une vue d''ensemble complète du projet et des listes de modules à l''aide de fichiers d''index README_AI.md.","de":"Perfekt für Code-Analyse-Agenten, die eine umfassende Projektübersicht und Modullisten mit Hilfe von README_AI.md-Indexdateien benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de visões gerais abrangentes do projeto e listas de módulos usando arquivos de índice README_AI.md.","ru":"Идеально подходит для агентов анализа кода, которым требуются комплексные обзоры проекта и перечни модулей с использованием файлов индекса README_AI.md.","ar":"مثالي للوكلاء الذين يحتاجون إلى نظرة عامة شاملة على المشروع وقائمة الوحدات باستخدام ملفات الفهرس README_AI.md."},"recommendation":{"en":"Empowers agents to query code architecture using README_AI.md index files generated by codeindex, providing a project overview and module listings through commands like `cat PROJECT_INDEX.md` and `find . -name ''README_AI.md'' -type f`.","zh":"赋予代理查询代码架构的能力，使用codeindex生成的README_AI.md索引文件，通过命令如`cat PROJECT_INDEX.md`和`find . -name ''README_AI.md'' -type f`提供项目概述和模块列表。","ja":"コードインデックスによって生成されたREADME_AI.mdインデックスファイルを使用して、コードアーキテクチャをクエリできるようにエージェントをEmpowerします。`cat PROJECT_INDEX.md`や`find . -name ''README_API.md'' -type f`のようなコマンドを介してプロジェクトの概要とモジュールのリストを提供します。","ko":"에이전트가 코드 아키텍처를 쿼리할 수 있도록 하며, codeindex로 생성된 README_AI.md 인덱스 파일을 사용하여 `cat PROJECT_INDEX.md` 및 `find . -name ''README_AI.md'' -type f`와 같은 명령을 통해 프로젝트 개요와 모듈 목록을 제공합니다.","es":"Habilita a los agentes a consultar la arquitectura del código mediante archivos de índice README_AI.md generados por codeindex, proporcionando una visión general del proyecto y listados de módulos a través de comandos como `cat PROJECT_INDEX.md` y `find . -name ''README_AI.md'' -type f`.","fr":"Permet aux agents d''interroger l''architecture du code à l''aide de fichiers d''index README_AI.md générés par codeindex, fournissant une vue d''ensemble du projet et des listes de modules via des commandes comme `cat PROJECT_INDEX.md` et `find . -name ''README_AI.md'' -type f`.","de":"Ermächtigt Agenten, die Code-Architektur mithilfe von README_AI.md-Indexdateien zu abfragen, die von codeindex generiert werden, und bietet eine Projektübersicht und Modullisten durch Befehle wie `cat PROJECT_INDEX.md` und `find . -name ''README_AI.md'' -type f`.","pt":"Habilita os agentes a consultar a arquitetura do código usando arquivos de índice README_AI.md gerados pelo codeindex, fornecendo uma visão geral do projeto e listas de módulos por meio de comandos como `cat PROJECT_INDEX.md` e `find . -name ''README_AI.md'' -type f`.","ru":"Предоставляет агентам возможность запрашивать архитектуру кода с использованием файлов индекса README_AI.md, сгенерированных codeindex, обеспечивая обзор проекта и перечни модулей через команды như `cat PROJECT_INDEX.md` и `find . -name ''README_AI.md'' -type f`.","ar":"يمنح الوكلاء إمكانية استفسار هيكل الكود باستخدام ملفات الفهرس README_AI.md التي تم إنشاؤها بواسطة codeindex، وتوفير نظرة عامة على المشروع وقائمة الوحدات من خلال أوامر مثل `cat PROJECT_INDEX.md` و `find . -name ''README_AI.md'' -type f`."},"useCases":{"en":["Querying project structures","Listing module dependencies","Generating project documentation"],"zh":["查询项目结构","列出模块依赖","生成项目文档"],"ja":["プロジェクト構造の照会","モジュールの依存関係のリスト","プロジェクトドキュメントの生成"],"ko":["프로젝트 구조 쿼리","모듈 종속성 목록","프로젝트 문서 생성"],"es":["Consulta de estructuras de proyecto","Listado de dependencias de módulos","Generación de documentación de proyecto"],"fr":["Interrogation de structures de projet","Listage de dépendances de modules","Génération de documentation de projet"],"de":["Abfrage von Projektstrukturen","Auflistung von Modulabhängigkeiten","Erstellung von Projektdokumentation"],"pt":["Consultar estruturas de projeto","Listar dependências de módulos","Gerar documentação de projeto"],"ru":["Запрос структуры проекта","Перечисление зависимостей модулей","Генерация документации проекта"],"ar":["استعلام هيكل المشروع","قائمة зависимости الوحدات","генерация وثائق المشروع"]},"limitations":{"en":["Requires existence of README_AI.md index files","Dependent on codeindex for index file generation","Limited to projects with accessible file system"],"zh":["需要README_AI.md索引文件存在","依赖于codeindex进行索引文件生成","仅限于具有可访问文件系统的项目"],"ja":["README_AI.mdインデックスファイルの存在が必要","インデックスファイルの生成にcodeindexに依存","アクセス可能なファイルシステムを持つプロジェクトに限定"],"ko":["README_AI.md 인덱스 파일의 존재가 필요","인덱스 파일 생성에 codeindex에 의존","접근 가능한 파일 시스템을 갖는 프로젝트로 제한"],"es":["Requiere la existencia de archivos de índice README_AI.md","Dependiente de codeindex para la generación de archivos de índice","Limitado a proyectos con sistema de archivos accesible"],"fr":["Nécessite l''existence de fichiers d''index README_AI.md","Dépendant de codeindex pour la génération de fichiers d''index","Limité à des projets avec un système de fichiers accessible"],"de":["Erfordert die Existenz von README_AI.md-Indexdateien","Abhängig von codeindex für die Indexdateigenerierung","Eingeschränkt auf Projekte mit zugänglichem Dateisystem"],"pt":["Exige a existência de arquivos de índice README_AI.md","Depende do codeindex para geração de arquivos de índice","Limitado a projetos com sistema de arquivos acessível"],"ru":["Требует существования файлов индекса README_AI.md","Зависит от codeindex для генерации файлов индекса","Ограничен проектами с доступной файловой системой"],"ar":["يتطلب وجود ملفات فهرس README_AI.md","يعتمد على codeindex لإنشاء ملفات الفهرس","محدود بمشاريع نظام الملفات المتاح"]},"version":4},"contentHash":"6119d043d381dcdb94039ad165630bfc352593620e92410354ab74282694cfd9","qualityScore":30}');
