INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dreamlx/codeindex/mo-arch', 'mo-arch', 'dreamlx', 'codeindex', 'community', 'mo-arch dreamlx codeindex community mo-arch is a skill that enables querying of code architecture using README_AI.md index files. It benefits developers by providing a project overview and module listings. mo-arch 是一个代码架构查询工具，使用 README_AI.md 索引文件快速找到所需的模块和目录 mo-arch はコードアーキテクチャ検索ツールであり、README_AI.md インデックスファイルを使用して必要なモジュールとディレクトリを見つける mo-arch는 코드 아키텍처 조회 도구로 README_AI.md 인덱스 파일을 사용하여 필요한 모듈 및 디렉토리를 빠르게 찾습니다 mo-arch es una herramienta que permite consultar la arquitectura de código utilizando archivos de índice generados por codeindex mo-arch est un outil qui permet d''interroger l''architecture de code en utilisant des fichiers d''index générés par codeindex mo-arch ist ein Tool, das es ermöglicht, die Code-Architektur mithilfe von Indexdateien abzufragen, die von codeindex generiert werden O mo-arch é uma ferramenta que consulta a arquitetura de código de projetos com README_AI.md. Ele fornece uma visão geral do projeto e lista todos os módulos. Mo-arch - это инструмент для запроса кодовой архитектуры проектов с помощью README_AI.md. Он предоставляет обзор проекта и перечисляет все модули. mo-arch هو أداة لاستعلام بنية التعليمات البرمجية لمشاريع باستخدام README_AI.md. يوفر نظرة عامة على المشروع ويسرد جميع الوحدات how to use mo-arch what is mo-arch mo-arch alternative mo-arch vs codeindex mo-arch install mo-arch setup guide code architecture query README_AI.md index files project index navigation mo-arch 代码架构查询 README_AI.md cat 命令 find 命令 代码索引 模块查询 目录索引 AI 代码工具 代码架构搜索 Checks project index using cat PROJECT_INDEX.md command Finds directory indexes with find . -name "README_AI.md" -type f command Reads relevant module indexes based on user''s question Utilizes README_AI.md files for module information Supports project overview with all modules listed Enables location of specific modules using head -10 command mo-arch is a code architecture query skill that utilizes README_AI.md index files generated by codeindex to provide project insights.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TokenBrice/stablecoin-dashboard/resilience-classify', 'community', 'TokenBrice', 'stablecoin-dashboard', 'TokenBrice/stablecoin-dashboard', 'resilience-classify', 3, 1, 30, '2026-02-27T20:35:50Z', '2026-03-06T07:01:48.813Z', '30327626c39955f2f1711b1adb5a0bfc936426ed438911cdccfa62fa318d55d3', '{"id":"TokenBrice/stablecoin-dashboard/resilience-classify","name":"resilience-classify","description":{"en":"The resilience-classify skill identifies stablecoins with incorrect default inferences and applies overrides for accurate tracking. This skill benefits developers working with stablecoin dashboards and liquidity pools.","zh":"稳健性分类AI工具用于识别稳定币的正确分类，通过对默认推理的覆盖","ja":"レジリエンス分類AIツールは、安定した通貨の正しい分類を特定するために、デフォルトの推論を上書きする","ko":"탄력성 분류 AI 도구는 안정된 통화의 올바른 분류를 식별하기 위해 기본적 추론을 덮어씀","es":"Resilience-classify es una habilidad que identifica stablecoins con inferencia incorrecta y aplica reglas de inferencia personalizadas. Se utiliza para auditar puntuaciones de resistencia y garantizar la precisión.","fr":"Resilience-classify est une compétence qui identifie les stablecoins avec inférence incorrecte et applique des règles d''inférence personnalisées. Elle est utilisée pour auditer les scores de résilience et garantir la précision.","de":"Resilience-classify ist eine Fähigkeit, die Stablecoins mit falscher Inferenz identifiziert und benutzerdefinierte Inferenzregeln anwendet. Sie wird verwendet, um Widerstandsbewertungen zu überprüfen und die Genauigkeit zu gewährleisten.","pt":"O resilience-classify é uma habilidade que identifica stablecoins onde a inferência padrão está incorreta e aplica substituições. Utiliza regras de inferência padrão do arquivo src/lib/stablecoins.ts","ru":"Resilience-classify - это навык, который идентифицирует стейблкоины, где стандартная инференция неверна, и применяет переопределения. Использует стандартные правила инференции из файла src/lib/stablecoins.ts","ar":"أداة الذكاء الاصطناعي resilience-classify هي مهارة تحدد الاستقرار العملات حيث الإستنتاج الافتراضي غير صحيح وتطبق الإستبدالات. تستخدم قواعد الإستنتاج الإفتراضي من الملف src/lib/stablecoins.ts"},"seo":{"title":{"en":"resilience-classify: Stablecoin Resilience Classification...","zh":"AIエージェント：稳健性分类设置指南","ja":"AIエージェント：レジリエンス分類のベストプラクティス","ko":"AI 에이전트: 탄력성 분류 설정 가이드","es":"Guía de configuración de resilience-classify para stablec...","fr":"Guide de mise en œuvre de resilience-classify pour les st...","de":"Einrichtungsleitfaden für resilience-classify bei Stablec...","pt":"Guia de Configuração do resilience-classify para Establec...","ru":"ИИ Агенты: Настройка resilience-classify для Стейблкоинов","ar":"دليل إعداد أداة الذكاء الاصطناعي resilience-classify لاست..."},"description":{"en":"Discover how to implement resilience-classify for accurate stablecoin tracking. Learn to override default inferences and improve resilience scores with this ...","zh":"了解稳健性分类AI工具的技术细节，用于识别稳定币的正确分类","ja":"レジリエンス分類AIツールの技術的側面を知る、正しい分類のための安定した通貨","ko":"탄력성 분류 AI 도구의 기술적 세부 사항을 알아보세요. 안정된 통화의 올바른 분류를 위한","es":"Aprende a utilizar resilience-classify para identificar stablecoins con inferencia incorrecta y aplicar reglas de inferencia personalizadas","fr":"Découvrez comment utiliser resilience-classify pour identifier les stablecoins avec inférence incorrecte et appliquer des règles d''inférence personnalisées","de":"Erfahren Sie, wie Sie resilience-classify verwenden, um Stablecoins mit falscher Inferenz zu identifizieren und benutzerdefinierte Inferenzregeln anzuwenden","pt":"Aprenda a utilizar o resilience-classify para identificar e classificar stablecoins com precisão, melhorando a análise de risco","ru":"Узнайте, как настроить и использовать resilience-classify для идентификации и классификации стейблкоинов с высокой точностью","ar":"تعرف على كيفية استخدام أداة الذكاء الاصطناعي resilience-classify لتحديد وتصنيف الاستقرار العملات ب精度 عالية"},"definition":{"en":"resilience-classify is a skill that classifies stablecoins based on their resilience, identifying cases where default inferences are incorrect and applying overrides for improved accuracy.","zh":"稳健性分类是指识别稳定币的正确分类，通过对默认推理的覆盖","ja":"レジリエンス分類とは、安定した通貨の正しい分類を特定すること","ko":"탄력성 분류란 안정된 통화의 올바른 분류를 식별하는 것","es":"Resilience-classify es una habilidad de clasificación que identifica stablecoins con inferencia incorrecta","fr":"Resilience-classify est une compétence de classification qui identifie les stablecoins avec inférence incorrecte","de":"Resilience-classify ist eine Klassifizierungsfähigkeit, die Stablecoins mit falscher Inferenz identifiziert","pt":"O que é resilience-classify? É uma habilidade que classifica stablecoins com base em regras de inferência padrão","ru":"Что такое resilience-classify? Это навык, который классифицирует стейблкоины на основе стандартных правил инференции","ar":"ما هي أداة الذكاء الاصطناعي resilience-classify؟ هي مهارة تصنف الاستقرار العملات بناءً على قواعد الإستنتاج الإفتراضي"},"features":{"en":["Identifies stablecoin candidates from src/lib/stablecoins.ts","Applies default inference rules using inferResilienceDefaults()","Overrides default inferences for accurate resilience scores","Reads coin data from stablecoins.ts for classification","Invoked after resilience types and default inference implementation","Supports auditing resilience scores for accuracy"],"zh":["识别候选稳定币","应用默认推理规则","覆盖默认推理","集成到Pharos Watch稳定币仪表板","使用src/lib/stablecoins.ts读取稳定币数据"],"ja":["候補安定した通貨の特定","デフォルトの推論ルールの適用","デフォルトの推論を上書き","Pharos Watch安定した通貨ダッシュボードへの統合","src/lib/stablecoins.tsを使用して安定した通貨データを読み取る"],"ko":["후보 안정된 통화 식별","기본적 추론 규칙 적용","기본적 추론 덮어씀","Pharos Watch 안정된 통화 대시보드로 통합","src/lib/stablecoins.ts 사용하여 안정된 통화 데이터 읽기"],"es":["Identificación de stablecoins con inferencia incorrecta","Aplicación de reglas de inferencia personalizadas","Uso de la función inferResilienceDefaults()","Lectura de monedas desde src/lib/stablecoins.ts","Integración con la tabla de seguimiento de stablecoins","Soporte para auditorías de puntuaciones de resistencia"],"fr":["Identification de stablecoins avec inférence incorrecte","Application de règles d''inférence personnalisées","Utilisation de la fonction inferResilienceDefaults()","Lecture de monnaies depuis src/lib/stablecoins.ts","Intégration avec le tableau de suivi des stablecoins","Prise en charge des audits de scores de résilience"],"de":["Identifizierung von Stablecoins mit falscher Inferenz","Anwendung benutzerdefinierter Inferenzregeln","Verwendung der Funktion inferResilienceDefaults()","Lesevorgang für Münzen aus src/lib/stablecoins.ts","Integration mit der Tabelle zur Verfolgung von Stablecoins","Unterstützung für die Überprüfung von Widerstandsbewertungen"],"pt":["Identificação de stablecoins com inferência padrão incorreta","Aplicação de substituições para stablecoins específicos","Utilização de regras de inferência padrão do arquivo src/lib/stablecoins.ts","Integração com a dashboard do Pharos Watch","Análise de risco para stablecoins","Classificação de stablecoins com base em liquidez e governança"],"ru":["Идентификация стейблкоинов с неверной стандартной инференцией","Применение переопределений для конкретных стейблкоинов","Использование стандартных правил инференции из файла src/lib/stablecoins.ts","Интеграция с панелью управления Pharos Watch","Анализ риска для стейблкоинов","Классификация стейблкоинов на основе ликвидности и управления"],"ar":["تحديد الاستقرار العملات مع الإستنتاج الافتراضي غير الصحيح","تطبيق الإستبدالات للاستقرار العملات النوعية","استخدام قواعد الإستنتاج الإفتراضي من الملف src/lib/stablecoins.ts","التكامل مع لوحة التحكم في Pharos Watch","تحليل المخاطر للاستقرار العملات","تصنيف الاستقرار العملات بناءً على السيولة والإدارة"]},"keywords":{"en":["how to use resilience-classify","resilience-classify setup guide","stablecoin resilience classification","resilience-classify alternative","resilience-classify vs stablecoin tracker","resilience-classify install","what is resilience-classify","resilience-classify for liquidity pools","resilience-classify for stablecoin dashboards"],"zh":["AI工具","稳健性分类","稳定币","默认推理","覆盖默认推理","Pharos Watch","src/lib/stablecoins.ts","安定した通貨分类"],"ja":["AIエージェント","レジリエンス分類","安定した通貨","デフォルトの推論","デフォルトの推論を上書き","Pharos Watch","src/lib/stablecoins.ts","安定した通貨分类"],"ko":["AI 에이전트","탄력성 분류","안정된 통화","기본적 추론","기본적 추론 덮어씀","Pharos Watch","src/lib/stablecoins.ts","안정된 통화 분류"],"es":["resilience-classify","stablecoins","inferencia incorrecta","reglas de inferencia personalizadas","auditoría de puntuaciones de resistencia","Herramientas de AI para stablecoins","Agente de clasificación de stablecoins","Guía de configuración de resilience-classify"],"fr":["resilience-classify","stablecoins","inférence incorrecte","règles d''inférence personnalisées","audit de scores de résilience","Outils d''IA pour les stablecoins","Agent de classification de stablecoins","Guide de mise en œuvre de resilience-classify"],"de":["resilience-classify","Stablecoins","falsche Inferenz","benutzerdefinierte Inferenzregeln","Überprüfung von Widerstandsbewertungen","AI-Tools für Stablecoins","Klassifizierungsagent für Stablecoins","Einrichtungsleitfaden für resilience-classify"],"pt":["resilience-classify","stablecoins","inferência padrão","análise de risco","liquidez","governança","Pharos Watch","dashboard de stablecoins","classificação de stablecoins"],"ru":["resilience-classify","стейблкоины","стандартная инференция","анализ риска","ликвидность","управление","Pharos Watch","панель управления стейблкоинами","классификация стейблкоинов"],"ar":["أداة الذكاء الاصطناعي resilience-classify","الاستقرار العملات","الإستنتاج الإفتراضي","تحليل المخاطر","السيولة","الإدارة","Pharos Watch","لوحة التحكم في الاستقرار العملات","تصنيف الاستقرار العملات"]}},"owner":"TokenBrice","repo":"stablecoin-dashboard","repoPath":"TokenBrice/stablecoin-dashboard","stars":3,"forks":1,"updatedAt":"2026-02-27T20:35:50Z","topics":["analytics","depeg","liquidity-pool","stablecoin","stablecoins"],"category":"community","skillMd":{"name":"resilience-classify","description":"Research and classify stablecoins for resilience sub-factor overrides (chainTier, deploymentModel, collateralQuality, custodyModel). Run after types/defaults are implemented to identify coins needing explicit overrides.","bodyPreview":"# Resilience Classification Skill\n\nIdentify stablecoins where the default inference (from backing + governance) is incorrect and apply overrides.\n\n## When to Invoke\n\n- After the resilience types and default inference are implemented\n- When a new stablecoin is added to the tracker\n- When auditing resilience scores for accuracy\n\n## Process\n\n### Step 1 — Identify candidates\n\nRead all coins from `src/lib/stablecoins.ts`. For each, apply the default inference rules (see `inferResilienceDefaults()` in","body":"# Resilience Classification Skill\n\nIdentify stablecoins where the default inference (from backing + governance) is incorrect and apply overrides.\n\n## When to Invoke\n\n- After the resilience types and default inference are implemented\n- When a new stablecoin is added to the tracker\n- When auditing resilience scores for accuracy\n\n## Process\n\n### Step 1 — Identify candidates\n\nRead all coins from `src/lib/stablecoins.ts`. For each, apply the default inference rules (see `inferResilienceDefaults()` in `src/lib/report-cards.ts`). Flag coins where the default is likely wrong based on:\n\n- `collateral` text containing keywords: \"Solana\", \"tBTC\", \"WBTC\", \"delta-neutral\", \"perpetual\", \"CEX\", \"off-exchange\", \"Copper\", \"Ceffu\", \"Fireblocks\", \"bridged\"\n- `pegMechanism` text containing: \"Solana\", \"Bitcoin L2\", \"not Ethereum\", \"Tron\"\n- `contracts[]` listing only non-Ethereum chains\n- `contracts[]` listing multiple chains (candidate for `deploymentModel` override)\n- `backing` = `crypto-backed` but collateral text mentions RWAs, bridges, or exotic strategies\n- Coins on this known-override list: HYUSD, USDe, meUSD, USDD, sUSD (Synthetix), USDJ, BOLD, rwaUSDi, satUSD\n- `collateral` or `pegMechanism` text mentioning: \"LayerZero\", \"OFT\", \"CCIP\", \"Wormhole\", \"Axelar\", \"multichain\", \"cross-chain\"\n\n### Step 2 — Research each candidate\n\nFor each flagged coin, in parallel:\n- `WebFetch` official docs for collateral composition, custody arrangement, and chain architecture\n- `WebSearch` for `\"{coin name}\" stablecoin collateral custody chain` to find independent analysis\n- Cross-reference with existing `collateral` and `pegMechanism` text fields\n\n### Step 3 — Classify\n\nFor each coin, determine the correct tier:\n\n| Sub-factor | Question | Tiers |\n|---|---|---|\n| `chainTier` | Where does the core protocol live and where is collateral held? | `ethereum` (100), `stage1-l2` (66), `established-alt-l1` (20), `unproven` (0) |\n| `deploymentModel` | How does the token extend to other chains? | `single-chain` (×1.0), `canonical-bridge` (×0.85), `third-party-bridge` (×0.60), `native-multichain` (×0.40) |\n| `collateralQuality` | What are the trust assumptions in backing assets? | `native` (100), `eth-lst` (66), `rwa` (50), `alt-lst-bridged-or-mixed` (20), `exotic` (0) |\n| `custodyModel` | Who holds the collateral and can it be verified on-chain? | `onchain` (100), `institutional` (50), `cex` (0) |\n\n**Classification rules:**\n- **chainTier**: Based on where the protocol''s smart contracts and collateral vaults live, NOT where the token is bridged to\n- **deploymentModel**: Use the decision tree:\n  ```\n  Can the protocol mint/redeem on >1 chain independently?\n    YES → native-multichain\n    NO → Is the token on >1 chain?\n      NO → single-chain\n      YES → Does cross-chain transfer use the L2''s canonical rollup bridge?\n        YES → canonical-bridge\n        NO → third-party-bridge (CCIP, LayerZero, Wormhole, etc.)\n  ```\n- **collateralQuality**: For mixed collateral, use the tier of the riskiest significant component (>15% of backing). Stablecoin portions don''t count here (handled by dependency risk)\n- **custodyModel**: If ANY significant portion is held off-chain by a non-institutional custodian, classify as `cex`\n- When uncertain between two tiers, choose the riskier (lower score) tier\n\n### Step 4 — Present findings\n\nFor each coin needing an override, present:\n\n```\n## {Name} ({Symbol}) — ID: {id}\n\n### Default inference\n- chainTier: {inferred} — {correct/wrong because...}\n- deploymentModel: {inferred} — {correct/wrong because...}\n- collateralQuality: {inferred} — {correct/wrong because...}\n- custodyModel: {inferred} — {correct/wrong because...}\n\n### Proposed overrides\n- {field}: {value} — {justification with source URL}\n\n### No override needed\n- {fields where default is correct}\n```\n\n### Step 5 — Apply\n\nAfter user approval, edit `src/lib/stablecoins.ts` to add only the override fields that differ from defaults. Example:\n\n```typescript\nusd(\"123\", \"Example\", \"EX\", \"crypto-backed\", \"decentralized\", {\n  // ... existing fields ...\n  chainTier: \"established-alt-l1\",\n  deploymentModel: \"third-party-bridge\",\n  collateralQuality: \"alt-lst-bridged-or-mixed\",\n}),\n```\n\nRun `npm run build` to verify.\n"},"lastSynced":"2026-03-06T07:01:48.813Z","agentAnalysis":{"suitability":{"en":"Perfect for Financial Analysis Agents needing accurate stablecoin tracking and override capabilities.","zh":"非常适合需要准确的稳定币跟踪和覆盖能力的金融分析代理。","ja":"金融分析エージェントが正確な安定したコインの追跡とオーバーライドの機能を必要とする場合に最適です。","ko":"정확한 안정된 코인 추적 및 오버라이드 기능이 필요한 금융 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de análisis financiero que necesitan un seguimiento preciso de stablecoins y capacidades de anulación.","fr":"Parfait pour les agents d''analyse financière nécessitant un suivi précis des stablecoins et des capacités de substitution.","de":"Perfekt für Finanzanalyse-Agenten, die ein genaues Stablecoin-Tracking und Überschreibungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise Financeira que necessitam de rastreamento de stablecoins preciso e capacidades de substituição.","ru":"Идеально для финансовых аналитических агентов, которым требуются точное отслеживание стейблкоинов и возможности переопределения.","ar":"مثالي لعمليات تحليل مالية تتطلب تتبعًا دقيقًا للعملات المستقرة وقدرات الإغراق."},"recommendation":{"en":"Empowers agents to identify stablecoins with incorrect default inferences and apply overrides for precise tracking, utilizing libraries like `src/lib/stablecoins.ts` and implementing default inference rules from `inferResilienceDefaults()`.","zh":"赋予代理识别具有不正确默认推理的稳定币并应用覆盖以实现精确跟踪的能力，利用诸如 `src/lib/stablecoins.ts` 的库，并从 `inferResilienceDefaults()` 实现默认推理规则。","ja":"エージェントが不正確なデフォルトの推論を持つ安定したコインを識別し、精確な追跡のためにオーバーライドを適用する機能を提供します。`src/lib/stablecoins.ts` などのライブラリを使用し、`inferResilienceDefaults()` からデフォルトの推論ルールを実装します。","ko":"에이전트가 부정확한 기본 추론을 가진 안정된 코인을 식별하고 정확한 추적을 위해 오버라이드를 적용할 수 있는 기능을 제공합니다. `src/lib/stablecoins.ts`와 같은 라이브러리를 사용하고 `inferResilienceDefaults()`에서 기본 추론 규칙을 구현합니다.","es":"Habilita a los agentes a identificar stablecoins con inferencias predeterminadas incorrectas y aplicar anulaciones para un seguimiento preciso, utilizando bibliotecas como `src/lib/stablecoins.ts` y implementando reglas de inferencia predeterminadas desde `inferResilienceDefaults()`.","fr":"Permet aux agents d''identifier les stablecoins avec des inférences par défaut incorrectes et d''appliquer des substitutions pour un suivi précis, en utilisant des bibliothèques comme `src/lib/stablecoins.ts` et en implémentant des règles d''inférence par défaut à partir de `inferResilienceDefaults()`.","de":"Ermächtigt Agenten, Stablecoins mit fehlerhaften Standardinferenzen zu identifizieren und Überschreibungen für eine präzise Nachverfolgung anzuwenden, unter Verwendung von Bibliotheken wie `src/lib/stablecoins.ts` und Implementierung von Standardinferenzregeln aus `inferResilienceDefaults()`.","pt":"Habilita os agentes a identificar stablecoins com inferências padrão incorretas e aplicar substituições para um rastreamento preciso, utilizando bibliotecas como `src/lib/stablecoins.ts` e implementando regras de inferência padrão de `inferResilienceDefaults()`.","ru":"Наделяет агентов возможностью выявлять стейблкоины с неправильными стандартными выводами и применять переопределения для точного отслеживания, используя библиотеки как `src/lib/stablecoins.ts` и реализуя стандартные правила вывода из `inferResilienceDefaults()`.","ar":"تمكّن الوكلاء من تحديد العملات المستقرة التي تحتوي على استنتاجات افتراضية غير صحيحة وتطبيق الإغراق للحصول على تتبع دقيق، باستخدام مكتبات مثل `src/lib/stablecoins.ts` وتنفيذ قواعد الاستنتاج الافتراضي من `inferResilienceDefaults()`."},"useCases":{"en":["Auditing resilience scores for accuracy","Tracking new stablecoin additions","Overriding default inferences for stablecoin dashboards and liquidity pools"],"zh":["审计弹性评分以确保准确性","跟踪新的稳定币添加","覆盖默认推理以实现稳定币仪表板和流动性池的精确跟踪"],"ja":["精度の確保のために弾性スコアを監査する","新しい安定したコインの追加を追跡する","安定したコインのダッシュボードと流動性プールの精確な追跡のためにデフォルトの推論をオーバーライドする"],"ko":["정확성을 보장하기 위해 탄력성 점수를 감사하는 것","새로운 안정된 코인의 추가를 추적하는 것","안정된 코인 대시보드 및 유동성 풀의 정확한 추적을 위해 기본 추론을 오버라이드하는 것"],"es":["Auditoría de puntuaciones de resistencia para precisión","Seguimiento de nuevas adiciones de stablecoins","Anulación de inferencias predeterminadas para paneles de control y piscinas de liquidez de stablecoins"],"fr":["Audit des scores de résilience pour l''exactitude","Suivi des nouvelles additions de stablecoins","Substitution des inférences par défaut pour les tableaux de bord et les piscines de liquidité des stablecoins"],"de":["Prüfung von Widerstandspunktzahlen auf Genauigkeit","Nachverfolgung neuer Stablecoin-Hinzufügungen","Überschreibung von Standardinferenzen für Stablecoin-Dashboards und Liquiditätspools"],"pt":["Auditoria de pontuações de resiliência para precisão","Rastreamento de novas adições de stablecoins","Substituição de inferências padrão para painéis e piscinas de liquidez de stablecoins"],"ru":["Проверка баллов резильентности на точность","Отслеживание новых добавлений стейблкоинов","Переопределение стандартных выводов для панелей и пулов ликвидности стейблкоинов"],"ar":["مراجعة درجات المرونة لضمان الدقة","تتبع إضافات العملات المستقرة الجديدة","الإغراق على الاستنتاجات الافتراضية لألواح وأحواض السوائل للعملات المستقرة"]},"limitations":{"en":["Requires implementation of resilience types and default inference","Limited to stablecoin tracking and analysis"],"zh":["需要实现弹性类型和默认推理","仅限于稳定币跟踪和分析"],"ja":["弾性タイプとデフォルトの推論を実装する必要がある","安定したコインの追跡と分析のみに限定される"],"ko":["탄력성 유형과 기본 추론을 구현해야 함","안정된 코인 추적 및 분석에만 제한됨"],"es":["Requiere la implementación de tipos de resistencia y inferencia predeterminada","Limitado al seguimiento y análisis de stablecoins"],"fr":["Nécessite la mise en œuvre de types de résilience et d''inférence par défaut","Limité au suivi et à l''analyse des stablecoins"],"de":["Erfordert die Implementierung von Widerstandstypen und Standardinferenzen","Begrenzt auf das Tracking und die Analyse von Stablecoins"],"pt":["Exige implementação de tipos de resiliência e inferência padrão","Limitado ao rastreamento e análise de stablecoins"],"ru":["Требует реализации типов резильентности и стандартных выводов","Ограничен отслеживанием и анализом стейблкоинов"],"ar":["يتطلب تنفيذ أنواع المرونة والاستنتاجات الافتراضية","محدود بتتبع وتحليل العملات المستقرة"]},"version":4},"contentHash":"30327626c39955f2f1711b1adb5a0bfc936426ed438911cdccfa62fa318d55d3","qualityScore":30}');
