INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TokenBrice/stablecoin-dashboard/resilience-classify', 'resilience-classify', 'TokenBrice', 'stablecoin-dashboard', 'community', 'resilience-classify TokenBrice stablecoin-dashboard community analytics depeg liquidity-pool stablecoin stablecoins The resilience-classify skill identifies stablecoins with incorrect default inferences and applies overrides for accurate tracking. This skill benefits developers working with stablecoin dashboards and liquidity pools. 稳健性分类AI工具用于识别稳定币的正确分类，通过对默认推理的覆盖 レジリエンス分類AIツールは、安定した通貨の正しい分類を特定するために、デフォルトの推論を上書きする 탄력성 분류 AI 도구는 안정된 통화의 올바른 분류를 식별하기 위해 기본적 추론을 덮어씀 Resilience-classify es una habilidad que identifica stablecoins con inferencia incorrecta y aplica reglas de inferencia personalizadas. Se utiliza para auditar puntuaciones de resistencia y garantizar la precisión. Resilience-classify est une compétence qui identifie les stablecoins avec inférence incorrecte et applique des règles d''inférence personnalisées. Elle est utilisée pour auditer les scores de résilience et garantir la précision. Resilience-classify ist eine Fähigkeit, die Stablecoins mit falscher Inferenz identifiziert und benutzerdefinierte Inferenzregeln anwendet. Sie wird verwendet, um Widerstandsbewertungen zu überprüfen und die Genauigkeit zu gewährleisten. O resilience-classify é uma habilidade que identifica stablecoins onde a inferência padrão está incorreta e aplica substituições. Utiliza regras de inferência padrão do arquivo src/lib/stablecoins.ts Resilience-classify - это навык, который идентифицирует стейблкоины, где стандартная инференция неверна, и применяет переопределения. Использует стандартные правила инференции из файла src/lib/stablecoins.ts أداة الذكاء الاصطناعي resilience-classify هي مهارة تحدد الاستقرار العملات حيث الإستنتاج الافتراضي غير صحيح وتطبق الإستبدالات. تستخدم قواعد الإستنتاج الإفتراضي من الملف src/lib/stablecoins.ts how to use resilience-classify resilience-classify setup guide stablecoin resilience classification resilience-classify alternative resilience-classify vs stablecoin tracker resilience-classify install what is resilience-classify resilience-classify for liquidity pools resilience-classify for stablecoin dashboards AI工具 稳健性分类 稳定币 默认推理 覆盖默认推理 Pharos Watch src/lib/stablecoins.ts 安定した通貨分类 Identifies stablecoin candidates from src/lib/stablecoins.ts Applies default inference rules using inferResilienceDefaults() Overrides default inferences for accurate resilience scores Reads coin data from stablecoins.ts for classification Invoked after resilience types and default inference implementation Supports auditing resilience scores for accuracy resilience-classify is a skill that classifies stablecoins based on their resilience, identifying cases where default inferences are incorrect and applying overrides for improved accuracy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mkaput/elixirij/ref-src', 'community', 'mkaput', 'elixirij', 'mkaput/elixirij', 'ref-src', 3, 1, 30, '2026-03-03T09:20:17Z', '2026-03-06T07:03:48.989Z', 'cf72fece46d72b0b580ee2f13a89ca7980f9a3c5d10ee6ba5e75e83e6f174439', '{"id":"mkaput/elixirij/ref-src","name":"ref-src","description":{"en":"The ref-src skill provides experimental modern Elixir language support for IntelliJ Platform IDEs, benefiting Elixir developers. It enables codebase consultation and checkout via associated scripts.","zh":"ref-src 为 IntelliJ Platform IDEs 提供实验性现代 Elixir 语言支持，包括脚本运行和代码库浏览","ja":"ref-src は、IntelliJ Platform IDEs に実験的なモダン Elixir 言語サポートを提供します","ko":"ref-src는 IntelliJ Platform IDEs에 실험적인 모던 Elixir 언어 지원을 제공합니다","es":"ref-src es una herramienta experimental que ofrece soporte para el lenguaje Elixir en IntelliJ Platform IDEs, permitiendo la consulta de código y la ejecución de scripts asociados","fr":"ref-src est un outil expérimental qui fournit un support pour le langage Elixir sur les IDE IntelliJ Platform, permettant la consultation de code et l''exécution de scripts associés","de":"ref-src ist ein experimentelles Tool, das Unterstützung für die Elixir-Sprache in IntelliJ-Plattform-IDEs bietet, damit Entwickler Code konsultieren und zugehörige Skripte ausführen können","pt":"O ref-src oferece suporte experimental ao Elixir para IntelliJ Platform IDEs, permitindo desenvolvimento mais eficiente.","ru":"Ref-src предоставляет экспериментальную поддержку Elixir для ИИ Агентов на основе IntelliJ Platform, повышая эффективность разработки.","ar":"يوفر ref-src دعمًا تجريبيًا لإلكسير لمنصات IntelliJ Platform، مما يسمح بالتطوير الأكثر كفاءة."},"seo":{"title":{"en":"ref-src: Experimental Elixir Support for IntelliJ | AI Ag...","zh":"ref-src Setup Guide: IntelliJ Platform Elixir 语言支持","ja":"ref-src セットアップガイド: IntelliJ Platform Elixir 言語サポート","ko":"ref-src 설정 가이드: IntelliJ Platform Elixir 언어 지원","es":"Configuración de ref-src: Soporte experimental de Elixir ...","fr":"Guide d''installation de ref-src : Support Elixir pour Int...","de":"Einrichtung von ref-src: Experimenteller Elixir-Unterstüt...","pt":"Guia de Configuração ref-src: Suporte Experimental ao Elixir","ru":"Настройка ref-src: Экспериментальная поддержка Elixir для...","ar":"دليل الإعداد ref-src: دعم إلكسير الحديثExperimental"},"description":{"en":"Unlock Elixir language support in IntelliJ Platform IDEs with ref-src. Discover how to setup and utilize this experimental skill for streamlined development","zh":"使用 ref-src 实验性现代 Elixir 语言支持，提高 IntelliJ Platform IDEs 开发效率","ja":"ref-src を使用して、IntelliJ Platform IDEs の開発効率を向上させる","ko":"ref-src를 사용하여 IntelliJ Platform IDEs 개발 효율性 향상","es":"Descubre cómo configurar ref-src para IntelliJ Platform y Elixir, y aprovecha al máximo sus capacidades de desarrollo","fr":"Découvrez comment installer et utiliser ref-src pour IntelliJ Platform et Elixir, et améliorez vos compétences en développement","de":"Erfahren Sie, wie Sie ref-src für IntelliJ Platform und Elixir einrichten und seine Entwicklungsfunktionen nutzen","pt":"Aprenda a configurar o ref-src para desenvolver em Elixir com suporte experimental para IntelliJ Platform IDEs","ru":"Узнайте, как настроить ref-src для разработки на Elixir с экспериментальной поддержкой ИИ Агентов для IntelliJ Platform","ar":"تعلم كيفية تكوين ref-src لتطوير إلكسير مع دعم تجريبي لـ IntelliJ Platform IDEs"},"definition":{"en":"ref-src is an experimental skill offering modern Elixir language support for IntelliJ Platform IDEs","zh":"ref-src 是一种实验性现代 Elixir 语言支持，用于提高 IntelliJ Platform IDEs 开发效率","ja":"ref-src は、IntelliJ Platform IDEs の開発効率を向上させるために実験的に開発された Elixir 言語サポート","ko":"ref-src는 IntelliJ Platform IDEs 개발 효율성 향상을 위해 실험적으로 개발된 Elixir 언어 지원","es":"ref-src es un agente de inteligencia artificial que proporciona soporte experimental para el lenguaje Elixir en entornos de desarrollo IntelliJ","fr":"ref-src est un agent d''intelligence artificielle qui offre un support expérimental pour le langage Elixir dans les environnements de développement IntelliJ","de":"ref-src ist ein künstlicher Intelligenz-Agent, der experimentelle Unterstützung für die Elixir-Sprache in IntelliJ-Entwicklungsumgebungen bietet","pt":"O que é ref-src? Um projeto de suporte experimental ao Elixir para IntelliJ Platform IDEs.","ru":"Что такое ref-src? Проект экспериментальной поддержки Elixir для ИИ Агентов на основе IntelliJ Platform.","ar":"ما هو ref-src؟ مشروع دعم تجريبي لإلكسير لمنصات IntelliJ Platform."},"features":{"en":["Runs scripts for codebase checkout and consultation","Supports IntelliJ Platform and Elixir projects","Utilizes scripts like intellij-platform-src and elixir-src","Enables browsing of full codebase checkout paths","Provides associated scripts for Expert projects"],"zh":["实验性现代 Elixir 语言支持","IntelliJ Platform IDEs 集成","脚本运行和代码库浏览","支持多个项目（IntelliJ Platform、Elixir、Expert）","提供代码库 checkout 路径"],"ja":["実験的なモダン Elixir 言語サポート","IntelliJ Platform IDEs 統合","スクリプト実行とコードライブラリ参照","複数のプロジェクト（IntelliJ Platform、Elixir、Expert）対応","コードライブラリ checkout パス提供"],"ko":["실험적인 모던 Elixir 언어 지원","IntelliJ Platform IDEs 통합","스크립트 실행 및 코드 라이브러리 참조","여러 프로젝트(IntelliJ Platform, Elixir, Expert) 지원","코드 라이브러리 체크아웃 경로 제공"],"es":["Soporte experimental para Elixir en IntelliJ Platform","Ejecución de scripts asociados para proyectos como IntelliJ Platform y Elixir","Consulta de código y navegación en el código fuente","Integración con entornos de desarrollo IntelliJ","Capacidades de desarrollo para proyectos Elixir"],"fr":["Support expérimental pour Elixir sur IntelliJ Platform","Exécution de scripts associés pour des projets tels que IntelliJ Platform et Elixir","Consultation de code et navigation dans le code source","Intégration avec les environnements de développement IntelliJ","Fonctionnalités de développement pour les projets Elixir"],"de":["Experimentelle Unter