INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mkaput/elixirij/ref-src', 'ref-src', 'mkaput', 'elixirij', 'community', 'ref-src mkaput elixirij community The ref-src skill provides experimental modern Elixir language support for IntelliJ Platform IDEs, benefiting Elixir developers. It enables codebase consultation and checkout via associated scripts. ref-src 为 IntelliJ Platform IDEs 提供实验性现代 Elixir 语言支持，包括脚本运行和代码库浏览 ref-src は、IntelliJ Platform IDEs に実験的なモダン Elixir 言語サポートを提供します ref-src는 IntelliJ Platform IDEs에 실험적인 모던 Elixir 언어 지원을 제공합니다 ref-src es una herramienta experimental que ofrece soporte para el lenguaje Elixir en IntelliJ Platform IDEs, permitiendo la consulta de código y la ejecución de scripts asociados ref-src est un outil expérimental qui fournit un support pour le langage Elixir sur les IDE IntelliJ Platform, permettant la consultation de code et l''exécution de scripts associés ref-src ist ein experimentelles Tool, das Unterstützung für die Elixir-Sprache in IntelliJ-Plattform-IDEs bietet, damit Entwickler Code konsultieren und zugehörige Skripte ausführen können O ref-src oferece suporte experimental ao Elixir para IntelliJ Platform IDEs, permitindo desenvolvimento mais eficiente. Ref-src предоставляет экспериментальную поддержку Elixir для ИИ Агентов на основе IntelliJ Platform, повышая эффективность разработки. يوفر ref-src دعمًا تجريبيًا لإلكسير لمنصات IntelliJ Platform، مما يسمح بالتطوير الأكثر كفاءة. how to use ref-src ref-src setup guide what is ref-src ref-src alternative ref-src vs IntelliJ Elixir plugin install ref-src Elixir language support IntelliJ Platform IDEs experimental Elixir skill ref-src IntelliJ Platform Elixir AIエージェント 实验性语言支持 代码库浏览 脚本运行 开发效率 Runs scripts for codebase checkout and consultation Supports IntelliJ Platform and Elixir projects Utilizes scripts like intellij-platform-src and elixir-src Enables browsing of full codebase checkout paths Provides associated scripts for Expert projects ref-src is an experimental skill offering modern Elixir language support for IntelliJ Platform IDEs');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ThunbergOlle/virtcon2/ecs', 'community', 'ThunbergOlle', 'virtcon2', 'ThunbergOlle/virtcon2', 'ecs', 2, 0, 30, '2026-02-17T20:02:35Z', '2026-03-06T07:04:05.392Z', 'a09cbf481692776f03bc35833c7af20432734db66f4e587b3f3ae0e6a3f2b315', '{"id":"ThunbergOlle/virtcon2/ecs","name":"ecs","description":{"en":"The ECS skill enables developers to efficiently work with the Entity Component System, including finding, modifying, and debugging components, systems, and worlds. It benefits game developers and programmers working with bytenetc framework.","zh":"ECS是一种实体组件系统，用于管理组件、系统和世界，包括调试和序列化","ja":"ECSはエンティティコンポーネントシステムであり、コンポーネント、システム、ワールドの管理、デバッグ、シリアライズを行う","ko":"ECS는 엔티티 컴포넌트 시스템으로 컴포넌트, 시스템, 월드 관리, 디버깅, 시리얼라이제이션 등을 수행","es":"El sistema de entidad-componente (ECS) es una arquitectura de software que permite la creación de entidades y componentes personalizados. Utiliza bytenetc para crear aplicaciones escalables","fr":"Le système d''entité-composant (ECS) est une architecture logicielle qui permet la création d''entités et de composants personnalisés. Utilisez bytenetc pour créer des applications évolutives","de":"Das Entity-Component-System (ECS) ist eine Software-Architektur, die die Erstellung von Entitäten und Komponenten ermöglicht. Verwenden Sie bytenetc, um skalierbare Anwendungen zu erstellen","pt":"O ECS é um framework de entidade-componente-sistema personalizado que utiliza armazenamento de array tipado. Ele é usado para encontrar ou modificar componentes, sistemas ou mundos","ru":"ECS - это пользовательский фреймворк сущность-компонент-система, использующий типизированное хранилище массивов. Он используется для поиска или изменения компонентов, систем или миров","ar":"ecs هو إطار عمل مخصص لمنصة الفيرتكون 2 يستخدم مخزن مصفوفة من النوع. يستخدم لتحديد أو تعديل المكونات أو الأنظمة أو العوالم"},"seo":{"title":{"en":"ECS Skill: Entity Component System Development Guide | AI...","zh":"ECS Setup Guide - AIエージェント实体组件系统","ja":"ECS ベストプラクティス - AIエージェントのためのエンティティコンポーネントシステム","ko":"ECS 구현 가이드 - AI 에이전트를 위한 엔티티 컴포넌트 시스템","es":"Guía de configuración de ECS para desarrolladores","fr":"Guide de mise en place d''ecs pour les développeurs","de":"ECS Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do ECS: Melhores Práticas para Desen...","ru":"Настройка ИИ Агентов ECS: Руководство для Разработчиков","ar":"دليل إعداد ecs: أفضل الممارسات لمنصة الفيرتكون 2"},"description":{"en":"Unlock efficient game development with ECS skill, learn how to work with bytenetc framework and typed array storage for seamless entity serialization and net...","zh":"了解ECS的技术细节，包括组件、系统和世界的管理，ECS架构和数据流，以及调试和序列化","ja":"ECSの技術的な概要、コンポーネント、システム、ワールドの管理、ECSアーキテクチャとデータフロー、デバッグとシリアライズ","ko":"ECS의 기술적인 세부 정보, 컴포넌트, 시스템, 월드 관리, ECS 아키텍처 및 데이터 흐름, 디버깅 및 시리얼라이제이션","es":"Aprenda a utilizar el sistema de entidad-componente (ECS) con bytenetc, un marco de trabajo personalizado de conjunto disperso con almacenamiento de matriz t...","fr":"Découvrez comment utiliser le système d''entité-composant (ECS) avec bytenetc, un cadre de travail personnalisé de ensemble dispersé avec stockage de tableau ...","de":"Erfahren Sie, wie Sie das Entity-Component-System (ECS) mit bytenetc, einem benutzerdefinierten Sparse-Set-ECS-Framework mit typisierter Array-Speicherung, v...","pt":"Aprenda a configurar e otimizar o ECS para desenvolvedores, incluindo arquitetura, componentes e sistemas","ru":"Узнайте, как настроить и оптимизировать ECS для разработчиков, включая архитектуру, компоненты и системы","ar":"تعرف على كيفية تنظیم و تحسين أداء ecs لمنصة الفيرتكون 2، بما في ذلك الهندسة المعمارية و المكونات و الأنظمة"},"definition":{"en":"ecs is a skill for working with the Entity Component System, including architecture, data flow, and entity serialization, using a custom sparse-set ECS framework with typed array storage","zh":"ECS是实体组件系统的缩写，用于管理游戏或模拟中的实体、组件和系统","ja":"ECSはエンティティコンポーネントシステムの略称であり、ゲームやシミュレーションにおけるエンティティ、コンポーネント、システムの管理に使用","ko":"ECS는 엔티티 컴포넌트 시스템의 약자로서 게임이나 시뮬레이션에서 엔티티, 컴포넌트, 시스템을 관리하는 데 사용","es":"ECS es un sistema de entidad-componente que permite la creación de entidades y componentes personalizados","fr":"ECS est un système d''entité-composant qui permet la création d''entités et de composants personnalisés","de":"ECS ist ein Entity-Component-System, das die Erstellung von Entitäten und Komponenten ermöglicht","pt":"O ECS é um framework de entidade-componente-sistema que permite encontrar ou modificar componentes, sistemas ou mundos","ru":"ECS - это фреймворк сущность-компонент-система, позволяющий найти или изменить компоненты, системы или миры","ar":"ecs هو إطار عمل لمنصة الفيرتكون 2 يسمح بتحديد أو تعديل المكونات أو الأنظمة أو العوالم"},"features":{"en":["Finding or modifying components, systems, or worlds using bytenetc framework","Understanding ECS architecture and data flow for efficient game development","Debugging ECS-related issues with typed array storage","Adding new components or systems to existing ECS projects","Working with entity serialization and network synchronization for seamless gameplay"],"zh":["使用bytenetc自定义的稀疏集ECS框架","支持组件、系统和世界的管理","包括调试和序列化功能","支持实体网络同步","使用typed array存储","支持并行ECS架构"],"ja":["bytenetcのカスタムスパースセットECSフレームワークを使用","コンポーネント、システム、ワールドの管理をサポート","デバッグとシリアライズ機能を含む","エンティティのネットワーク同期をサポート","typed arrayストレージを使用","並列ECSアーキテクチャをサポート"],"ko":["bytenetc의 커스텀 스파스 셋 ECS 프레임워크 사용","컴포넌트, 시스템, 월드 관리 지원","디버깅 및 시리얼라이제이션 기능 포함","엔티티 네트워크 동기화 지원","타입드 어레이 저장소 사용","병렬 ECS 아키텍처 지원"],"es":["Utiliza bytenetc, un marco de trabajo personalizado de conjunto disperso con almacenamiento de matriz tipada","Permite la creación de entidades y componentes personalizados","Soporta la serialización de entidades y la sincronización de red","Incluye un sistema de depuración para identificar problemas","Permite la adición de nuevos componentes o sistemas","Utiliza una arquitectura de software escalable"],"fr":["Utilise bytenetc, un cadre de travail personnalisé de ensemble dispersé avec stockage de tableau typé","Permet la création d''entités et de composants personnalisés","Prend en charge la sérialisation d''entités et la synchronisation de réseau","Inclut un système de débogage pour identifier les problèmes","Permet l''ajout de nouveaux composants ou systèmes","Utilise une architecture logicielle évutive"],"de":["Verwendet bytenetc, ein benutzerdefiniertes Sparse-Set-ECS-Framework mit typisierter Array-Speicherung","Ermöglicht die Erstellung von Entitäten und Komponenten","Unterstützt die Serialisierung von Entitäten und die Netzwerksynchronisierung","Enthält ein Debugging-System zur Identifizierung von Problemen","Ermöglicht das Hinzufügen neuer Komponenten oder Systeme","Verwendet eine skalierbare Software-Architektur"],"pt":["Utiliza armazenamento de array tipado","Permite encontrar ou modificar componentes, sistemas ou mundos","Inclui arquitetura de entidade-componente-sistema personalizada","Suporta serialização de entidades e sincronização de rede","Permite adicionar novos componentes ou sistemas","Inclui depuração de problemas relacionados ao ECS"],"ru":["Использует типизированное хранилище массивов","Позволяет найти или изменить компоненты, системы или миры","Включает пользовательскую архитектуру сущность-компонент-система","Поддерживает сериализацию сущностей и сетевую синхронизацию","Позволяет добавлять новые компоненты или системы","Включает отладку проблем, связанных с ECS"],"ar":["يستخدم مخزن مصفوفة من النوع","يسمح بتحديد أو تعديل المكونات أو الأنظمة أو العوالم","يضم هندسة معمارية مخصصة لمنصة الفيرتكون 2","يدعم تسلسل الكائنات و التزامن الشبكي","يسمح بإضافة مكونات أو أنظمة جديدة","يضم تصحيح أخطاء متعلقة بمنصة الفيرتكون 2"]},"keywords":{"en":["how to use ecs","ecs architecture","bytenetc framework","ecs vs other game development frameworks","ecs install guide","ecs setup for game development","entity component system tutorial","ecs debugging techniques","ecs network synchronization"],"zh":["ECS","AIエージェント","实体组件系统","bytenetc","typed array存储","并行ECS架构","实体网络同步","游戏开发","模拟开发"],"ja":["ECS","AIエージェント","エンティティコンポーネントシステム","bytenetc","typed arrayストレージ","並列ECSアーキテクチャ","エンティティのネットワーク同期","ゲーム開発","シミュレーション開発"],"ko":["ECS","AI 에이전트","엔티티 컴포넌트 시스템","bytenetc","타입드 어레이 저장소","병렬 ECS 아키텍처","엔티티 네트워크 동기화","게임 개발","시뮬레이션 개발"],"es":["ecs","sistema de entidad-componente","bytenetc","desarrollo de aplicaciones","arquitectura de software","serialización de entidades","sincronización de red","depuración de ecs"],"fr":["ecs","système d''entité-composant","bytenetc","développement d''applications","architecture logicielle","sérialisation d''entités","synchronisation de réseau","débogage d''ecs"],"de":["ecs","entity-component-system","bytenetc","anwendungsentwicklung","software-architektur","entitäten-serialisierung","netzwerksynchronisierung","ecs-debugging"],"pt":["ecs","entidade-componente-sistema","armazenamento de array tipado","arquitetura de software","desenvolvimento de jogos","Virtcon 2","bytenetc","serialização de entidades","sincronização de rede"],"ru":["ECS","сущность-компонент-система","типизированное хранилище массивов","архитектура программного обеспечения","разработка игр","Virtcon 2","bytenetc","сериализация сущностей","сетевая синхронизация"],"ar":["ecs","منصة الفيرتكون 2","مخزن مصفوفة من النوع","هندسة معمارية لمنصة الفيرتكون 2","تطوير الألعاب","Virtcon 2","bytenetc","تسلسل الكائنات","التزامن الشبكي"]}},"owner":"ThunbergOlle","repo":"virtcon2","repoPath":"ThunbergOlle/virtcon2","stars":2,"forks":0,"updatedAt":"2026-02-17T20:02:35Z","topics":[],"category":"community","skillMd":{"name":"ecs","description":"Use when working with the Entity Component System (ECS), including finding or modifying components, systems, worlds, debugging, or adding new components/systems.","bodyPreview":"# ECS Skill\n\nUse this skill when working with the Entity Component System (ECS), including:\n- Finding or modifying components, systems, or worlds\n- Understanding ECS architecture and data flow\n- Debugging ECS-related issues\n- Adding new components or systems\n- Working with entity serialization and network synchronization\n\n## Overview\n\nThis project uses **bytenetc**, a custom sparse-set ECS framework with typed array storage. Both server (packet_router) and client (game) maintain parallel ECS ins","body":"# ECS Skill\n\nUse this skill when working with the Entity Component System (ECS), including:\n- Finding or modifying components, systems, or worlds\n- Understanding ECS architecture and data flow\n- Debugging ECS-related issues\n- Adding new components or systems\n- Working with entity serialization and network synchronization\n\n## Overview\n\nThis project uses **bytenetc**, a custom sparse-set ECS framework with typed array storage. Both server (packet_router) and client (game) maintain parallel ECS instances synchronized via Socket.io packets.\n\n## Key Locations\n\n**ECS Core Framework:**\n- `packages/bytenetc/src/lib/` - Core ECS implementation\n\n**Components:**\n- `packages/network-world-entities/src/lib/components/` - All component definitions\n- Common components: Position, Sprite, Velocity, Collider, Player, Building, Resource, Tile\n\n**Systems:**\n- `apps/packet_router/src/systems/` - Server-side systems (20 TPS tick loop)\n- `apps/game/src/systems/` - Client-side systems (60 FPS render loop)\n\n**Entities:**\n- `packages/network-world-entities/src/lib/entities/` - Entity factory functions\n\n**Serialization:**\n- `packages/network-world-entities/src/lib/serializeConfig.ts` - Component serialization config\n- `packages/network-world-entities/src/lib/SerializationIDs.ts` - Serialization ID definitions\n\n**Network Sync:**\n- `apps/packet_router/src/main.ts` - Server tick loop and packet broadcasting\n- `apps/game/src/scenes/Game.ts` - Client packet handling and deserialization\n- `apps/game/src/networking/Network.ts` - Socket.io client wrapper\n\n## Quick Reference\n\n### Component Definition\n\n```typescript\nimport { defineComponent, Types } from ''@virtcon2/bytenetc'';\n\nexport const MyComponent = defineComponent(''myComponent'', {\n  value: Types.i32,\n  position: Types.f32,\n  data: [Types.ui8, 32], // Fixed-size array\n});\n```\n\n**Supported types:** `i8`, `i16`, `i32`, `f32`, `f64`, `ui8`, `ui16`, `ui32`\n\n### World Management\n\n```typescript\nimport { createWorld, deleteWorld, registerComponents } from ''@virtcon2/bytenetc'';\n\nconst world = createWorld(''world-id'');\nregisterComponents(world, [Position, Sprite, MyComponent]);\ndeleteWorld(world); // Cleanup\n```\n\n### Entity Operations\n\n```typescript\nimport { addEntity, addComponent, removeEntity, removeComponent } from ''@virtcon2/bytenetc'';\n\nconst eid = addEntity(world);\naddComponent(world, Position, eid);\n\n// Set values (direct array access)\nPosition.x[eid] = 100;\nPosition.y[eid] = 200;\n\nremoveComponent(world, Sprite, eid);\nremoveEntity(world, eid);\n```\n\n### Queries\n\n```typescript\nimport { defineQuery, Has, Not, Changed, enterQuery, exitQuery } from ''@virtcon2/bytenetc'';\n\n// Basic query - entities with both components\nconst query = defineQuery(Position, Sprite);\nconst entities = query(world); // Returns entity ID array\n\n// Modifiers\nconst playerQuery = defineQuery(Position, Has(Player), Not(NPC));\nconst changedQuery = defineQuery(Changed(Position));\n\n// Enter/Exit queries\nconst newEntities = enterQuery(query)(world);\nconst removedEntities = exitQuery(query)(world);\n```\n\n### System Definition (Server)\n\n```typescript\nimport { defineSystem } from ''@virtcon2/bytenetc'';\nimport type { SyncEntities } from ''@virtcon2/network-packet'';\n\nexport const createMySystem = (world: World) => {\n  const query = defineQuery(Position, MyComponent);\n\n  return defineSystem<SyncEntities>(({ worldData }) => {\n    const entitiesToSync: number[] = [];\n    const entitiesToRemove: number[] = [];\n\n    // Process entities\n    for (const eid of query(world)) {\n      Position.x[eid] += 1;\n      entitiesToSync.push(eid);\n    }\n\n    // Serialize for network\n    const serialized = defineSerializer(\n      getSerializeConfig(world)[SerializationID.MY_ENTITY]\n    )(world, entitiesToSync);\n\n    return {\n      sync: [{ serializationId: SerializationID.MY_ENTITY, data: serialized }],\n      removeEntities: entitiesToRemove,\n      worldData,\n    };\n  });\n};\n```\n\n### System Definition (Client)\n\n```typescript\nexport const createMyClientSystem = (world: World) => {\n  const query = defineQuery(Position, Sprite);\n\n  return (state: State) => {\n    for (const eid of query(world)) {\n      const sprite = state.spritesById[eid];\n      if (sprite) {\n        sprite.x = Position.x[eid];\n        sprite.y = Position.y[eid];\n      }\n    }\n    return state;\n  };\n};\n```\n\n## Network Synchronization Flow\n\n1. **Server (packet_router):**\n   - Runs tick loop at 20 TPS (`apps/packet_router/src/main.ts`)\n   - Systems process entities and return serialized data\n   - Broadcasts `SYNC_SERVER_ENTITY` and `REMOVE_ENTITY` packets via Socket.io\n\n2. **Client (game):**\n   - Receives packets in `Game.update()` (`apps/game/src/scenes/Game.ts`)\n   - Deserializes entities into local ECS world\n   - Runs client systems at 60 FPS to update Phaser sprites\n\n3. **Serialization:**\n   - Defined in `serializeConfig.ts` - maps SerializationID to component lists\n   - Entities serialize to arrays: `[componentName, fieldName, value]`\n   - Only specified components are synced per entity type\n\n## Common Tasks\n\n### Adding a New Component\n\n1. Create component definition in `packages/network-world-entities/src/lib/components/`\n2. Export from `packages/network-world-entities/src/lib/components/index.ts`\n3. Add to serialization config in `serializeConfig.ts` if network-synced\n4. Register in world initialization (both server and client if synced)\n\n### Adding a New System\n\n**Server:**\n1. Create in `apps/packet_router/src/systems/`\n2. Import and add to `tickSystems()` in `apps/packet_router/src/main.ts`\n\n**Client:**\n1. Create in `apps/game/src/systems/`\n2. Import and call in `Game.update()` in `apps/game/src/scenes/Game.ts`\n\n### Adding a New Entity Type\n\n1. Create factory function in `packages/network-world-entities/src/lib/entities/`\n2. Add SerializationID in `SerializationIDs.ts`\n3. Add serialization config in `serializeConfig.ts`\n4. Create spawning logic in appropriate system\n\n## Debugging\n\n**Check which entities have a component:**\n```typescript\nconst query = defineQuery(MyComponent);\nconsole.log(''Entities with MyComponent:'', query(world));\n```\n\n**Check component values:**\n```typescript\nconsole.log(''Position:'', { x: Position.x[eid], y: Position.y[eid] });\n```\n\n**Track component changes:**\n```typescript\nconst changedQuery = defineQuery(Changed(Position));\nconsole.log(''Entities with changed Position:'', changedQuery(world));\n```\n\n## Important Notes\n\n- Maximum 3,000 entities per world\n- Component data stored in typed arrays for performance\n- Direct array access (e.g., `Position.x[eid]`) for reading/writing values\n- Server systems run at 20 TPS, client systems at 60 FPS\n- Not all components need network sync (client-only rendering components)\n- Use enter/exit queries to detect new/removed entities efficiently\n\n## Documentation\n\nFull details: `/docs/ECS_AND_NETWORK_SYNC.md`\n"},"lastSynced":"2026-03-06T07:04:05.392Z","agentAnalysis":{"suitability":{"en":"Ideal for Game Development Agents working with bytenetc framework and requiring advanced Entity Component System management.","zh":"适合使用bytenetc framework并需要高级Entity Component System管理的游戏开发代理。","ja":"bytenetcフレームワークを使用し、Entity Component Systemの高度な管理が必要なゲーム開発エージェントに適しています。","ko":"bytenetc 프레임워크를 사용하고 Entity Component System의 고급 관리가 필요한 게임 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo de Juegos que trabajan con el framework bytenetc y requieren una gestión avanzada del Sistema de Entidades y Componentes.","fr":"Idéal pour les Agents de Développement de Jeux travaillant avec le framework bytenetc et nécessitant une gestion avancée du Système d''Entités et de Composants.","de":"Ideal für Game-Entwicklung-Agenten, die mit dem bytenetc-Framework arbeiten und eine erweiterte Verwaltung des Entity-Component-Systems benötigen.","pt":"Ideal para agentes de desenvolvimento de jogos que trabalham com o framework bytenetc e que exigem gerenciamento avançado do Entity Component System.","ru":"Идеально подходит для агентов разработки игр, работающих с фреймворком bytenetc и требующих расширенного управления системой Entity Component System.","ar":"مثالي لعميل تطوير الألعاب الذي يعمل مع إطار bytenetc والذي يتطلب إدارة متقدمة لنظام Entity Component"},"recommendation":{"en":"Empowers agents to efficiently find, modify, and debug components, systems, and worlds within the Entity Component System, leveraging bytenetc''s custom sparse-set ECS framework with typed array storage, and facilitating entity serialization and network synchronization.","zh":"赋予代理在Entity Component System中高效地查找、修改和调试组件、系统和世界的能力，利用bytenetc的自定义sparse-set ECS框架和类型化数组存储，并促进实体序列化和网络同步。","ja":"エージェントがEntity Component System内でコンポーネント、システム、ワールドを効率的に検索、変更、デバッグできるようにし、bytenetcのカスタムsparse-set ECSフレームワークと型付き配列ストレージを活用し、エンティティのシリアル化とネットワーク同期を促進します。","ko":"에이전트가 Entity Component System 내에서 컴포넌트, 시스템, 월드를 효율적으로 검색, 수정 및 디버깅 할 수 있도록 하며, bytenetc의 사용자 정의 sparse-set ECS 프레임워크와 유형화된 배열 저장소를 활용하여 엔티티의 직렬화 및 네트워크 동기화를促進합니다.","es":"Permite a los agentes encontrar, modificar y depurar componentes, sistemas y mundos dentro del Sistema de Entidades y Componentes de manera eficiente, aprovechando el framework de conjunto disperso personalizado de bytenetc con almacenamiento de matrices tipadas y facilitando la serialización de entidades y la sincronización de red.","fr":"Permet aux agents de trouver, de modifier et de déboguer efficacement les composants, les systèmes et les mondes au sein du Système d''Entités et de Composants, en exploitant le framework de ensemble éparse personnalisé de bytenetc avec un stockage de tableaux typés et en facilitant la sérialisation d''entités et la synchronisation réseau.","de":"Ermöglicht es Agenten, Komponenten, Systeme und Welten innerhalb des Entity-Component-Systems effizient zu finden, zu ändern und zu debuggen, indem es den benutzerdefinierten sparse-set-ECS-Framework von bytenetc mit typisierter Array-Speicherung nutzt und die Entitäts-Serialisierung und Netzwerksynchronisierung erleichtert.","pt":"Habilita os agentes a encontrar, modificar e depurar componentes, sistemas e mundos dentro do Entity Component System, aproveitando o framework de ECS personalizado com armazenamento de matriz esparsa do bytenetc e facilitando a serialização de entidades e a sincronização de rede.","ru":"Наделяет агентов возможностью эффективно находить, изменять и отлаживать компоненты, системы и миры внутри системы Entity Component System, используя пользовательский фреймворк ECS с типизированным хранилищем массивов bytenetc и облегчая сериализацию сущностей и сетевую синхронизацию.","ar":"يمنح الوكلاء القدرة على العثور على العناصر وتعديلها وتصحيحها داخل نظام Entity Component System، مستفيدا من الإطار المخصص ل ECS مع تخزين المصفوفة النادرة من bytenetc وتسهيل تسلسل الكيانات وتزامن الشبكة."},"useCases":{"en":["Debugging ECS-related issues","Adding new components or systems","Understanding ECS architecture and data flow"],"zh":["调试ECS相关问题","添加新组件或系统","理解ECS架构和数据流"],"ja":["ECS関連の問題をデバッグする","新しいコンポーネントまたはシステムを追加する","ECSアーキテクチャとデータフローを理解する"],"ko":["ECS 관련 문제를 디버깅하는 것","새로운 컴포넌트 또는 시스템을 추가하는 것","ECS 아키텍처와 데이터 흐름을 이해하는 것"],"es":["Depuración de problemas relacionados con ECS","Adición de nuevos componentes o sistemas","Comprensión de la arquitectura y el flujo de datos de ECS"],"fr":["Débogage des problèmes liés à ECS","Ajout de nouveaux composants ou systèmes","Compréhension de l''architecture et du flux de données d''ECS"],"de":["Debuggen von ECS-bezogenen Problemen","Hinzufügen neuer Komponenten oder Systeme","Verständnis der ECS-Architektur und des Datenflusses"],"pt":["Depuração de problemas relacionados ao ECS","Adicionar novos componentes ou sistemas","Compreender a arquitetura e o fluxo de dados do ECS"],"ru":["Отладка проблем, связанных с ECS","Добавление новых компонентов или систем","Понимание архитектуры и потока данных ECS"],"ar":["تصحيح الأخطاء المتعلقة بنظام ECS","إضافة مكونات أو أنظمة جديدة","فهم هندسة نظام ECS وتدفق البيانات"]},"limitations":{"en":["Requires bytenetc framework","Specific to Entity Component System (ECS) architecture"],"zh":["需要bytenetc框架","特定于Entity Component System（ECS）架构"],"ja":["bytenetcフレームワークが必要","Entity Component System（ECS）アーキテクチャに特有"],"ko":["bytenetc 프레임워크가 필요","Entity Component System（ECS） 아키텍처에 특정"],"es":["Requiere el framework bytenetc","Específico para la arquitectura del Sistema de Entidades y Componentes (ECS)"],"fr":["Nécessite le framework bytenetc","Spécifique à l''architecture du Système d''Entités et de Composants (ECS)"],"de":["Benötigt das bytenetc-Framework","Spezifisch für die Entity-Component-System (ECS)-Architektur"],"pt":["Exige o framework bytenetc","Específico para a arquitetura do Entity Component System (ECS)"],"ru":["Требует фреймворка bytenetc","Специфичен для архитектуры системы Entity Component System (ECS)"],"ar":["يتطلب إطار bytenetc","محدد لهندسة نظام Entity Component System (ECS)"]},"version":4},"contentHash":"a09cbf481692776f03bc35833c7af20432734db66f4e587b3f3ae0e6a3f2b315","qualityScore":30}');
