INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ThunbergOlle/virtcon2/ecs', 'ecs', 'ThunbergOlle', 'virtcon2', 'community', 'ecs ThunbergOlle virtcon2 community The ECS skill enables developers to efficiently work with the Entity Component System, including finding, modifying, and debugging components, systems, and worlds. It benefits game developers and programmers working with bytenetc framework. ECS是一种实体组件系统，用于管理组件、系统和世界，包括调试和序列化 ECSはエンティティコンポーネントシステムであり、コンポーネント、システム、ワールドの管理、デバッグ、シリアライズを行う ECS는 엔티티 컴포넌트 시스템으로 컴포넌트, 시스템, 월드 관리, 디버깅, 시리얼라이제이션 등을 수행 El sistema de entidad-componente (ECS) es una arquitectura de software que permite la creación de entidades y componentes personalizados. Utiliza bytenetc para crear aplicaciones escalables Le système d''entité-composant (ECS) est une architecture logicielle qui permet la création d''entités et de composants personnalisés. Utilisez bytenetc pour créer des applications évolutives Das Entity-Component-System (ECS) ist eine Software-Architektur, die die Erstellung von Entitäten und Komponenten ermöglicht. Verwenden Sie bytenetc, um skalierbare Anwendungen zu erstellen O ECS é um framework de entidade-componente-sistema personalizado que utiliza armazenamento de array tipado. Ele é usado para encontrar ou modificar componentes, sistemas ou mundos ECS - это пользовательский фреймворк сущность-компонент-система, использующий типизированное хранилище массивов. Он используется для поиска или изменения компонентов, систем или миров ecs هو إطار عمل مخصص لمنصة الفيرتكون 2 يستخدم مخزن مصفوفة من النوع. يستخدم لتحديد أو تعديل المكونات أو الأنظمة أو العوالم how to use ecs ecs architecture bytenetc framework ecs vs other game development frameworks ecs install guide ecs setup for game development entity component system tutorial ecs debugging techniques ecs network synchronization ECS AIエージェント 实体组件系统 bytenetc typed array存储 并行ECS架构 实体网络同步 游戏开发 模拟开发 Finding or modifying components, systems, or worlds using bytenetc framework Understanding ECS architecture and data flow for efficient game development Debugging ECS-related issues with typed array storage Adding new components or systems to existing ECS projects Working with entity serialization and network synchronization for seamless gameplay ecs is a skill for working with the Entity Component System, including architecture, data flow, and entity serialization, using a custom sparse-set ECS framework with typed array storage');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ka2kama/ringiflow/retro', 'community', 'ka2kama', 'ringiflow', 'ka2kama/ringiflow', 'retro', 2, 0, 30, '2026-02-24T17:21:06Z', '2026-03-06T07:04:23.174Z', '74db3b873363cfd950e86ca058fda5c298b38212714805242295a42f54029b34', '{"id":"ka2kama/ringiflow/retro","name":"retro","description":{"en":"The retro skill analyzes the effectiveness of improvement cycles and trends in project health from an SRE perspective. It benefits developers by providing insights into the direction of operational improvements.","zh":"Retro AI工具通过改善周期优化和趋势分析提高项目健康度，提供SRE的运用改善方向","ja":"Retro AIエージェントは改善サイクル全体の有効性を検証し、プロジェクト健全性のトレンドを分析する","ko":"Retro AI 에이전트는 개선 사이클의 효율성을 검증하고 프로젝트 건강성의 트렌드를 분석하여 SRE의 관점에서 운용 개선 방향을 제시","es":"Retro es una herramienta de análisis de tendencias y mejora que verifica la efectividad de los ciclos de mejora y analiza las tendencias de salud del proyecto","fr":"Retro est un outil d''analyse de tendances et d''amélioration qui vérifie l''efficacité des cycles d''amélioration et analyse les tendances de santé du projet","de":"Retro ist ein Tool für Trendanalyse und Verbesserung, das die Wirksamkeit der Verbesserungszyklen überprüft und die Trends der Projekgesundheit analysiert","pt":"O Retro é uma habilidade que verifica a eficácia dos ciclos de melhoria e analisa tendências de saúde do projeto, fornecendo direção para melhorias operacionais.","ru":"Ретро - это навык, который проверяет эффективность циклов улучшения и анализирует тенденции здоровья проекта, предоставляя направление для операционных улучшений.","ar":"Retro هو مهارة تقوم بفحص فعالية دورات التحسين وتحليل اتجاهات صحة المشروع، وتوفر توجيهًا لتحسينات تشغيلية"},"seo":{"title":{"en":"Retro: Improvement Cycle Analysis for AI Agents | Setup G...","zh":"Retro AI工具改善周期优化设置指南","ja":"Retro AIエージェントの改善サイクル全体の有効性検証","ko":"Retro AI 에이전트 개선 사이클 최적화 설정 가이드","es":