INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ka2kama/ringiflow/retro', 'retro', 'ka2kama', 'ringiflow', 'community', 'retro ka2kama ringiflow community The retro skill analyzes the effectiveness of improvement cycles and trends in project health from an SRE perspective. It benefits developers by providing insights into the direction of operational improvements. Retro AI工具通过改善周期优化和趋势分析提高项目健康度，提供SRE的运用改善方向 Retro AIエージェントは改善サイクル全体の有効性を検証し、プロジェクト健全性のトレンドを分析する Retro AI 에이전트는 개선 사이클의 효율성을 검증하고 프로젝트 건강성의 트렌드를 분석하여 SRE의 관점에서 운용 개선 방향을 제시 Retro es una herramienta de análisis de tendencias y mejora que verifica la efectividad de los ciclos de mejora y analiza las tendencias de salud del proyecto Retro est un outil d''analyse de tendances et d''amélioration qui vérifie l''efficacité des cycles d''amélioration et analyse les tendances de santé du projet Retro ist ein Tool für Trendanalyse und Verbesserung, das die Wirksamkeit der Verbesserungszyklen überprüft und die Trends der Projekgesundheit analysiert O Retro é uma habilidade que verifica a eficácia dos ciclos de melhoria e analisa tendências de saúde do projeto, fornecendo direção para melhorias operacionais. Ретро - это навык, который проверяет эффективность циклов улучшения и анализирует тенденции здоровья проекта, предоставляя направление для операционных улучшений. Retro هو مهارة تقوم بفحص فعالية دورات التحسين وتحليل اتجاهات صحة المشروع، وتوفر توجيهًا لتحسينات تشغيلية how to use retro in AI agents what is retro skill retro vs assess retro setup guide for developers retro improvement cycle analysis site reliability engineering with retro retro trend analysis tool installing retro for AI agents retro alternative for project health analysis Retro AI工具 AI工具 改善周期优化 趋势分析 SRE 项目健康度 运用改善方向 AIエージェント Performs a full assessment of improvement cycles in ''full mode'' without arguments Supports ''quick'' mode for rapid verification of improvement systems Provides SRE-centric analysis with the ''sre'' argument Analyzes trends in project health over time Differentiates from ''/assess'' by focusing on improvement cycles and trends rather than current snapshots Retro is a skill that verifies the effectiveness of improvement cycles and analyzes project health trends, providing guidance on operational improvement directions from a Site Reliability Engineering (SRE) perspective.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ebongard/renfield/git-workflow', 'community', 'ebongard', 'renfield', 'ebongard/renfield', 'git-workflow', 1, 2, 30, '2026-02-25T11:49:18Z', '2026-03-06T07:10:43.921Z', 'eac8bed60118dbc9eccc0853360a0e977f8021d09cfcd4be6e2243dd1ac31ea3', '{"id":"ebongard/renfield/git-workflow","name":"git-workflow","description":{"en":"The git-workflow skill provides a self-hosted AI assistant with a set of critical rules for Git management, benefiting developers who need to streamline their workflow. It integrates with 100+ tools and features a RAG knowledge base.","zh":"Git Workflow 是一个自托管的 AI 助手，集成了 100 多个工具，包括 FastAPI、React 和 Ollama。了解其关键规则和最佳实践","ja":"Git Workflow は、100以上のツールを統合したセルフホステッドのAIアシスタントです。FastAPI、React、Ollamaなどを含みます。重要なルールとベストプラクティスを学びましょう","ko":"Git Workflow는 100개 이상의 도구를 통합한 자체 호스팅 AI 도구입니다. FastAPI, React, Ollama 등이 포함되어 있습니다. 주요 규칙과 최고의 실천 방법을 알아보세요","es":"El flujo de trabajo de git es fundamental para el desarrollo de Agentes de Inteligencia Artificial. Conoce las mejores prácticas para configurarlo","fr":"Le flux de travail git est essentiel pour le développement des Agents d''Intelligence Artificielle. Découvrez les meilleures pratiques pour le configurer","de":"Der Git-Workflow ist für die Entwicklung von KI-Agenten entscheidend. Erfahren Sie die besten Praktiken für die Einrichtung","pt":"O fluxo de trabalho Git é uma ferramenta essencial para desenvolvedores de IA, permitindo a colaboração e o controle de versão de código com FastAPI e React.","ru":"Поток работы Git является важнейшим инструментом для разработчиков ИИ, позволяющим сотрудничать и контролировать версии кода с FastAPI и React.","ar":"مسار العمل جيت هو أداة أساسية لمطوري الذكاء الاصطناعي، مما يسمح بالتعاون ومراقبة إصدارات الكود مع FastAPI و React."},"seo":{"title":{"en":"git-workflow: Git Management Best Practices for AI Agents...","zh":"Git Workflow 最佳实践指南 - AI 工具集成","ja":"Git Workflow セットアップガイド - AI エージェントとの統合","ko":"Git Workflow 설정 가이드 - AI 도구 통합","es":"Guía de configuración de flujo de trabajo de git para Age...","fr":"Guide de mise en place du flux de travail git pour les Ag...","de":"Einrichtungsleitfaden für Git-Workflow für KI-Agenten","pt":"Guia de Configuração do Fluxo de Trabalho Git para Ferram...","ru":"Настройка Потока Работы Git для ИИ Агентов","ar":"دليل إعداد مسار العمل جيت لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to optimize your Git workflow with critical rules and features like branch protection, co-authored-by, and commit message formatting. Learn more...","zh":"了解 Git Workflow 的关键规则和最佳实践，包括 Issue 编号、文档更新和分支保护，用于 AI 工具集成","ja":"Git Workflow の重要なルールとベストプラクティスを学びます。Issue 番号、ドキュメントの更新、ブランチ保護など、AI エージェントとの統合に役立ちます","ko":"Git Workflow의 중요한 규칙과 최고의 실천 방법을 알아보세요. 이슈 번호, 문서 업데이트, 브랜치 보호 등 AI 도구 통합에 도움이 됩니다","es":"Aprende a configurar el flujo de trabajo de git para tu proyecto de Agente de Inteligencia Artificial con FastAPI, React y Ollama","fr":"Découvrez comment configurer le flux de travail git pour votre projet d''Agent d''Intelligence Artificielle avec FastAPI, React et Ollama","de":"Erfahren Sie, wie Sie den Git-Workflow für Ihr KI-Agenten-Projekt mit FastAPI, React und Ollama einrichten","pt":"Aprenda a configurar o fluxo de trabalho Git para ferramentas de IA com FastAPI, React e Ollama, incluindo integrações de 100+ ferramentas e capacidade offline","ru":"Узнайте, как настроить поток работы Git для ИИ агентов с FastAPI, React и Ollama, включая интеграции с 100+ инструментами и возможность работы offline","ar":"تعلم كيفية إعداد مسار العمل جيت لأدوات الذكاء الاصطناعي مع FastAPI و React و Ollama، بما في ذلك التكامل مع أكثر من 100 أداة ووظائف العمل离 الخط"},"definition":{"en":"git-workflow is a set of guidelines and rules for managing Git repositories, ensuring efficient collaboration and version control for developers and AI agents.","zh":"Git Workflow 是一个用于管理 Git 仓库的工作流程，包含一系列的规则和最佳实践，用于 AI 工具集成","ja":"Git Workflow は、Git リポジトリを管理するためのワークフローであり、AI エージェントとの統合に役立つ一連のルールとベストプラクティスを含みます","ko":"Git Workflow는 Git 저장소를 관리하기 위한 작업 흐름으로, AI 도구 통합에 도움이 되는 일련의 규칙과 최고의 실천 방법을 포함합니다","es":"El flujo de trabajo de git es un conjunto de reglas y prácticas para gestionar el código de un proyecto de Agente de Inteligencia Artificial","fr":"Le flux de travail git est un ensemble de règles et de pratiques pour gérer le code d''un projet d''Agent d''Intelligence Artificielle","de":"Der Git-Workflow ist eine Sammlung von Regeln und Praktiken zur Verwaltung des Codes eines KI-Agenten-Projekts","pt":"O fluxo de trabalho Git é um conjunto de regras e procedimentos para gerenciar o código-fonte de projetos de IA","ru":"Поток работы Git - это набор правил и процедур для управления исходным кодом проектов ИИ","ar":"مسار العمل جيت هو مجموعة من القواعد والإجراءات لإدارة код المصدر لمشاريع الذكاء الاصطناعي"},"features":{"en":["Enforces branch protection to prevent direct pushes to the main branch","Requires issue numbers in every commit for better tracking","Supports co-authored-by commits for collaborative development","Mandates documentation updates before pushing changes","Utilizes a specific commit message format for consistency"],"zh":["集成 FastAPI、React 和 Ollama","支持 100 多个工具","包含 RAG 知识库和全离线能力","使用 Co-Authored-By Commit 消息格式","支持分支保护和 Issue 编号","支持 Docker 和 PWA"],"ja":["FastAPI、React、Ollama の統合","100以上のツールのサポート","RAG ノウハウベースとオフライン機能の包含","Co-Authored-By Commit メッセージ形式の使用","ブランチ保護とIssue番号のサポート","Docker と PWA のサポート"],"ko":["FastAPI, React, Ollama 통합","100개 이상의 도구 지원","RAG 지식베이스와 전체 오프라인 기능 포함","Co-Authored-By Commit 메시지 형식 사용","브랜치 보호와 이슈 번호 지원","Docker와 PWA 지원"],"es":["Integración con FastAPI y React","Compatibilidad con Ollama","Flujo de trabajo de git con protección de ramas","Soporte para commits co-autorizados","Formato de mensaje de commit personalizable"],"fr":["Intégration avec FastAPI et React","Compatibilité avec Ollama","Flux de travail git avec protection de branches","Prise en charge de commits co-auteurs","Format de message de commit personnalisable"],"de":["Integration mit FastAPI und React","Kompatibilität mit Ollama","Git-Workflow mit Branch-Schutz","Unterstützung für Co-Autoren-Commits","Anpassbares Commit-Nachrichten-Format"],"pt":["Integração com 100+ ferramentas","Capacidade offline com Ollama","Desenvolvimento com FastAPI e React","Controle de versão com Git","Colaboração em equipe com branch protection"],"ru":["Интеграция с 100+ инструментами","Возможность работы offline с Ollama","Разработка с FastAPI и React","Контроль версий с Git","Сотрудничество в команде с branch protection"],"ar":["التكامل مع أكثر من 100 أداة","الوظائف العمل离 الخط مع Ollama","التطوير مع FastAPI و React","مراقبة إصدارات الكود مع Git","التعاون الفريق مع حماية الفرع"]},"keywords":{"en":["how to use git-workflow","git-workflow setup guide","git-workflow alternative","git-workflow vs gitflow","git-workflow install","what is git-workflow","git-workflow best practices","git-workflow for AI agents","git-workflow and FastAPI","git-workflow with React"],"zh":["Git Workflow","AI 工具集成","FastAPI","React","Ollama","RAG 知识库","全离线能力","Co-Authored-By Commit","分支保护","Issue 编号"],"ja":["Git Workflow","AI エージェント統合","FastAPI","React","Ollama","RAG ノウハウベース","オフライン機能","Co-Authored-By Commit","ブランチ保護","Issue 番号"],"ko":["Git Workflow","AI 도구 통합","FastAPI","React","Ollama","RAG 지식베이스","전체 오프라인 기능","Co-Authored-By Commit","브랜치 보호","이슈 번호"],"es":["flujo de trabajo de git","Agente de Inteligencia Artificial","FastAPI","React","Ollama","desarrollo de software","git workflow","AI Agentes","Inteligencia Artificial"],"fr":["flux de travail git","Agent d''Intelligence Artificielle","FastAPI","React","Ollama","développement de logiciels","git workflow","Agents d''IA","Intelligence Artificielle"],"de":["Git-Workflow","KI-Agenten","FastAPI","React","Ollama","Software-Entwicklung","git workflow","Künstliche Intelligenz","KI-Tools"],"pt":["ferramentas de IA","fluxo de trabalho Git","FastAPI","React","Ollama","integração de ferramentas","capacidade offline","controle de versão","colaboração em equipe"],"ru":["ИИ агенты","поток работы Git","FastAPI","React","Ollama","интеграция инструментов","возможность работы offline","контроль версий","сотрудничество в команде"],"ar":["أدوات الذكاء الاصطناعي","مسار العمل جيت","FastAPI","React","Ollama","التكامل مع الأدوات","الوظائف العمل离 الخط","مراقبة إصدارات الكود","التعاون الفريق"]}},"owner":"ebongard","repo":"renfield","repoPath":"ebongard/renfield","stars":1,"forks":2,"updatedAt":"2026-02-25T11:49:18Z","topics":["ai-assistant","docker","knowledge-base","knowledge-graph","mcp","offline-first","ollama","presence-detection","privacy","pwa","rag","raspberry-pi","react","self-hosted","speaker-recognition","typescript","voice-assistant"],"category":"community","skillMd":{"name":"git-workflow","description":"Git workflow rules for Renfield. Commit message format, issue numbering, branch naming, PR creation, documentation updates before push. Triggers on commit, push, PR erstellen, pull request, branch, git, merge.","bodyPreview":"# Git Workflow\n\n## CRITICAL RULES\n\n1. **NIEMALS ohne Erlaubnis pushen** — `git push` NUR nach expliziter Bestätigung\n2. **Issue-Nummer bei jedem Commit** — Vor jedem Commit nach der Issue-Nummer fragen\n3. **Dokumentation vor Push** — CLAUDE.md, docs/, README müssen Änderungen widerspiegeln\n4. **Branch Protection** — Direct push to `main` is blocked. Always use feature branch → PR → merge.\n5. **Co-Authored-By** — Jeder Commit muss die Co-Author-Zeile enthalten\n\n## Commit Message Format\n\n```\ntype(","body":"# Git Workflow\n\n## CRITICAL RULES\n\n1. **NIEMALS ohne Erlaubnis pushen** — `git push` NUR nach expliziter Bestätigung\n2. **Issue-Nummer bei jedem Commit** — Vor jedem Commit nach der Issue-Nummer fragen\n3. **Dokumentation vor Push** — CLAUDE.md, docs/, README müssen Änderungen widerspiegeln\n4. **Branch Protection** — Direct push to `main` is blocked. Always use feature branch → PR → merge.\n5. **Co-Authored-By** — Jeder Commit muss die Co-Author-Zeile enthalten\n\n## Commit Message Format\n\n```\ntype(scope): Kurze Beschreibung (#issue)\n\nLängere Beschreibung falls nötig.\n\nCo-Authored-By: Claude Opus 4.6 <noreply@anthropic.com>\n```\n\n**Example:** `feat(satellites): Add monitoring dashboard (#25)`\n\n## Commit Types\n\n| Type | Usage |\n|------|-------|\n| `feat` | Neues Feature |\n| `fix` | Bugfix |\n| `docs` | Dokumentation |\n| `refactor` | Code-Refactoring |\n| `test` | Tests hinzufügen/ändern |\n| `chore` | Wartung, Dependencies |\n\n## Workflow\n\n1. Create feature branch: `git checkout -b type/short-description`\n2. Make changes + write tests (TDD)\n3. Update documentation (CLAUDE.md, docs/)\n4. Ask for issue number\n5. Commit with proper format\n6. Ask user: \"Soll ich pushen?\"\n7. Only after confirmation: `git push -u origin branch-name`\n8. Create PR: `gh pr create --title \"type(scope): Description (#issue)\" --body \"...\"`\n\n## PR Format\n\n```bash\ngh pr create --title \"type(scope): Description (#issue)\" --body \"$(cat <<''EOF''\n## Summary\n- Bullet points describing changes\n\n## Test plan\n- [ ] Tests added/updated\n- [ ] Manual testing done\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\nEOF\n)\"\n```\n"},"lastSynced":"2026-03-06T07:10:43.921Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined Git workflow management with integrated RAG knowledge base and 100+ tool compatibility.","zh":"非常适合需要简化Git工作流管理并集成RAG知识库和100+工具兼容性的开发代理。","ja":"開発エージェントがストリームライン化されたGitワークフロー管理と統合されたRAGナレッジベース、および100以上のツールの互換性を必要とする場合に最適です。","ko":"개발 에이전트가 스트림 라인화 된 Git 워크 플로우 관리와 통합 된 RAG 지식 베이스 및 100 이상의 도구 호환성을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de flujo de trabajo de Git optimizada con una base de conocimientos de RAG integrada y compatibilidad con más de 100 herramientas.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de workflow Git rationalisée avec une base de connaissances RAG intégrée et une compatibilité avec plus de 100 outils.","de":"Perfekt für Entwicklungsmittel, die eine optimierte Git-Workflow-Verwaltung mit integrierter RAG-Wissensbasis und Kompatibilität mit über 100 Tools benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento de fluxo de trabalho do Git simplificado com base de conhecimento RAG integrada e compatibilidade com 100+ ferramentas.","ru":"Идеально подходит для агентов разработки, которым необходим упрощенный менеджмент рабочего процесса Git с интегрированной базой знаний RAG и совместимостью более 100 инструментов.","ar":"مثالي لعملاقة التطوير الذين يحتاجون إلى إدارة تدفق عمل Git مبسط مع قاعدة معارف RAG متكاملة ومتوافقة مع أكثر من 100 أداة."},"recommendation":{"en":"Empowers agents to enforce critical Git rules, including branch protection, co-authored commits, and documentation updates, while utilizing protocols like git push and git pull, and integrating with tools through APIs and webhooks.","zh":"赋予代理人执行关键Git规则的能力，包括分支保护、共同提交和文档更新，同时利用诸如git push和git pull的协议，并通过API和webhook与工具集成。","ja":"エージェントが重要なGitルールを適用できるようにすることで、ブランチ保護、共同コミット、およびドキュメントの更新を行い、git pushやgit pullなどのプロトコルを利用し、APIやwebhookを介してツールと統合します。","ko":"에이전트가 중요한 Git 규칙을 적용할 수 있도록하여 브랜치 보호, 공동 커밋 및 문서 업데이트를 수행하며 git push 및 git pull와 같은 프로토콜을 활용하고 API 및 webhook을 통해 도구와 통합합니다.","es":"Habilita a los agentes a hacer cumplir reglas críticas de Git, incluida la protección de ramas, confirmaciones coautorizadas y actualizaciones de documentación, al mismo tiempo que utiliza protocolos como git push y git pull, e integrarse con herramientas a través de API y webhooks.","fr":"Permet aux agents d''appliquer des règles Git critiques, notamment la protection des branches, les validations de commits co-signées et les mises à jour de documentation, tout en utilisant des protocoles tels que git push et git pull, et en s''intégrant avec des outils via des API et des webhooks.","de":"Ermächtigt Agenten, kritische Git-Regeln durchzusetzen, einschließlich Branch-Schutz, Co-Autoren-Commits und Dokumenten-Aktualisierungen, während sie Protokolle wie git push und git pull nutzen und sich über APIs und Webhooks in Tools integrieren.","pt":"Habilita os agentes a impor regras críticas do Git, incluindo proteção de branch, commits co-autorados e atualizações de documentação, ao mesmo tempo em que utiliza protocolos como git push e git pull, e integra-se com ferramentas por meio de APIs e webhooks.","ru":"Наделяет агентов возможностью обеспечивать соблюдение критических правил Git, включая защиту веток, коммиты с соавторами и обновления документации, а также использовать протоколы như git push и git pull, и интегрироваться с инструментами через API и вебхуки.","ar":"يتمكن العميل من فرض قواعد جيت الحاسوبية الحرجة، بما في ذلك حماية الفرع والتعليقات المشتركة وتحديثات الوثائق، في الوقت نفسه الذي يستخدم فيه بروتوكولات مثل git push و git pull، ويتكامل مع الأدوات من خلال واجهات برمجة التطبيقات وال_IRQs_."},"useCases":{"en":["Automating commit message formatting","Enforcing branch protection policies","Validating documentation consistency with CLAUDE.md, docs/, and README files"],"zh":["自动化提交消息格式化","执行分支保护策略","验证文档一致性，包括CLAUDE.md、docs/和README文件"],"ja":["コミットメッセージの自動フォーマット","ブランチ保護ポリシーの適用","ドキュメントの一貫性の検証、CLAUDE.md、docs/、READMEファイルを含む"],"ko":["커밋 메시지 자동 형식화","브랜치 보호 정책 적용","문서 일관성 검증, CLAUDE.md, docs/, README 파일 포함"],"es":["Automatización del formato de mensajes de confirmación","Aplicación de políticas de protección de ramas","Validación de la coherencia de la documentación con archivos CLAUDE.md, docs/ y README"],"fr":["Automatisation du formatage des messages de validation","Application des politiques de protection des branches","Validation de la cohérence de la documentation avec les fichiers CLAUDE.md, docs/ et README"],"de":["Automatisierung der Formatierung von Commit-Nachrichten","Durchsetzung von Branch-Schutzrichtlinien","Validierung der Konsistenz der Dokumentation mit Dateien CLAUDE.md, docs/ und README"],"pt":["Automatizar formatação de mensagens de commit","Impor políticas de proteção de branch","Validar consistência de documentação com CLAUDE.md, docs/ e arquivos README"],"ru":["Автоматизировать форматирование сообщений коммитов","Внедрять политики защиты веток","Проверять согласованность документации с CLAUDE.md, docs/ и файлами README"],"ar":["أتمتة تنسيق رسائل Commit","فرض سياسات حماية الفرع","التحقق من الاتساق في الوثائق مع CLAUDE.md و docs/ وملفات README"]},"limitations":{"en":["Requires explicit user confirmation for git push operations","Limited to self-hosted AI assistant environments"],"zh":["需要显式用户确认以进行git push操作","仅限自托管AI助手环境"],"ja":["git push操作には明示的なユーザー確認が必要","セルフホスト型AIアシスタント環境のみ"],"ko":["git push 작업을 위해 명시적 사용자 확인이 필요","자체 호스팅 AI 어시스턴트 환경만"],"es":["Requiere confirmación explícita del usuario para operaciones de git push","Limitado a entornos de asistentes de inteligencia artificial autoalojados"],"fr":["Nécessite une confirmation explicite de l''utilisateur pour les opérations de git push","Limité à des environnements d''assistants d''intelligence artificielle auto-hébergés"],"de":["Benötigt eine explizite Benutzerbestätigung für git push-Vorgänge","Begrenzt auf selbst gehostete KI-Assistenten-Umgebungen"],"pt":["Exige confirmação explícita do usuário para operações git push","Limitado a ambientes de assistentes de IA auto-hospedados"],"ru":["Требует явительного подтверждения пользователя для операций git push","Ограничен средами самохостинга помощников ИИ"],"ar":["يتطلب تأكيدًا صريحًا من المستخدم لعمليات git push","محدود بالبيئات المضيفة الذاتية لمساعدي الذكاء الاصطناعي"]},"version":4},"contentHash":"eac8bed60118dbc9eccc0853360a0e977f8021d09cfcd4be6e2243dd1ac31ea3","qualityScore":30}');
