INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ebongard/renfield/git-workflow', 'git-workflow', 'ebongard', 'renfield', 'community', 'git-workflow ebongard renfield community ai-assistant docker knowledge-base knowledge-graph mcp offline-first ollama presence-detection privacy pwa rag raspberry-pi react self-hosted speaker-recognition typescript voice-assistant The git-workflow skill provides a self-hosted AI assistant with a set of critical rules for Git management, benefiting developers who need to streamline their workflow. It integrates with 100+ tools and features a RAG knowledge base. Git Workflow 是一个自托管的 AI 助手，集成了 100 多个工具，包括 FastAPI、React 和 Ollama。了解其关键规则和最佳实践 Git Workflow は、100以上のツールを統合したセルフホステッドのAIアシスタントです。FastAPI、React、Ollamaなどを含みます。重要なルールとベストプラクティスを学びましょう Git Workflow는 100개 이상의 도구를 통합한 자체 호스팅 AI 도구입니다. FastAPI, React, Ollama 등이 포함되어 있습니다. 주요 규칙과 최고의 실천 방법을 알아보세요 El flujo de trabajo de git es fundamental para el desarrollo de Agentes de Inteligencia Artificial. Conoce las mejores prácticas para configurarlo Le flux de travail git est essentiel pour le développement des Agents d''Intelligence Artificielle. Découvrez les meilleures pratiques pour le configurer Der Git-Workflow ist für die Entwicklung von KI-Agenten entscheidend. Erfahren Sie die besten Praktiken für die Einrichtung O fluxo de trabalho Git é uma ferramenta essencial para desenvolvedores de IA, permitindo a colaboração e o controle de versão de código com FastAPI e React. Поток работы Git является важнейшим инструментом для разработчиков ИИ, позволяющим сотрудничать и контролировать версии кода с FastAPI и React. مسار العمل جيت هو أداة أساسية لمطوري الذكاء الاصطناعي، مما يسمح بالتعاون ومراقبة إصدارات الكود مع FastAPI و React. how to use git-workflow git-workflow setup guide git-workflow alternative git-workflow vs gitflow git-workflow install what is git-workflow git-workflow best practices git-workflow for AI agents git-workflow and FastAPI git-workflow with React Git Workflow AI 工具集成 FastAPI React Ollama RAG 知识库 全离线能力 Co-Authored-By Commit 分支保护 Issue 编号 Enforces branch protection to prevent direct pushes to the main branch Requires issue numbers in every commit for better tracking Supports co-authored-by commits for collaborative development Mandates documentation updates before pushing changes Utilizes a specific commit message format for consistency git-workflow is a set of guidelines and rules for managing Git repositories, ensuring efficient collaboration and version control for developers and AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Blackhorse311/BotMind/bepinex', 'community', 'Blackhorse311', 'BotMind', 'Blackhorse311/BotMind', 'bepinex', 1, 0, 30, '2026-03-01T10:44:45Z', '2026-03-06T07:16:16.962Z', 'fc392c828bfd68b8549e2d0f8af63c0b03f25dbd17c764c113400304e2c9efe3', '{"id":"Blackhorse311/BotMind/bepinex","name":"bepinex","description":{"en":"BepInEx is a plugin framework for Unity game modding, specifically designed for SPT 4.0.12. It enables AI agents to enhance gameplay with features like looting, questing, and MedicBuddy.","zh":"BepInEx是一个Unity游戏模组框架，支持Harmony补丁和.NET Standard 2.1","ja":"BepInExはUnityゲームモッドのプラグインフレームワークであり、Harmonyパッチと.NET Standard 2.1をサポートしています","ko":"BepInEx는 Unity 게임 모드의 플러그인 프레임워크로서 Harmony 패치와 .NET Standard 2.1를 지원합니다","es":"BepInEx es un framework de plugins para mods de Unity. Se utiliza con .NET Standard 2.1 para mods de SPT.","fr":"BepInEx est un framework de plugins pour les mods Unity. Il est utilisé avec .NET Standard 2.1 pour les mods SPT.","de":"BepInEx ist ein Plugin-Framework für Unity-Mods. Es wird mit .NET Standard 2.1 für SPT-Mods verwendet.","pt":"BepInEx é um framework de plugins para modding de jogos Unity, utilizando .NET Standard 2.1 e Harmony para mods de SPT.","ru":"BepInEx — это фреймворк плагинов для моддинга игр на Unity, использующий .NET Standard 2.1 и Harmony для модов SPT.","ar":"BepInEx هو إطار عمل للبرامج المساعدة لتحسين mods ألعاب Unity، باستخدام .NET Standard 2.1 و Harmony لتحسين mods SPT."},"seo":{"title":{"en":"BepInEx: Unity Game Modding Setup Guide | AI Agent Skill","zh":"BepInEx AI工具集成指南","ja":"BepInEx AIエージェントのセットアップガイド","ko":"BepInEx AI 에이전트 설정 가이드","es":"Guía de configuración de BepInEx para SPT 4.0.12","fr":"Guide de démarrage rapide pour BepInEx avec SPT 4.0.12","de":"BepInEx-Setup-Anleitung für SPT 4.0.12","pt":"Guia de Configuração BepInEx para Modding de Jogos Unity","ru":"Настройка BepInEx для моддинга игр на Unity","ar":"دليل إعداد BepInEx لتحسين ألعاب Unity"},"description":{"en":"Unlock the full potential of SPT 4.0.12 with BepInEx, the ultimate plugin framework for Unity game modding. Learn how to install and setup BepInEx for AI age...","zh":"了解BepInEx的技术细节，包括Harmony补丁和.NET Standard 2.1集成","ja":"BepInExの技術的詳細を学び、Harmonyパッチと.NET Standard 2.1の統合について理解する","ko":"BepInEx의 기술적인 상세를 알아보고 Harmony 패치 및 .NET Standard 2.1 통합에 대해 학습하세요","es":"Descubre cómo configurar BepInEx con .NET Standard 2.1 para mods de SPT. Aprende sobre la integración de Harmony y ConfigFile.","fr":"Découvrez comment configurer BepInEx avec .NET Standard 2.1 pour les mods SPT. Apprenez à utiliser Harmony et ConfigFile.","de":"Erfahren Sie, wie Sie BepInEx mit .NET Standard 2.1 für SPT-Mods konfigurieren. Lernen Sie über die Integration von Harmony und ConfigFile.","pt":"Aprenda a configurar o BepInEx para mods de jogos Unity com .NET Standard 2.1 e Harmony","ru":"Узнайте, как настроить BepInEx для модов игр на Unity с .NET Standard 2.1 и Harmony","ar":"تعلم كيفية إعداد BepInEx لتحسين mods ألعاب Unity مع .NET Standard 2.1 و Harmony"},"definition":{"en":"BepInEx is a Unity game modding plugin framework that uses .NET Standard 2.1 and Harmony for patching, allowing developers to create custom plugins for SPT 4.0.12.","zh":"BepInEx是一个用于Unity游戏模组的插件框架","ja":"BepInExはUnityゲームモッド用のプラグインフレームワークです","ko":"BepInEx는 Unity 게임 모드 용 플러그인 프레임워크입니다","es":"BepInEx es un framework de plugins para mods de Unity que permite la creación de mods personalizados","fr":"BepInEx est un framework de plugins pour les mods Unity qui permet la création de mods personnalisés","de":"BepInEx ist ein Plugin-Framework für Unity-Mods, das die Erstellung von benutzerdefinierten Mods ermöglicht","pt":"O que é BepInEx? É um framework de plugins para modding de jogos Unity.","ru":"Что такое BepInEx? Это фреймворк плагинов для моддинга игр на Unity.","ar":"ما هو BepInEx؟ إنه إطار عمل للبرامج المساعدة لتحسين mods ألعاب Unity."},"features":{"en":["Loads plugins via [BepInPlugin] attributes","Uses ConfigFile for settings management","Employs Harmony for patching and modding","Supports .NET Standard 2.1 for SPT 4.0.12 modding","Enables creation of custom plugins for Unity games","Utilizes BepInDependency for dependency management"],"zh":["支持Harmony补丁","使用.NET Standard 2.1","通过ConfigFile进行设置","支持BepInDependency","使用BepInPlugin属性加载插件","兼容SPT 4.0.12"],"ja":["Harmonyパッチのサポート",".NET Standard 2.1の使用","ConfigFileによる設定","BepInDependencyのサポート","BepInPlugin属性によるプラグインのロード","SPT 4.0.12との互換性"],"ko":["Harmony 패치 지원",".NET Standard 2.1 사용","ConfigFile을 통한 설정","BepInDependency 지원","BepInPlugin 속성으로 플러그인 로드","SPT 4.0.12와의 호환성"],"es":["Compatibilidad con .NET Standard 2.1","Integración con Harmony para parches","Uso de ConfigFile para configuraciones","Carga de plugins a través de atributos [BepInPlugin]","Compatibilidad con SPT 4.0.12"],"fr":["Compatibilité avec .NET Standard 2.1","Intégration avec Harmony pour les patchs","Utilisation de ConfigFile pour les configurations","Chargement de plugins via les attributs [BepInPlugin]","Compatibilité avec SPT 4.0.12"],"de":["Kompatibilität mit .NET Standard 2.1","Integration mit Harmony für Patches","Verwendung von ConfigFile für Konfigurationen","Laden von Plugins über Attribute [BepInPlugin]","Kompatibilität mit SPT 4.0.12"],"pt":["Suporte a .NET Standard 2.1","Integração com Harmony para patches","Carregamento de plugins via atributos [BepInPlugin]","Uso de ConfigFile para configurações","Compatibilidade com mods de SPT"],"ru":["Поддержка .NET Standard 2.1","Интеграция с Harmony для патчей","Загрузка плагинов через атрибуты [BepInPlugin]","Использование ConfigFile для настроек","Совместимость с модами SPT"],"ar":["دعم .NET Standard 2.1","التكامل مع Harmony لتحسين patches","تحميل البرامج المساعدة عبر سمات [BepInPlugin]","استخدام ConfigFile لتحسين الإعدادات","التوافق مع mods SPT"]},"keywords":{"en":["how to use BepInEx","BepInEx setup guide","BepInEx vs Harmony","BepInEx install for SPT 4.0.12","what is BepInEx","BepInEx alternative for Unity game modding","BepInEx plugin framework","BepInEx for AI agents","BepInEx and .NET Standard 2.1","BepInEx game modding tutorials"],"zh":["BepInEx","Unity游戏模组","Harmony补丁",".NET Standard 2.1","SPT 4.0.12","AI工具","游戏模组开发","插件框架"],"ja":["BepInEx","Unityゲームモッド","Harmonyパッチ",".NET Standard 2.1","SPT 4.0.12","AIエージェント","ゲームモッド開発","プラグインフレームワーク"],"ko":["BepInEx","Unity 게임 모드","Harmony 패치",".NET Standard 2.1","SPT 4.0.12","AI 에이전트","게임 모드 개발","플러그인 프레임워크"],"es":["BepInEx","mods de Unity","SPT 4.0.12","plugins de Unity","Harmony","ConfigFile","desarrollo de mods","AI Agentes","Herramientas de AI"],"fr":["BepInEx","mods Unity","SPT 4.0.12","plugins Unity","Harmony","ConfigFile","développement de mods","Agents IA","Outils IA"],"de":["BepInEx","Unity-Mods","SPT 4.0.12","Unity-Plugins","Harmony","ConfigFile","Mod-Entwicklung","KI-Agenten","KI-Tools"],"pt":["BepInEx","modding de jogos Unity",".NET Standard 2.1","Harmony","plugins de jogos","mods de SPT","desenvolvimento de jogos","framework de plugins","configuração de BepInEx"],"ru":["BepInEx","моддинг игр на Unity",".NET Standard 2.1","Harmony","плагины игр","моды SPT","разработка игр","фреймворк плагинов","настройка BepInEx"],"ar":["BepInEx","تحسين mods ألعاب Unity",".NET Standard 2.1","Harmony","البرامج المساعدة لألعاب","mods SPT","تطوير الألعاب","إطار عمل للبرامج المساعدة","إعداد BepInEx"]}},"owner":"Blackhorse311","repo":"BotMind","repoPath":"Blackhorse311/BotMind","stars":1,"forks":0,"updatedAt":"2026-03-01T10:44:45Z","topics":[],"category":"community","skillMd":{"name":"bepinex","description":"|","bodyPreview":"# BepInEx Skill\n\nBepInEx is the plugin framework for Unity game modding. This project uses BepInEx 5.x with .NET Standard 2.1 for SPT (Single Player Tarkov) modding. Plugins are loaded via `[BepInPlugin]` attributes and use `ConfigFile` for settings. All patches use **Harmony** (see the **harmony** skill).\n\n## Quick Start\n\n### Plugin Entry Point\n\n```csharp\n[BepInPlugin(\"com.blackhorse311.botmind\", \"BotMind\", \"1.0.0\")]\n[BepInDependency(\"xyz.drakia.bigbrain\", BepInDependency.DependencyFlags.HardDe","body":"# BepInEx Skill\n\nBepInEx is the plugin framework for Unity game modding. This project uses BepInEx 5.x with .NET Standard 2.1 for SPT (Single Player Tarkov) modding. Plugins are loaded via `[BepInPlugin]` attributes and use `ConfigFile` for settings. All patches use **Harmony** (see the **harmony** skill).\n\n## Quick Start\n\n### Plugin Entry Point\n\n```csharp\n[BepInPlugin(\"com.blackhorse311.botmind\", \"BotMind\", \"1.0.0\")]\n[BepInDependency(\"xyz.drakia.bigbrain\", BepInDependency.DependencyFlags.HardDependency)]\n[BepInDependency(\"me.sol.sain\", BepInDependency.DependencyFlags.SoftDependency)]\npublic class BotMindPlugin : BaseUnityPlugin\n{\n    public static ManualLogSource Log { get; private set; }\n    \n    private void Awake()\n    {\n        Log = Logger;\n        Log.LogInfo(\"BotMind is loading...\");\n        \n        // Initialize configuration\n        BotMindConfig.Initialize(Config);\n        \n        // Apply Harmony patches\n        new Harmony(\"com.blackhorse311.botmind\").PatchAll();\n        \n        Log.LogInfo(\"BotMind loaded successfully!\");\n    }\n}\n```\n\n### Configuration Binding\n\n```csharp\npublic static class BotMindConfig\n{\n    public static ConfigEntry<bool> EnableLooting { get; private set; }\n    public static ConfigEntry<float> SearchRadius { get; private set; }\n    \n    public static void Initialize(ConfigFile config)\n    {\n        EnableLooting = config.Bind(\n            \"General\",           // Section\n            \"Enable Looting\",    // Key\n            true,                // Default\n            \"Enable bot looting behavior\"  // Description\n        );\n        \n        SearchRadius = config.Bind(\n            \"Looting\",\n            \"Search Radius\",\n            50f,\n            new ConfigDescription(\n                \"Loot search distance in meters\",\n                new AcceptableValueRange<float>(10f, 200f)\n            )\n        );\n    }\n}\n```\n\n## Key Concepts\n\n| Concept | Usage | Example |\n|---------|-------|---------|\n| Plugin GUID | Unique identifier | `\"com.author.modname\"` |\n| Hard dependency | Required mod | `DependencyFlags.HardDependency` |\n| Soft dependency | Optional mod | `DependencyFlags.SoftDependency` |\n| ConfigEntry | Runtime setting | `config.Bind(\"Section\", \"Key\", default)` |\n| ManualLogSource | Logging | `Logger.LogInfo(\"message\")` |\n\n## Common Patterns\n\n### Soft Dependency Check\n\n**When:** Integrating with optional mods like SAIN\n\n```csharp\nprivate static bool _sainChecked;\nprivate static bool _sainAvailable;\n\npublic static bool IsSAINAvailable()\n{\n    if (!_sainChecked)\n    {\n        _sainAvailable = Chainloader.PluginInfos.ContainsKey(\"me.sol.sain\");\n        _sainChecked = true;\n    }\n    return _sainAvailable;\n}\n```\n\n### Lifecycle Hooks\n\n**When:** Responding to game events\n\n```csharp\nprivate void Awake()    // Plugin load - register patches, config\nprivate void Start()    // After all plugins loaded\nprivate void OnEnable() // Plugin enabled\nprivate void OnDisable() // Plugin disabled\nprivate void OnDestroy() // Cleanup resources\n```\n\n## See Also\n\n- [patterns](references/patterns.md) - Plugin structure, config, logging\n- [workflows](references/workflows.md) - Build, deploy, debug\n\n## Related Skills\n\n- **harmony** - Patching game methods\n- **csharp** - Language patterns\n- **unity** - MonoBehaviour lifecycle\n- **dotnet** - Build and project configuration"},"lastSynced":"2026-03-06T07:16:16.962Z","agentAnalysis":{"suitability":{"en":"Perfect for Unity Game Modding Agents needing advanced plugin framework capabilities with Harmony patches and .NET Standard 2.1 support.","zh":"非常适合需要高级插件框架能力的Unity游戏模组代理，支持Harmony补丁和.NET Standard 2.1。","ja":"Unityゲームモッディングエージェントが高度なプラグインフレームワーク機能を必要とする場合に最適です。Harmonyパッチと.NET Standard 2.1をサポートしています。","ko":"고급 플러그인 프레임워크 기능과 Harmony 패치 및 .NET Standard 2.1 지원이 필요한 Unity 게임 모딩 에이전트에게 적합합니다.","es":"Perfecto para agentes de modificación de juegos de Unity que necesitan capacidades de framework de plugins avanzadas con parches de Harmony y soporte de .NET Standard 2.1.","fr":"Parfait pour les agents de modification de jeux Unity nécessitant des fonctionnalités de framework de plugins avancées avec des correctifs Harmony et la prise en charge de .NET Standard 2.1.","de":"Perfekt für Unity-Game-Modding-Agents, die erweiterte Plugin-Framework-Funktionen mit Harmony-Patches und .NET Standard 2.1-Unterstützung benötigen.","pt":"Perfeito para agentes de modding de jogos Unity que precisam de capacidades avançadas de framework de plugins com patches Harmony e suporte ao .NET Standard 2.1.","ru":"Идеально подходит для агентов моддинга игр Unity, которым требуются продвинутые возможности фреймворка плагинов с патчами Harmony и поддержкой .NET Standard 2.1.","ar":"مثالي لعميل تعديل ألعاب Unity الذين يحتاجون إلى إمكانيات إطارية متقدمة مع补ات Harmony ودعم .NET Standard 2.1."},"recommendation":{"en":"Empowers agents to enhance gameplay with features like looting, questing, and MedicBuddy using BepInEx 5.x, leveraging Harmony for patching and ConfigFile for settings, all within the Unity game modding ecosystem with SPT 4.0.12 compatibility.","zh":"赋予代理以BepInEx 5.x、Harmony用于补丁和ConfigFile用于设置等功能，增强游戏体验，例如战利品收集、任务和MedicBuddy等，所有这些都在Unity游戏模组生态系统中实现，且支持SPT 4.0.12。","ja":"BepInEx 5.x、Harmonyによるパッチ適用、ConfigFileによる設定などを使用して、エージェントがゲーム体験を強化できるようにします。たとえば、戦利品収集、クエスト、MedicBuddyなどの機能を実現します。すべてこれらはUnityゲームモッディングエコシステム内で実現され、SPT 4.0.12と互換性があります。","ko":"BepInEx 5.x, Harmony를 사용한 패치 및 ConfigFile을 사용한 설정 등을 사용하여 에이전트가 게임 플레이를 향상시키는 기능을 제공합니다. 예를 들어, 약탈, 퀘스트, MedicBuddy 등과 같은 기능을 제공하며, 모든 이러한 기능은 Unity 게임 모딩 에코시스템 내에서 제공되며, SPT 4.0.12와 호환됩니다.","es":"Permite a los agentes mejorar la experiencia de juego con características como saqueo, búsqueda y MedicBuddy utilizando BepInEx 5.x, aprovechando Harmony para la creación de parches y ConfigFile para la configuración, todo dentro del ecosistema de modificación de juegos de Unity con compatibilidad con SPT 4.0.12.","fr":"Permet aux agents d''améliorer l''expérience de jeu avec des fonctionnalités telles que le pillage, la quête et MedicBuddy en utilisant BepInEx 5.x, en exploitant Harmony pour le patching et ConfigFile pour les paramètres, le tout dans l''écosystème de modification de jeux Unity avec une compatibilité SPT 4.0.12.","de":"Ermächtigt Agents, das Gameplay mit Funktionen wie Plünderung, Questing und MedicBuddy zu verbessern, indem BepInEx 5.x verwendet wird, Harmony für das Patching und ConfigFile für die Einstellungen nutzt, all dies innerhalb des Unity-Game-Modding-Ökosystems mit SPT 4.0.12-Kompatibilität.","pt":"Habilita agentes a melhorar a jogabilidade com recursos como saque, busca e MedicBuddy usando BepInEx 5.x, aproveitando Harmony para patching e ConfigFile para configurações, tudo dentro do ecossistema de modding de jogos Unity com compatibilidade com SPT 4.0.12.","ru":"Наделяет агентов возможностью улучшить игровой процесс функциями, такими как мародерство, квестинг и MedicBuddy, используя BepInEx 5.x, используя Harmony для патчинга и ConfigFile для настроек, все внутри экосистемы моддинга игр Unity с совместимостью SPT 4.0.12.","ar":"تمكين العميل من تحسين اللعب باستخدام ميزات مثل السلب والبحث و MedicBuddy باستخدام BepInEx 5.x، واستخدام Harmony للتصحيح والملف.Config لالإعدادات، وكل ذلك داخل نظام ألعاب Unity مع توافق SPT 4.0.12."},"useCases":{"en":["Creating custom plugins for Single Player Tarkov modding","Enhancing gameplay with automated looting and questing features","Developing MedicBuddy integrations for improved player assistance"],"zh":["为Single Player Tarkov模组创建自定义插件","使用自动化战利品收集和任务功能来增强游戏体验","开发MedicBuddy集成以提高玩家辅助"],"ja":["Single Player Tarkovモッディング用のカスタムプラグインを作成する","自動化された戦利品収集やクエストなどの機能でゲーム体験を強化する","プレイヤー支援を向上させるためにMedicBuddyの統合を開発する"],"ko":["Single Player Tarkov 모딩을 위한 사용자 지정 플러그인 만들기","자동화된 약탈 및 퀘스트などの 기능을 사용하여 게임 플레이를 향상시키기","플레이어 지원을 개선하기 위한 MedicBuddy 통합 개발"],"es":["Creación de plugins personalizados para la modificación de Single Player Tarkov","Mejora del juego con características de saqueo y búsqueda automatizadas","Desarrollo de integraciones de MedicBuddy para una mejor asistencia al jugador"],"fr":["Création de plugins personnalisés pour la modification de Single Player Tarkov","Amélioration du jeu avec des fonctionnalités de pillage et de quête automatisées","Développement d''intégrations de MedicBuddy pour une meilleure assistance au joueur"],"de":["Erstellung benutzerdefinierter Plugins für die Modifikation von Single Player Tarkov","Verbesserung des Gameplays mit automatisierten Plünderungs- und Questing-Funktionen","Entwicklung von MedicBuddy-Integrationen für eine verbesserte Spielerunterstützung"],"pt":["Criação de plugins personalizados para modding de Single Player Tarkov","Melhoria da jogabilidade com recursos de saque e busca automatizados","Desenvolvimento de integrações do MedicBuddy para assistência de jogador melhorada"],"ru":["Создание пользовательских плагинов для моддинга Single Player Tarkov","Улучшение игрового процесса функциями автоматизированного мародерства и квестинга","Разработка интеграций MedicBuddy для улучшения помощи игроку"],"ar":["إنشاء ملحقات مخصصة لتعديل لاعب واحد Tarkov","تحسين اللعب باستخدام ميزات السلب والبحث التلقائي","تطوير دمج MedicBuddy لتحسين المساعدة اللاعب"]},"limitations":{"en":["Requires .NET Standard 2.1 compatibility","Specifically designed for SPT 4.0.12 and Unity game modding","Dependent on Harmony for patching functionality"],"zh":[".NET Standard 2.1兼容性要求","专门为SPT 4.0.12和Unity游戏模组设计","依赖Harmony用于补丁功能"],"ja":[".NET Standard 2.1の互換性が必要","SPT 4.0.12とUnityゲームモッディングのために特別に設計されています","パッチ機能にはHarmonyに依存します"],"ko":[".NET Standard 2.1 호환성 요구","SPT 4.0.12 및 Unity 게임 모딩을 위해 특별히 설계됨","패치 기능에 Harmony에 의존"],"es":["Requiere compatibilidad con .NET Standard 2.1","Diseñado específicamente para SPT 4.0.12 y la modificación de juegos de Unity","Dependiente de Harmony para la funcionalidad de patching"],"fr":["Nécessite la compatibilité avec .NET Standard 2.1","Conçu spécifiquement pour SPT 4.0.12 et la modification de jeux Unity","Dépendant de Harmony pour la fonctionnalité de patching"],"de":["Benötigt .NET Standard 2.1-Kompatibilität","Speziell für SPT 4.0.12 und Unity-Game-Modding entwickelt","Abhängig von Harmony für die Patching-Funktionalität"],"pt":["Exige compatibilidade com .NET Standard 2.1","Projetado especificamente para SPT 4.0.12 e modding de jogos Unity","Dependente de Harmony para funcionalidade de patching"],"ru":["Требует совместимости с .NET Standard 2.1","Разработан специально для SPT 4.0.12 и моддинга игр Unity","Зависит от Harmony для функциональности патчинга"],"ar":["يتطلب توافقًا مع .NET Standard 2.1","صمّم خصيصًا لـ SPT 4.0.12 وتعديل ألعاب Unity","يعتمد على Harmony لوظيفة التصحيح"]},"version":4},"contentHash":"fc392c828bfd68b8549e2d0f8af63c0b03f25dbd17c764c113400304e2c9efe3","qualityScore":30}');
