INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Blackhorse311/BotMind/bepinex', 'bepinex', 'Blackhorse311', 'BotMind', 'community', 'bepinex Blackhorse311 BotMind community BepInEx is a plugin framework for Unity game modding, specifically designed for SPT 4.0.12. It enables AI agents to enhance gameplay with features like looting, questing, and MedicBuddy. BepInEx是一个Unity游戏模组框架，支持Harmony补丁和.NET Standard 2.1 BepInExはUnityゲームモッドのプラグインフレームワークであり、Harmonyパッチと.NET Standard 2.1をサポートしています BepInEx는 Unity 게임 모드의 플러그인 프레임워크로서 Harmony 패치와 .NET Standard 2.1를 지원합니다 BepInEx es un framework de plugins para mods de Unity. Se utiliza con .NET Standard 2.1 para mods de SPT. BepInEx est un framework de plugins pour les mods Unity. Il est utilisé avec .NET Standard 2.1 pour les mods SPT. BepInEx ist ein Plugin-Framework für Unity-Mods. Es wird mit .NET Standard 2.1 für SPT-Mods verwendet. BepInEx é um framework de plugins para modding de jogos Unity, utilizando .NET Standard 2.1 e Harmony para mods de SPT. BepInEx — это фреймворк плагинов для моддинга игр на Unity, использующий .NET Standard 2.1 и Harmony для модов SPT. BepInEx هو إطار عمل للبرامج المساعدة لتحسين mods ألعاب Unity، باستخدام .NET Standard 2.1 و Harmony لتحسين mods SPT. how to use BepInEx BepInEx setup guide BepInEx vs Harmony BepInEx install for SPT 4.0.12 what is BepInEx BepInEx alternative for Unity game modding BepInEx plugin framework BepInEx for AI agents BepInEx and .NET Standard 2.1 BepInEx game modding tutorials BepInEx Unity游戏模组 Harmony补丁 .NET Standard 2.1 SPT 4.0.12 AI工具 游戏模组开发 插件框架 Loads plugins via [BepInPlugin] attributes Uses ConfigFile for settings management Employs Harmony for patching and modding Supports .NET Standard 2.1 for SPT 4.0.12 modding Enables creation of custom plugins for Unity games Utilizes BepInDependency for dependency management BepInEx is a Unity game modding plugin framework that uses .NET Standard 2.1 and Harmony for patching, allowing developers to create custom plugins for SPT 4.0.12.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anabelle/acars.pub/nostr', 'community', 'anabelle', 'acars.pub', 'anabelle/acars.pub', 'nostr', 1, 0, 30, '2026-02-28T00:59:06Z', '2026-03-06T07:16:05.830Z', '1916e20ad165717e7ab21867e45a9f279acb9df33c4abb5c9872365962f4967f', '{"id":"anabelle/acars.pub/nostr","name":"nostr","description":{"en":"The nostr skill enables developers to simulate airlines using the open nostr protocol, providing a censorship-resistant and global social network solution.","zh":"Nostr 协议是一种简单的开源协议，允许使用加密密钥和签名构建真正的抗审查和全球社交网络","ja":"Nostr プロトコルは、暗号鍵と署名を使用して真正の検閲耐性とグローバルなソーシャルネットワークを実現するためのシンプルでオープンなプロトコルです","ko":"Nostr 프로토콜은 암호화 키와 서명을 사용하여真正의 검열에 강한 글로벌 소셜 네트워크를 구축하는 단순하고 개방형 프로토콜입니다","es":"Nostr es un protocolo abierto que permite la creación de redes sociales resistentes a la censura y globales utilizando claves y firmas criptográficas","fr":"Nostr est un protocole ouvert qui permet de créer des réseaux sociaux résistants à la censura et mondiaux en utilisant des clés et des signatures cryptographiques","de":"Nostr ist ein offenes Protokoll, das die Erstellung von zensurresistenten und globalen sozialen Netzwerken mit kryptographischen Schlüsseln und Signaturen ermöglicht","pt":"O Nostr é um protocolo simples e aberto que permite redes sociais globais e resistentes à censura. Aprenda a configurá-lo para simulações de companhias aéreas.","ru":"Nostr — простой и открытый протокол, позволяющий создавать глобальные социальные сети с устойчивостью к цензуре. Узнайте, как настроить его для симуляции авиакомпаний.","ar":"Nostr هو بروتوكول بسيط ومفتوح يسمح بإنشاء شبكات اجتماعية عالمية ومقاومة للرقابة. تعلم كيفية إعدادته لمحاكاة شركة طيران."},"seo":{"title":{"en":"nostr: Airlines Simulator Setup Guide | AI Agent Skill","zh":"Nostr 协议中文指南 - 无审查社交网络搭建","ja":"Nostr プロトコル入門 - AIエージェントによる検閲耐性のあるソーシャルネットワークの構築","ko":"Nostr 프로토콜 한국어 가이드 - 검열에 강한 글로벌 소셜 네트워크 구축","es":"Guía de configuración de Nostr para simuladores de aerolí...","fr":"Guide de configuration de Nostr pour les simulateurs d''av...","de":"Nostr-Konfigurationsleitfaden für Fluglinien-Simulatoren","pt":"Guia de Configuração do Nostr: Simulador de Companhias Aé...","ru":"Настройка Nostr: Руководство по симуляции авиакомпаний с ...","ar":"دليل إعداد Nostr: محاكي شركة طيران مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the power of nostr protocol for AI agents. Learn how to simulate airlines with nostr and explore its censorship-resistant social networks.","zh":"了解 Nostr 协议的工作原理，搭建无审查的社交网络，并发现 NIPs 文档库中的更多信息","ja":"Nostr プロトコルを使用して検閲耐性のあるソーシャルネットワークを構築し、NIPs リポジトリで詳細を確認する","ko":"Nostr 프로토콜을 사용하여 검열에 강한 소셜 네트워크를 구축하고 NIPs 문서에서 자세한 정보를 확인하세요","es":"Aprende a configurar Nostr para crear redes sociales resistentes a la censura y globales con claves y firmas criptográficas","fr":"Découvrez comment configurer Nostr pour créer des réseaux sociaux résistants à la censure et mondiaux avec des clés et des signatures cryptographiques","de":"Erfahren Sie, wie Sie Nostr konfigurieren, um zensurresistente und globale soziale Netzwerke mit kryptographischen Schlüsseln und Signaturen zu erstellen","pt":"Aprenda a configurar o Nostr para simulações de companhias aéreas com resistência à censura e redes sociais globais","ru":"Узнайте, как настроить Nostr для симуляции авиакомпаний с помощью ИИ Агентов и глобальных социальных сетей","ar":"تعلم كيفية إعداد Nostr لتحاكي شركة طيران مع أدوات الذكاء الاصطناعي وقاعدة اجتماعية عالمية"},"definition":{"en":"nostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.","zh":"Nostr 协议是一种开源协议，实现抗审查和全球社交网络","ja":"Nostr プロトコルは、検閲耐性とグローバルなソーシャルネットワークを実現するオープンなプロトコル","ko":"Nostr 프로토콜은 검열에 강한 글로벌 소셜 네트워크를 구축하는 개방형 프로토콜","es":"Nostr es un protocolo de red social descentralizado que utiliza claves y firmas criptográficas","fr":"Nostr est un protocole de réseau social décentralisé qui utilise des clés et des signatures cryptographiques","de":"Nostr ist ein dezentrales soziales Netzwerkprotokoll, das kryptographische Schlüssel und Signaturen verwendet","pt":"O Nostr é um protocolo que permite redes sociais globais e resistentes à censura usando chaves e assinaturas criptográficas","ru":"Nostr — протокол, позволяющий создавать глобальные социальные сети с устойчивостью к цензуре, используя криптографические ключи и подписи","ar":"Nostr هو بروتوكول يسمح بإنشاء شبكات اجتماعية عالمية ومقاومة للرقابة باستخدام مفاتيح وتوقيعات تشفير"},"features":{"en":["Utilizes cryptographic keys and signatures for secure communication","Supports global social networks with censorship-resistant architecture","Provides access to Nostr Implementation Possibilities (NIPs) repository","Enables fetching of individual NIPs from GitHub repository","Leverages NIP-01 for basic protocol implementation","Integrates with Airlines Simulator for realistic scenario modeling"],"zh":["使用加密密钥和签名实现抗审查","支持全球社交网络的构建","NIPs 文档库提供详细的实现信息","简单的开源协议","支持多种开发语言"],"ja":["暗号鍵と署名を使用した検閲耐性のある構築","グローバルなソーシャルネットワークの構築をサポート","NIPs リポジトリで詳細な実装情報を提供","シンプルでオープンなプロトコル","多くの開発言語をサポート"],"ko":["암호화 키와 서명을 사용하여 검열에 강한 구축","글로벌 소셜 네트워크 구축 지원","NIPs 문서에서 자세한 구현 정보 제공","단순하고 개방형 프로토콜","다수의 개발 언어 지원"],"es":["Utiliza claves y firmas criptográficas para la autenticación","Permite la creación de redes sociales resistentes a la censura","Es un protocolo abierto y descentralizado","Utiliza el repositorio NIPs (Nostr Implementation Possibilities) para la documentación","Permite la lectura de NIPs individuales a través de GitHub"],"fr":["Utilise des clés et des signatures cryptographiques pour l''authentification","Permet la création de réseaux sociaux résistants à la censure","Est un protocole ouvert et décentralisé","Utilise le référentiel NIPs (Nostr Implementation Possibilities) pour la documentation","Permet la lecture de NIPs individuels à travers GitHub"],"de":["Verwendet kryptographische Schlüssel und Signaturen für die Authentifizierung","Ermöglicht die Erstellung von zensurresistenten sozialen Netzwerken","Ist ein offenes und dezentrales Protokoll","Verwendet das Repository NIPs (Nostr Implementation Possibilities) für die Dokumentation","Ermöglicht die Lesung von NIPs über GitHub"],"pt":["Suporte a redes sociais globais","Resistência à censura usando chaves e assinaturas criptográficas","Acesso a documentação do Nostr via NIPs","Simulação de companhias aéreas com Airlines Simulator","Uso de protocolo simples e aberto"],"ru":["Поддержка глобальных социальных сетей","Устойчивость к цензуре с помощью криптографических ключей и подписей","Доступ к документации Nostr через NIPs","Симуляция авиакомпаний с Airlines Simulator","Использование простого и открытого протокола"],"ar":["دعم الشبكات الاجتماعية العالمية","مقاومة الرقابة باستخدام مفاتيح وتوقيعات تشفير","الوصول إلى توثيق Nostr عبر NIPs","محاكاة شركة طيران مع Airlines Simulator","استخدام بروتوكول بسيط ومفتوح"]},"keywords":{"en":["how to use nostr protocol","what is nostr","nostr alternative","nostr vs other protocols","nostr install guide","nostr setup for AI agents","nostr airlines simulator","censorship-resistant social networks","global social network solutions"],"zh":["Nostr 协议","抗审查社交网络","开源协议","加密密钥","签名","NIPs 文档库","社交网络开发","AIエージェント"],"ja":["Nostr プロトコル","検閲耐性のあるソーシャルネットワーク","オープンなプロトコル","暗号鍵","署名","NIPs リポジトリ","ソーシャルネットワーク開発","AIエージェント"],"ko":["Nostr 프로토콜","검열에 강한 소셜 네트워크","개방형 프로토콜","암호화 키","서명","NIPs 문서","소셜 네트워크 개발","AI 에이전트"],"es":["Nostr protocolo","redes sociales descentralizadas","claves criptográficas","firmas criptográficas","NIPs","GitHub","simuladores de aerolíneas","herramientas de AI","agentes de IA"],"fr":["protocole Nostr","réseaux sociaux décentralisés","clés cryptographiques","signatures cryptographiques","NIPs","GitHub","simulateurs d''aviation","outils d''IA","agents d''IA"],"de":["Nostr-Protokoll","dezentrale soziale Netzwerke","kryptographische Schlüssel","kryptographische Signaturen","NIPs","GitHub","Fluglinien-Simulatoren","AI-Tools","KI-Agenten"],"pt":["Nostr","Simulador de companhias aéreas","Redes sociais globais","Resistência à censura","Chaves criptográficas","Assinaturas criptográficas","NIPs","Airlines Simulator"],"ru":["Nostr","Симулятор авиакомпаний","Глобальные социальные сети","Устойчивость к цензуре","Криптографические ключи","Криптографические подписи","NIPs","Airlines Simulator","ИИ Агенты"],"ar":["Nostr","محاكي شركة طيران","شبكات اجتماعية عالمية","مقاومة الرقابة","مفاتيح تشفير","توقيعات تشفير","NIPs","Airlines Simulator","أدوات الذكاء الاصطناعي"]}},"owner":"anabelle","repo":"acars.pub","repoPath":"anabelle/acars.pub","stars":1,"forks":0,"updatedAt":"2026-02-28T00:59:06Z","topics":[],"category":"community","skillMd":{"name":"nostr","description":"Knowledge about the Nostr protocol. Use to view up-to-date NIPs, discover capabilities of the Nostr protocol, and to implement Nostr functionality correctly.","bodyPreview":"# Nostr Protocol\n\nNostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.\n\n## Finding Nostr Documentation\n\nAll Nostr protocol documentation is maintained in the NIPs (Nostr Implementation Possibilities) repository. To access this information:\n\n### Reading Individual NIPs\n\nIndividual NIPs can be fetched from:\n```\nhttps://github.com/nostr-protocol/nips/blob/master/{NIP}.md\n```\n\nFor example, NIP-01 (the basic proto","body":"# Nostr Protocol\n\nNostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.\n\n## Finding Nostr Documentation\n\nAll Nostr protocol documentation is maintained in the NIPs (Nostr Implementation Possibilities) repository. To access this information:\n\n### Reading Individual NIPs\n\nIndividual NIPs can be fetched from:\n```\nhttps://github.com/nostr-protocol/nips/blob/master/{NIP}.md\n```\n\nFor example, NIP-01 (the basic protocol specification) is available at:\n```\nhttps://github.com/nostr-protocol/nips/blob/master/01.md\n```\n\n### Finding Event Kinds\n\nDocumentation for Nostr event kinds is spread across one or more NIPs. **There is no direct relationship between the NIP number and the kind number.**\n\nTo find which NIPs document a specific event kind:\n\n1. First, fetch the README:\n   ```\n   https://github.com/nostr-protocol/nips/blob/master/README.md\n   ```\n\n2. Reference the \"Event Kinds\" table in the README to find which NIP(s) document the kind you''re looking for\n\n### Discovering Existing Capabilities\n\nThe README should be consulted to:\n\n- **View the list of NIPs** - Use this to discover what capabilities already exist on the Nostr network\n- **Review client and relay messages** - Understand the communication protocol\n- **Check the list of tags** - See what standardized tags are available\n- **Decide on using existing NIPs** - Before implementing a feature, check if an existing NIP already covers it\n\n### Best Practices\n\nAlways start by fetching and reviewing the README to understand the current state of the protocol and avoid reinventing existing functionality.\n"},"lastSynced":"2026-03-06T07:16:05.830Z","agentAnalysis":{"suitability":{"en":"Ideal for Decentralized Social Network Agents utilizing the open nostr protocol for censorship-resistant communication.","zh":"适用于利用开放的nostr协议进行抗审查通信的去中心化社交网络代理。","ja":"nostrプロトコルを使用した検閲耐性のある通信を実現する分散型ソーシャルネットワークエージェントに最適。","ko":"nostr 프로토콜을 사용한 검열에 강한 통신을 제공하는 분산형 소셜 네트워크 에이전트에 적합합니다.","es":"Ideal para Agentes de Redes Sociales Descentralizadas que utilizan el protocolo abierto nostr para comunicación resistente a la censura.","fr":"Idéal pour les agents de réseaux sociaux décentralisés utilisant le protocole ouvert nostr pour une communication résistante à la censure.","de":"Ideal für dezentrale soziale Netzwerkagenten, die das offene nostr-Protokoll für zensurresistente Kommunikation nutzen.","pt":"Ideal para Agentes de Rede Social Descentralizada que utilizam o protocolo open nostr para comunicação resistente à censura.","ru":"Идеально для децентрализованных социальных сетей, использующих открытый протокол nostr для цензуроустойчивой связи.","ar":"مثالي للوكلاء الاجتماعيين اللامركزيين الذين يستخدمون بروتوكول nostr مفتوح المصدر للاتصالات المقاومة للرقابة."},"recommendation":{"en":"Empowers agents to simulate airlines and interact with the nostr network using cryptographic keys and signatures, providing a global social network solution with NIPs documentation for implementation possibilities.","zh":"赋予代理模拟航空公司并使用加密密钥和签名与nostr网络交互的能力，提供一个具有NIPs文档的全球社交网络解决方案以实现各种可能性。","ja":"エージェントが航空会社をシミュレートし、加密鍵と署名を使用してnostrネットワークとやり取りすることを可能にし、NIPsドキュメントを使用した実装の可能性を持つグローバルソーシャルネットワークソリューションを提供する。","ko":"에이전트가 항공사를 시뮬레이션하고 암호화 키 및 서명을 사용하여 nostr 네트워크와 상호 작용할 수 있도록 하여 NIPs 문서를 사용한 구현 가능성과 함께全球 소셜 네트워크 솔루션을 제공합니다.","es":"Habilita a los agentes a simular aerolíneas y interactuar con la red nostr utilizando claves y firmas criptográficas, proporcionando una solución de red social global con documentación de NIPs para posibilidades de implementación.","fr":"Permet aux agents de simuler des compagnies aériennes et d''interagir avec le réseau nostr en utilisant des clés et des signatures cryptographiques, fournissant une solution de réseau social global avec une documentation NIPs pour les possibilités de mise en œuvre.","de":"Ermächtigt Agenten, Fluggesellschaften zu simulieren und mit dem nostr-Netzwerk unter Verwendung von kryptografischen Schlüsseln und Signaturen zu interagieren, wodurch eine globale soziale Netzwerklösung mit NIPs-Dokumentation für Implementierungsmöglichkeiten bereitgestellt wird.","pt":"Habilita agentes a simular companhias aéreas e interagir com a rede nostr usando chaves e assinaturas criptográficas, fornecendo uma solução de rede social global com documentação de NIPs para possibilidades de implementação.","ru":"Наделяет агентов возможностью симулировать авиакомпании и взаимодействовать с сетью nostr, используя криптографические ключи и подписи, обеспечивая глобальное решение социальной сети с документацией NIPs для возможностей реализации.","ar":"تمكين الوكلاء من محاكاة شركات الطيران والتفاعل مع شبكة nostr باستخدام المفاتيح والتوقيعات المعمّاة، وتوفير حل mạng اجتماعي عالمي مع توثيق NIPs لإمكانيات التنفيذ."},"useCases":{"en":["Simulating decentralized social networks","Implementing censorship-resistant communication protocols","Fetching individual NIPs for customization"],"zh":["模拟去中心化社交网络","实现抗审查通信协议","获取个性化的NIPs"],"ja":["分散型ソーシャルネットワークのシミュレーション","検閲耐性のある通信プロトコルの実装","カスタマイズされたNIPsの取得"],"ko":["분산형 소셜 네트워크 시뮬레이션","검열에 강한 통신 프로토콜 구현","개인화된 NIPs 가져오기"],"es":["Simulación de redes sociales descentralizadas","Implementación de protocolos de comunicación resistentes a la censura","Recuperación de NIPs individuales para personalización"],"fr":["Simulation de réseaux sociaux décentralisés","Mise en œuvre de protocoles de communication résistants à la censure","Récupération de NIPs individuels pour personnalisation"],"de":["Simulation dezentraler sozialer Netzwerke","Implementierung zensurresistenter Kommunikationsprotokolle","Abrufen individueller NIPs für Anpassung"],"pt":["Simulando redes sociais descentralizadas","Implementando protocolos de comunicação resistentes à censura","Recuperando NIPs individuais para personalização"],"ru":["Симуляция децентрализованных социальных сетей","Реализация протоколов цензуроустойчивой связи","Получение индивидуальных NIPs для настройки"],"ar":["محاكاة الشبكات الاجتماعية اللامركزية","تنفيذ بروتوكولات الاتصالات المقاومة للرقابة","استرجاع NIPs الفردية للتخصيص"]},"limitations":{"en":["Requires understanding of cryptographic keys and signatures","Nostr protocol specific","NIPs documentation required for implementation"],"zh":["需要了解加密密钥和签名","特定于nostr协议","需要NIPs文档进行实现"],"ja":["加密鍵と署名の理解が必要","nostrプロトコル限定","実装にはNIPsドキュメントが必要"],"ko":["암호화 키 및 서명의 이해가 필요합니다.","nostr 프로토콜 전용","구현을 위해 NIPs 문서가 필요합니다."],"es":["Requiere comprensión de claves y firmas criptográficas","Específico del protocolo nostr","Se requiere documentación de NIPs para la implementación"],"fr":["Nécessite une compréhension des clés et des signatures cryptographiques","Spécifique du protocole nostr","Documentation NIPs requise pour la mise en œuvre"],"de":["Erfordert das Verständnis von kryptografischen Schlüsseln und Signaturen","Spezifisch für das nostr-Protokoll","NIPs-Dokumentation erforderlich für die Implementierung"],"pt":["Requer entendimento de chaves e assinaturas criptográficas","Específico do protocolo nostr","Documentação de NIPs necessária para implementação"],"ru":["Требует понимания криптографических ключей и подписей","Специфичен для протокола nostr","Требуется документация NIPs для реализации"],"ar":["يتطلب فهم المفاتيح والتوقيعات المعمّاة","محدد لبروتوكول nostr","يتطلب توثيق NIPs للتنفيذ"]},"version":4},"contentHash":"1916e20ad165717e7ab21867e45a9f279acb9df33c4abb5c9872365962f4967f","qualityScore":30}');
