INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anabelle/acars.pub/nostr', 'nostr', 'anabelle', 'acars.pub', 'community', 'nostr anabelle acars.pub community The nostr skill enables developers to simulate airlines using the open nostr protocol, providing a censorship-resistant and global social network solution. Nostr 协议是一种简单的开源协议，允许使用加密密钥和签名构建真正的抗审查和全球社交网络 Nostr プロトコルは、暗号鍵と署名を使用して真正の検閲耐性とグローバルなソーシャルネットワークを実現するためのシンプルでオープンなプロトコルです Nostr 프로토콜은 암호화 키와 서명을 사용하여真正의 검열에 강한 글로벌 소셜 네트워크를 구축하는 단순하고 개방형 프로토콜입니다 Nostr es un protocolo abierto que permite la creación de redes sociales resistentes a la censura y globales utilizando claves y firmas criptográficas Nostr est un protocole ouvert qui permet de créer des réseaux sociaux résistants à la censura et mondiaux en utilisant des clés et des signatures cryptographiques Nostr ist ein offenes Protokoll, das die Erstellung von zensurresistenten und globalen sozialen Netzwerken mit kryptographischen Schlüsseln und Signaturen ermöglicht O Nostr é um protocolo simples e aberto que permite redes sociais globais e resistentes à censura. Aprenda a configurá-lo para simulações de companhias aéreas. Nostr — простой и открытый протокол, позволяющий создавать глобальные социальные сети с устойчивостью к цензуре. Узнайте, как настроить его для симуляции авиакомпаний. Nostr هو بروتوكول بسيط ومفتوح يسمح بإنشاء شبكات اجتماعية عالمية ومقاومة للرقابة. تعلم كيفية إعدادته لمحاكاة شركة طيران. how to use nostr protocol what is nostr nostr alternative nostr vs other protocols nostr install guide nostr setup for AI agents nostr airlines simulator censorship-resistant social networks global social network solutions Nostr 协议 抗审查社交网络 开源协议 加密密钥 签名 NIPs 文档库 社交网络开发 AIエージェント Utilizes cryptographic keys and signatures for secure communication Supports global social networks with censorship-resistant architecture Provides access to Nostr Implementation Possibilities (NIPs) repository Enables fetching of individual NIPs from GitHub repository Leverages NIP-01 for basic protocol implementation Integrates with Airlines Simulator for realistic scenario modeling nostr is a simple, open protocol that enables truly censorship-resistant and global social networks using cryptographic keys and signatures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('holEeast979/On-Device-LMM-Reasoning-Acceleration/pickup', 'community', 'holEeast979', 'On-Device-LMM-Reasoning-Acceleration', 'holEeast979/On-Device-LMM-Reasoning-Acceleration', 'pickup', 1, 0, 30, '2026-03-02T08:22:44Z', '2026-03-06T13:09:45.116Z', '7633fb1ac669d49a58bc4cdbb78682c2e4c494f1b2eef13639d8c23680865b04', '{"id":"holEeast979/On-Device-LMM-Reasoning-Acceleration/pickup","name":"pickup","description":{"en":"The pickup skill enables AI agents to continue conversations from where they left off, benefiting developers who need to manage complex dialogue flows. It reads PROGRESS.md and checks tmux sessions for efficient task handling.","zh":"pickup功能允许用户在新对话开始时继续上次的进度，通过读取PROGRESS.md和检查后台任务","ja":"pickup機能は、ユーザーが新しい会話を開始したときに前の会話の進度を継続できるようにします","ko":"pickup 기능은 새로운 대화 시작 시 이전 대화의 진행状況을 계속할 수 있도록 합니다","es":"El skill pickup permite a los Agentes de IA leer el archivo PROGRESS.md y entender el estado actual de la conversación","fr":"Le skill pickup permet aux Outils d''IA de lire le fichier PROGRESS.md et de comprendre l''état actuel de la conversation","de":"Das pickup-Skill ermöglicht es KI-Agents, die Datei PROGRESS.md zu lesen und den aktuellen Zustand des Dialogs zu verstehen","pt":"O pickup é uma habilidade que permite a continuação de conversas, lendo PROGRESS.md e verificando tarefas em segundo plano","ru":"Pickup - это навык, который позволяет продолжать разговоры, читая PROGRESS.md и проверяя фоновіх задач","ar":"Pickup هو مهارة تسمح بمواصلة المحادثات، وقراءة PROGRESS.md وفرصة المهام في الخلفية"},"seo":{"title":{"en":"pickup: Setup Guide for AI Agents","zh":"pickup 技术指南：新对话接续最佳实践","ja":"AIエージェントのpickup機能：新しい会話の継続方法","ko":"pickup 기능 설정 가이드: 새로운 대화 연속성","es":"Guía de configuración de pickup para Agentes de IA","fr":"Guide de configuration de pickup pour les Outils d''IA","de":"Einrichtungsleitfaden für pickup in KI-Agents","pt":"Guia de Configuração do Pickup: Integração de Ferramentas...","ru":"Настройка Pickup: Руководство по интеграции ИИ Агентов","ar":"دليل إعداد Pickup: دمج أدوات الإي الأجنت"},"description":{"en":"Discover how to implement the pickup skill for seamless conversation handoffs. Learn how to read PROGRESS.md and utilize tmux for efficient task management.","zh":"了解如何使用pickup功能实现新对话接续，包括读取PROGRESS.md和检查后台任务","ja":"AIエージェントのpickup機能を使用して新しい会話を継続する方法を学ぶ","ko":"pickup 기능을 사용하여 새로운 대화 연속성을 구현하는 방법을 알아보세요","es":"Aprende a configurar pickup para Agentes de IA y optimiza tus procesos de diálogo","fr":"Découvrez comment configurer pickup pour les Outils d''IA et améliorer vos processus de dialogue","de":"Erfahren Sie, wie Sie pickup für KI-Agents einrichten und Ihre Dialogprozesse optimieren","pt":"Aprenda a configurar o pickup para Ferramentas de IA, incluindo a leitura de PROGRESS.md e a verificação de tarefas em segundo plano","ru":"Узнайте, как настроить pickup для ИИ Агентов, включая чтение PROGRESS.md и проверку фонових задач","ar":"تعرف على كيفية إعداد Pickup لأدوات الإي الأجنت، بما في ذلك قراءة PROGRESS.md وفرصة المهام في الخلفية"},"definition":{"en":"pickup is a skill that allows AI agents to resume conversations by reading PROGRESS.md and utilizing tmux for task management","zh":"pickup功能是一种新对话接续技术，允许用户继续上次的进度","ja":"pickup機能は、新しい会話の継続性を実現するための技術です","ko":"pickup 기능은 새로운 대화 연속성을 구현하는 기술입니다","es":"pickup es un skill que permite a los Agentes de IA leer el archivo PROGRESS.md y entender el estado actual de la conversación","fr":"pickup est un skill qui permet aux Outils d''IA de lire le fichier PROGRESS.md et de comprendre l''état actuel de la conversation","de":"pickup ist ein Skill, der es KI-Agents ermöglicht, die Datei PROGRESS.md zu lesen und den aktuellen Zustand des Dialogs zu verstehen","pt":"O que é pickup? É uma habilidade de Ferramentas de IA que permite a continuação de conversas","ru":"Что такое pickup? Это навык ИИ Агентов, который позволяет продолжать разговоры","ar":"ما هي Pickup؟ إنه مهارة لأدوات الإي الأجنت التي تسمح بمواصلة المحادثات"},"features":{"en":["Reads PROGRESS.md to understand current conversation state","Utilizes tmux to check and manage background tasks","Supports BLUF format for concise status reporting","Executes tasks based on ''立即执行事项'' in PROGRESS.md","Compatible with /handoff prompts for precise conversation handoffs","Automatically captures and reports on task progress using tmux capture-pane"],"zh":["读取PROGRESS.md文件","检查后台任务的进度","支持tmux实验","使用BLUF格式汇报当前状态","列出立即执行事项"],"ja":["PROGRESS.mdファイルの読み取り","バックグラウンドタスクの進度の確認","tmux実験のサポート","BLUF形式の現在の状態の報告","実行すべき事項のリスト"],"ko":["PROGRESS.md 파일 읽기","백그라운드 작업 진행 상황 확인","tmux 실험 지원","BLUF 형식의 현재 상태 보고","즉시 실행 항목 목록"],"es":["Lectura del archivo PROGRESS.md","Comprobación de tareas en segundo plano con tmux","Informe del estado actual en formato BLUF","Ejecución de acciones inmediatas","Integración con la CLI para ejecutar comandos"],"fr":["Lecture du fichier PROGRESS.md","Vérification des tâches en arrière-plan avec tmux","Rapport d''état actuel au format BLUF","Exécution d''actions immédiates","Intégration avec la CLI pour exécuter des commandes"],"de":["Lesevorgang der Datei PROGRESS.md","Überprüfung von Hintergrundtasks mit tmux","Bericht über den aktuellen Zustand im BLUF-Format","Ausführung von Sofortmaßnahmen","Integration mit der CLI zur Ausführung von Befehlen"],"pt":["Leitura de PROGRESS.md","Verificação de tarefas em segundo plano com tmux","Suporte à continuação de conversas","Integração com CLI","Relatório de status em formato BLUF"],"ru":["Чтение PROGRESS.md","Проверка фонових задач с помощью tmux","Поддержка продолжения разговоров","Интеграция с CLI","Отчёт о статусе в формате BLUF"],"ar":["قراءة PROGRESS.md","فرصة المهام في الخلفية مع tmux","دعم استمرار المحادثات","التكامل مع CLI","تقرير الحالة بصيغة BLUF"]},"keywords":{"en":["how to use pickup skill","pickup skill setup guide","what is pickup in AI agents","pickup vs handoff","pickup alternative for conversation management","install pickup skill for AI agents","tmux task management with pickup","PROGRESS.md format for pickup","pickup skill for efficient conversation handoffs"],"zh":["pickup功能","新对话接续","PROGRESS.md","tmux实验","BLUF格式","AI工具","会话管理","对话继续"],"ja":["AIエージェント","pickup機能","新しい会話の継続","PROGRESS.md","tmux実験","BLUF形式","会話管理","対話の続き"],"ko":["AI 에이전트","pickup 기능","新的 대화 연속성","PROGRESS.md","tmux 실험","BLUF 형식","대화 관리","대화 계속"],"es":["pickup Agentes de IA","configuración de pickup","PROGRESS.md","tmux","BLUF","CLI","desarrollo de Agentes de IA","integración de pickup","optimización de diálogo"],"fr":["pickup Outils d''IA","configuration de pickup","PROGRESS.md","tmux","BLUF","CLI","développement d''Outils d''IA","intégration de pickup","optimisation de dialogue"],"de":["pickup KI-Agents","Einrichtung von pickup","PROGRESS.md","tmux","BLUF","CLI","Entwicklung von KI-Agents","Integration von pickup","Optimierung von Dialogen"],"pt":["Ferramentas de IA","pickup","PROGRESS.md","tmux","CLI","continuação de conversas","relatório de status","BLUF"],"ru":["ИИ Агенты","pickup","PROGRESS.md","tmux","CLI","продолжение разговоров","отчёт о статусе","BLUF"],"ar":["أدوات الإي الأجنت","pickup","PROGRESS.md","tmux","CLI","استمرار المحادثات","تقرير الحالة","BLUF"]}},"owner":"holEeast979","repo":"On-Device-LMM-Reasoning-Acceleration","repoPath":"holEeast979/On-Device-LMM-Reasoning-Acceleration","stars":1,"forks":0,"updatedAt":"2026-03-02T08:22:44Z","topics":[],"category":"community","skillMd":{"name":"pickup","description":"新对话开始时的接续流程。读取 PROGRESS.md 了解项目状态，快速进入工作状态。","bodyPreview":"# 新对话接续（/pickup）\n\n当用户在新对话开始时说\"接续\"、\"继续上次\"、\"读进度\"时执行此流程。\n\n> **最佳方式**：用户直接粘贴上次 `/handoff` 生成的交接 Prompt（更精准）。\n> **兜底方式**：没有 Prompt 时用 `/pickup`，Agent 自己读 PROGRESS.md 理解状态。\n\n## 步骤\n\n1. **读取 PROGRESS.md**\n   ```\n   读取 /root/scripts/PROGRESS.md 全文（重点关注\"当前状态\"和\"⬇️ 新对话 Agent 立即执行事项\"）\n   ```\n\n2. **检查后台任务**\n   ```bash\n   # 检查是否有 tmux 实验在跑\n   tmux list-sessions 2>/dev/null || echo \"no sessions\"\n   # 如果有，查看进度\n   tmux capture-pane -t eval -p | tail -20\n   ```\n\n3. **汇报当前状态**（BLUF 格式）\n   - 一句话总结当前状态\n   - 列出\"立即执行事项","body":"# 新对话接续（/pickup）\n\n当用户在新对话开始时说\"接续\"、\"继续上次\"、\"读进度\"时执行此流程。\n\n> **最佳方式**：用户直接粘贴上次 `/handoff` 生成的交接 Prompt（更精准）。\n> **兜底方式**：没有 Prompt 时用 `/pickup`，Agent 自己读 PROGRESS.md 理解状态。\n\n## 步骤\n\n1. **读取 PROGRESS.md**\n   ```\n   读取 /root/scripts/PROGRESS.md 全文（重点关注\"当前状态\"和\"⬇️ 新对话 Agent 立即执行事项\"）\n   ```\n\n2. **检查后台任务**\n   ```bash\n   # 检查是否有 tmux 实验在跑\n   tmux list-sessions 2>/dev/null || echo \"no sessions\"\n   # 如果有，查看进度\n   tmux capture-pane -t eval -p | tail -20\n   ```\n\n3. **汇报当前状态**（BLUF 格式）\n   - 一句话总结当前状态\n   - 列出\"立即执行事项\"\n   - 如果有后台实验，报告进度\n\n4. **确认优先级**\n   - 如果用户粘贴了交接 Prompt：按 Prompt 中的\"立即执行\"直接开始\n   - 如果用户只说了 /pickup：问用户\"按 PROGRESS.md 的计划继续，还是有新的优先级？\"\n\n5. **开始工作**\n   - 按\"⬇️ 新对话 Agent 立即执行事项\"的第一条开始执行\n   - 如果实验已完成，优先分析结果\n   - 如果实验未完成，做其他待办事项\n"},"lastSynced":"2026-03-06T13:09:45.116Z","agentAnalysis":{"suitability":{"en":"Essential for Development and Task-Oriented Agents requiring persistent state management across conversation breaks.","zh":"对于需要跨对话中断进行持久状态管理的开发和面向任务的AI Agent来说，这是必不可少的技能。","ja":"会話の中断を跨いで持続的な状態管理を必要とする開発およびタスク指向のAIエージェントにとって、本スキルは必須です。","ko":"대화 중단에 걸친 지속적인 상태 관리가 필요한 개발 및 작업 지향형 AI 에이전트에게 필수적인 스킬입니다.","es":"Esencial para agentes de desarrollo y orientados a tareas que requieren gestión de estado persistente entre interrupciones de conversación.","fr":"Essentiel pour les agents de développement et orientés tâches nécessitant une gestion d''état persistante entre les interruptions de conversation.","de":"Essenziell für Entwicklungs- und aufgabenorientierte Agents, die eine persistente Zustandsverwaltung über Konversationsunterbrechungen hinweg erfordern.","pt":"Essencial para Agentes de Desenvolvimento e Orientados a Tarefas que requerem gerenciamento de estado persistente entre interrupções de conversa.","ru":"Необходимо для агентов разработки и целевых агентов, требующих управления постоянным состоянием между перерывами в беседе.","ar":"ضروري لوكلاء التطوير والوكلاء الموجهة للمهام التي تتطلب إدارة حالة مستمرة عبر انقطاعات المحادثة."},"recommendation":{"en":"Enables seamless continuation of complex workflows by reading the PROGRESS.md file to understand the current state and immediate next actions. It checks for active tmux sessions to monitor background tasks and report progress using BLUF (Bottom Line Up Front) formatting for clarity.","zh":"通过读取 PROGRESS.md 文件来理解当前状态和紧接的后续操作，从而实现复杂工作流的无缝继续。它检查活跃的 tmux 会话以监控后台任务，并使用 BLUF (Bottom Line Up Front) 格式化清晰报告进度。","ja":"PROGRESS.md ファイルを読み取って現在の状態と次の即時アクションを理解することで、複雑なワークフローのシームレスな継続を可能にします。アクティブな tmux セッションをチェックしてバックグラウンドタスクを監視し、明確さのために BLUF (Bottom Line Up Front) フォーマットを使用して進捗状況を報告します。","ko":"현재 상태와 바로 다음 작업을 이해하기 위해 PROGRESS.md 파일을 읽어서 복잡한 워크플로우의 원활한 연속을 가능하게 합니다. 백그라운드 작업을 모니터링하기 위해 활성 tmux 세션을 확인하고, 명확성을 위해 BLUF (Bottom Line Up Front) 형식을 사용하여 진행 상황을 보고합니다.","es":"Permite la continuación fluida de flujos de trabajo complejos mediante la lectura del archivo PROGRESS.md para comprender el estado actual y las siguientes acciones inmediatas. Comprueba las sesiones activas de tmux para supervisar tareas en segundo plano e informar del progreso utilizando el formato BLUF (Bottom Line Up Front) para mayor claridad.","fr":"Permet la poursuite transparente de flux de travail complexes en lisant le fichier PROGRESS.md pour comprendre l''état actuel et les prochaines actions immédiates. Il vérifie les sessions tmux actives pour surveiller les tâches en arrière-plan et rapporter la progression en utilisant le formatage BLUF (Bottom Line Up Front) pour plus de clarté.","de":"Ermöglicht die nahtlose Fortsetzung komplexer Workflows, indem die PROGRESS.md-Datei gelesen wird, um den aktuellen Zustand und die unmittelbaren nächsten Aktionen zu verstehen. Es prüft aktive tmux-Sitzungen, um Hintergrundaufgaben zu überwachen und den Fortschritt mit BLUF (Bottom Line Up Front)-Formatierung zur Klarheit zu melden.","pt":"Permite a continuação perfeita de fluxos de trabalho complexos ao ler o arquivo PROGRESS.md para entender o estado atual e as próximas ações imediatas. Ele verifica sessões tmux ativas para monitorar tarefas em segundo plano e relatar o progresso usando formatação BLUF (Bottom Line Up Front) para clareza.","ru":"Обеспечивает беспрерывное продолжение сложных рабочих процессов путем чтения файла PROGRESS.md для понимания текущего состояния и непосредственных следующих действий. Он проверяет активные сессии tmux для мониторинга фоновых задач и отчетности о прогрессе с использованием форматирования BLUF (Bottom Line Up Front) для ясности.","ar":"يتيح الاستمرار السلس لسير العمل المعقد من خلال قراءة ملف PROGRESS.md لفهم الحالة الحالية والإجراءات التالية المباشرة. يقوم بالتحقق من جلسات tmux النشطة لمراقبة المهام في الخلفية والإبلاغ عن التقدم باستخدام تنسيق BLUF (خلاصة الأمر من البداية) من أجل الوضوح."},"useCases":{"en":["Resuming interrupted development workflows","Monitoring long-running tmux-based experiments","Parsing PROGRESS.md for immediate action items"],"zh":["恢复被中断的开发工作流程","监控基于 tmux 的长时间运行的实验","解析 PROGRESS.md 以获取立即执行的任务项"],"ja":["中断された開発ワークフローの再開","tmuxベースの長時間実行実験の監視","即時アクション項目のために PROGRESS.md を解析"],"ko":["중단된 개발 워크플로우 재개","tmux 기반 장기 실행 실험 모니터링","즉각적인 실행 항목을 위해 PROGRESS.md 파싱"],"es":["Reanudar flujos de trabajo de desarrollo interrumpidos","Supervisar experimentos de larga duración basados en tmux","Analizar PROGRESS.md para identificar elementos de acción inmediatos"],"fr":["Reprendre des flux de travail de développement interrompus","Surveiller des expériences de longue durée basées sur tmux","Analyser PROGRESS.md pour les éléments d''action immédiats"],"de":["Fortsetzen unterbrochener Entwicklungs-Workflows","Überwachen langlaufender Experimente auf tmux-Basis","Parsen von PROGRESS.md für unmittelbare Aktionspunkte"],"pt":["Retomada de fluxos de trabalho de desenvolvimento interrompidos","Monitoramento de experimentos de longa duração baseados em tmux","Análise do PROGRESS.md para itens de ação imediatos"],"ru":["Возобновление прерванных рабочих процессов разработки","Мониторинг долгосрочных экспериментов на основе tmux","Анализ файла PROGRESS.md для определения немедленных пунктов действий"],"ar":["استئناف سير عمل التطوير المتقطع","مراقبة التجارب طويلة المدى القائمة على tmux","تحليل PROGRESS.md لعناصر العمل الفورية"]},"limitations":{"en":["Requires PROGRESS.md file in /root/scripts/ directory","Depends on tmux for session monitoring","Relies on specific handoff prompt structure for optimal performance"],"zh":["需要在 /root/scripts/ 目录中存在 PROGRESS.md 文件","依赖 tmux 进行会话监控","依赖特定的交接提示结构以获得最佳性能"],"ja":["/root/scripts/ ディレクトリに PROGRESS.md ファイルが必要","セッション監視に tmux への依存","最適なパフォーマンスのために特定のハンドオフプロンプト構造に依存"],"ko":["/root/scripts/ 디렉토리에 PROGRESS.md 파일 필요","세션 모니터링을 위해 tmux에 의존","최적의 성능을 위해 특정 핸드오프 프롬프트 구조에 의존"],"es":["Requiere un archivo PROGRESS.md en el directorio /root/scripts/","Depende de tmux para la supervisión de sesiones","Depende de una estructura de prompt de traspaso específica para un rendimiento óptimo"],"fr":["Nécessite un fichier PROGRESS.md dans le répertoire /root/scripts/","Dépend de tmux pour la surveillance des sessions","Repose sur une structure d''invite de transfert spécifique pour des performances optimales"],"de":["Erfordert eine PROGRESS.md-Datei im Verzeichnis /root/scripts/","Ist für die Sitzungsüberwachung auf tmux angewiesen","Verlässt sich für optimale Leistung auf eine spezifische Handoff-Prompt-Struktur"],"pt":["Requer o arquivo PROGRESS.md no diretório /root/scripts/","Depende do tmux para monitoramento de sessão","Depende de uma estrutura de prompt de handoff específica para desempenho ideal"],"ru":["Требует наличия файла PROGRESS.md в каталоге /root/scripts/","Зависит от tmux для мониторинга сессий","Опирается на определенную структуру подсказки передачи для оптимальной производительности"],"ar":["يتطلب وجود ملف PROGRESS.md في دليل /root/scripts/","يعتمد على tmux لمراقبة الجلسة","يعتمد على هيكل محدد لموجه التسليم لأداء مثالي"]},"version":4},"contentHash":"7633fb1ac669d49a58bc4cdbb78682c2e4c494f1b2eef13639d8c23680865b04","qualityScore":30}');
