INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('holEeast979/On-Device-LMM-Reasoning-Acceleration/pickup', 'pickup', 'holEeast979', 'On-Device-LMM-Reasoning-Acceleration', 'community', 'pickup holEeast979 On-Device-LMM-Reasoning-Acceleration community The pickup skill enables AI agents to continue conversations from where they left off, benefiting developers who need to manage complex dialogue flows. It reads PROGRESS.md and checks tmux sessions for efficient task handling. pickup功能允许用户在新对话开始时继续上次的进度，通过读取PROGRESS.md和检查后台任务 pickup機能は、ユーザーが新しい会話を開始したときに前の会話の進度を継続できるようにします pickup 기능은 새로운 대화 시작 시 이전 대화의 진행状況을 계속할 수 있도록 합니다 El skill pickup permite a los Agentes de IA leer el archivo PROGRESS.md y entender el estado actual de la conversación Le skill pickup permet aux Outils d''IA de lire le fichier PROGRESS.md et de comprendre l''état actuel de la conversation Das pickup-Skill ermöglicht es KI-Agents, die Datei PROGRESS.md zu lesen und den aktuellen Zustand des Dialogs zu verstehen O pickup é uma habilidade que permite a continuação de conversas, lendo PROGRESS.md e verificando tarefas em segundo plano Pickup - это навык, который позволяет продолжать разговоры, читая PROGRESS.md и проверяя фоновіх задач Pickup هو مهارة تسمح بمواصلة المحادثات، وقراءة PROGRESS.md وفرصة المهام في الخلفية how to use pickup skill pickup skill setup guide what is pickup in AI agents pickup vs handoff pickup alternative for conversation management install pickup skill for AI agents tmux task management with pickup PROGRESS.md format for pickup pickup skill for efficient conversation handoffs pickup功能 新对话接续 PROGRESS.md tmux实验 BLUF格式 AI工具 会话管理 对话继续 Reads PROGRESS.md to understand current conversation state Utilizes tmux to check and manage background tasks Supports BLUF format for concise status reporting Executes tasks based on ''立即执行事项'' in PROGRESS.md Compatible with /handoff prompts for precise conversation handoffs Automatically captures and reports on task progress using tmux capture-pane pickup is a skill that allows AI agents to resume conversations by reading PROGRESS.md and utilizing tmux for task management');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jllopis/kairos/changelog-gen', 'community', 'jllopis', 'kairos', 'jllopis/kairos', 'changelog-gen', 1, 1, 30, '2026-02-28T16:51:54Z', '2026-03-06T13:12:14.174Z', '82a4a9fccb848558de4bf37899a65ee94ecc859efebfa34f2dd63798efb553e4', '{"id":"jllopis/kairos/changelog-gen","name":"changelog-gen","description":{"en":"The changelog-gen skill generates user-friendly changelogs from git commits, benefiting developers and customers alike by providing clear release notes and update summaries.","zh":"Changelog-gen是一种自动化变更日志生成工具，支持Git提交转换为易于使用的变更日志","ja":"Changelog-genは、Gitコミットを容易に使用できる変更ログに自動変換するAIエージェントツールです","ko":"Changelog-gen은 Git 커밋을 쉽게 사용할 수 있는 변경 로그로 자동 변환하는 AI 에이전트 도구입니다","es":"changelog-gen es un generador de notas de versión que transforma commits técnicos de git en changelogs elegantes y fáciles de usar","fr":"changelog-gen est un générateur de notes de version qui transforme les commits techniques de git en des changelogs élégants et faciles à utiliser","de":"changelog-gen ist ein Versionshinweis-Generator, der technische Git-Commits in elegante und benutzerfreundliche Changelogs umwandelt","pt":"O Changelog-Gen é uma skill de agente IA que gera changelogs a partir de commits Git, tornando-os fáceis de entender e usar","ru":"Changelog-Gen - это навык ИИ Агента, который генерирует чейнджлоги из коммитов Git, делая их легко понимаемыми и используемыми","ar":"Changelog-Gen هو مهارة وكيل الإيمان العقلانية التي تولد سجلات التغيير من التعديلات في كود المصدر، مما يسهل فهمها واستخدامها"},"seo":{"title":{"en":"changelog-gen: Automated Changelog Generation for AI Agen...","zh":"Changelog-gen_SETUP_GUIDE：自动化变更日志生成","ja":"Changelog-gen_BEST_PRACTICES：AIエージェントを使用した自動化変更ログ生成","ko":"Changelog-gen_가이드: 자동화된 변경 로그 생성","es":"Guía de configuración de changelog-gen para Agentes IA","fr":"Guide de mise en place de changelog-gen pour Outils IA","de":"Einrichtungsleitfaden für changelog-gen in KI-Agents","pt":"Guia de Configuração do Changelog-Gen: Ferramenta de IA p...","ru":"Настройка Changelog-Gen: Инструмент ИИ Агентов для Разраб...","ar":"دليل إعداد Changelog-Gen: أداة الإيمان العقلانية للمطورين"},"description":{"en":"Transform git commits into elegant changelogs with changelog-gen. Discover how to simplify release notes and improve customer communication. Get started now!","zh":"使用Changelog-gen自动化变更日志生成，提高开发效率和代码质量","ja":"AIエージェントを使用したChangelog-genで自動化変更ログ生成を実現し、開発効率とコード品質を向上させる","ko":"Changelog-gen을 사용하여 자동화된 변경 로그 생성을实现하고 개발 효율성과 코드 품질을 높이세요","es":"Descubre cómo configurar changelog-gen para generar notas de versión técnicas y fáciles de usar para tus clientes y usuarios","fr":"Découvrez comment configurer changelog-gen pour générer des notes de version techniques et faciles à utiliser pour vos clients et utilisateurs","de":"Erfahren Sie, wie Sie changelog-gen konfigurieren, um technische Versionshinweise zu erstellen, die für Ihre Kunden und Benutzer einfach zu verstehen sind","pt":"Aprenda a usar o Changelog-Gen, uma skill de agente IA que transforma commits em changelogs elegantes e fáceis de usar","ru":"Узнайте, как использовать Changelog-Gen, навык ИИ Агента, который преобразует коммиты в элегантные и удобные чейнджлоги","ar":"تعرف على كيفية استخدام Changelog-Gen، مهارة وكيل الإيمان العقلانية التي تحول التعديلات في كود المصدر إلى سجلات تغييرات أنيقة وسهلة الاستخدام"},"definition":{"en":"changelog-gen is a Go-native framework agent skill focused on interoperability and observability, generating changelogs from git commits for easier release management.","zh":"Changelog-gen是一种自动化工具，用于生成易于使用的变更日志","ja":"Changelog-genは、変更ログを自動生成するAIエージェントの一種です","ko":"Changelog-gen은 변경 로그를 자동 생성하는 AI 에이전트의 일종입니다","es":"changelog-gen es una habilidad de agente IA que genera notas de versión técnicas a partir de commits de git","fr":"changelog-gen est une compétence d''outil IA qui génère des notes de version techniques à partir de commits de git","de":"changelog-gen ist eine Fähigkeit von KI-Agents, die technische Versionshinweise aus Git-Commits generiert","pt":"O que é Changelog-Gen? Uma ferramenta de IA que transforma commits em changelogs elegantes","ru":"Что такое Changelog-Gen? Инструмент ИИ, который преобразует коммиты в элегантные чейнджлоги","ar":"ما هو Changelog-Gen؟ أداة الإيمان العقلانية التي تحول التعديلات في كود المصدر إلى سجلات تغييرات أنيقة"},"features":{"en":["Transforms git commits into elegant and easy-to-use changelogs","Supports preparation of release notes for new software releases","Enables creation of weekly or monthly product update summaries","Facilitates documentation of changes for customers","Generates content for app store listings, such as App Store and Play Store"],"zh":["支持Git提交转换为变更日志","自动化变更日志生成","易于使用的变更日志格式","支持多种输出格式","集成OpenTelemetry观测能力"],"ja":["Gitコミットを変更ログに自動変換","自動化変更ログ生成","容易に使用できる変更ログフォーマット","複数の出力形式をサポート","OpenTelemetry観測機能を統合"],"ko":["Git 커밋을 변경 로그로 자동 변환","자동화된 변경 로그 생성","쉽게 사용할 수 있는 변경 로그 형식","여러 가지 출력 형식을 지원","OpenTelemetry 관측 기능을 통합"],"es":["Transformación de commits técnicos de git en changelogs elegantes","Generación de notas de versión para nuevas releases de software","Creación de resúmenes semanales o mensuales de actualizaciones de producto","Documentación de cambios para los clientes","Escribir novedades para las tiendas de aplicaciones"],"fr":["Transformation de commits techniques de git en des changelogs élégants","Génération de notes de version pour les nouvelles versions de logiciels","Création de résumés hebdomadaires ou mensuels de mises à jour de produits","Documentation des modifications pour les clients","Écriture de nouveautés pour les magasins d''applications"],"de":["Umwandlung von technischen Git-Commits in elegante Changelogs","Erstellung von Versionshinweisen für neue Software-Versionen","Erstellung von wöchentlichen oder monatlichen Zusammenfassungen von Produktaktualisierungen","Dokumentation von Änderungen für die Kunden","Erstellung von Neuigkeiten für die App-Stores"],"pt":["Geração de changelogs a partir de commits Git","Suporte a MCP, A2A/ACP e AgentSkills","Observabilidade com OpenTelemetry","Ejecução multi-agente distribuida","Criação de resúmenes semanales ou mensais de atualizações de produto","Geração de notificações de atualização"],"ru":["Генерация чейнджлогов из коммитов Git","Поддержка MCP, A2A/ACP и AgentSkills","Наблюдаемость с помощью OpenTelemetry","Многоагентная распределенная выполнение","Создание еженедельных или ежемесячных сводок обновлений продукта","Генерация уведомлений об обновлении"],"ar":["توليد سجلات التغيير من التعديلات في كود المصدر","دعم MCP، A2A/ACP و AgentSkills","مراقبة باستخدام OpenTelemetry","تنفيذ متعدد الوكلاء الموزع","إنشاء ملخصات أسبوعية أو شهرية لتحديثات المنتج","توليد إشعارات التحديث"]},"keywords":{"en":["how to use changelog-gen","changelog-gen alternative","changelog-gen setup guide","what is changelog-gen","changelog-gen vs conventional changelog","automated changelog generation","changelog-gen install","git commit to changelog"],"zh":["Changelog-gen","自动化变更日志生成","Git提交转换","AIエージェント","OpenTelemetry","变更日志工具","代码质量提高","开发效率提高"],"ja":["Changelog-gen","自動化変更ログ生成","Gitコミット変換","AIエージェント","OpenTelemetry","変更ログツール","コード品質向上","開発効率向上"],"ko":["Changelog-gen","자동화된 변경 로그 생성","Git 커밋 변환","AI 에이전트","OpenTelemetry","변경 로그 도구","코드 품질 향상","개발 효율성 향상"],"es":["changelog-gen","agentes IA","generador de notas de versión","commits de git","documentación de cambios","novedades para tiendas de aplicaciones","guía de configuración de changelog-gen","mejores prácticas para changelog-gen","herramientas de agente IA"],"fr":["changelog-gen","outils IA","générateur de notes de version","commits de git","documentation des modifications","nouveautés pour les magasins d''applications","guide de mise en place de changelog-gen","meilleures pratiques pour changelog-gen","outils d''agent IA"],"de":["changelog-gen","KI-Agents","Versionshinweis-Generator","Git-Commits","Dokumentation von Änderungen","Neuigkeiten für App-Stores","Einrichtungsleitfaden für changelog-gen","Best Practices für changelog-gen","KI-Tools"],"pt":["Changelog-Gen","ferramenta de IA","desenvolvedores","commits Git","changelogs","MCP","A2A/ACP","AgentSkills","OpenTelemetry","multi-agente distribuida"],"ru":["Changelog-Gen","инструмент ИИ","разработчики","коммиты Git","чейнджлоги","MCP","A2A/ACP","AgentSkills","OpenTelemetry","многоагентная распределенная"],"ar":["Changelog-Gen","أداة الإيمان العقلانية","مطورين","التعديلات في كود المصدر","سجلات التغيير","MCP","A2A/ACP","AgentSkills","OpenTelemetry","تنفيذ متعدد الوكلاء الموزع"]}},"owner":"jllopis","repo":"kairos","repoPath":"jllopis/kairos","stars":1,"forks":1,"updatedAt":"2026-02-28T16:51:54Z","topics":[],"category":"community","skillMd":{"name":"changelog-gen","description":"Crea automáticamente changelogs orientados al usuario a partir de commits de git. Analiza el historial, categoriza los cambios y transforma commits técnicos en notas de release claras y amigables para el cliente.","bodyPreview":"# Generador de Changelog\n\nEsta skill transforma los commits técnicos de git en changelogs elegantes y fáciles de usar que tus clientes y usuarios realmente entenderán y apreciarán.\n\n## Cuándo usar esta Skill\n\n- Preparar las notas para una nueva release de software.\n- Crear resúmenes semanales o mensuales de actualizaciones de producto.\n- Documentar cambios para los clientes.\n- Escribir las novedades para las tiendas de aplicaciones (App Store, Play Store).\n- Generar notificaciones de actualizaci","body":"# Generador de Changelog\n\nEsta skill transforma los commits técnicos de git en changelogs elegantes y fáciles de usar que tus clientes y usuarios realmente entenderán y apreciarán.\n\n## Cuándo usar esta Skill\n\n- Preparar las notas para una nueva release de software.\n- Crear resúmenes semanales o mensuales de actualizaciones de producto.\n- Documentar cambios para los clientes.\n- Escribir las novedades para las tiendas de aplicaciones (App Store, Play Store).\n- Generar notificaciones de actualización.\n- Crear documentación interna sobre los lanzamientos.\n- Mantener una página pública de changelog o actualizaciones de producto.\n\n## Qué Hace esta Skill\n\n1.  **Escanea el Historial de Git**: Analiza los commits de un período de tiempo específico o entre versiones.\n2.  **Categoriza los Cambios**: Agrupa los commits en categorías lógicas (funcionalidades, mejoras, correcciones de errores, cambios disruptivos, seguridad).\n3.  **Traduce de Técnico a Amigable**: Convierte el lenguaje de los commits de desarrollador a uno orientado al cliente.\n4.  **Formatea Profesionalmente**: Crea entradas de changelog limpias y estructuradas.\n5.  **Filtra el Ruido**: Excluye commits internos (refactorización, tests, etc.).\n6.  **Sigue las Mejores Prácticas**: Aplica directrices de changelog y la voz de tu marca.\n\n## Cómo Usar\n\n### Uso Básico\n\nDesde el repositorio de tu proyecto:\n\n```\nCrea un changelog con los commits desde la última release\n```\n\n```\nGenera un changelog para todos los commits de la última semana\n```\n\n```\nCrea las notas de la release para la versión 2.5.0\n```\n\n### Con Rango de Fechas Específico\n\n```\nCrea un changelog para los commits entre el 1 y el 15 de marzo\n```\n\n### Con Guías de Estilo Personalizadas\n\n```\nCrea un changelog para los commits desde la v2.4.0, usando mis guías de estilo definidas en ESTILO_XXX.md.\n```\n\nSi el cliente no indica un estilo explícitamente, usa [ESTILO_CHANGELOG](references/ESTILO_CHANGELOG.md) como estilo predeterminado.\n\n## Ejemplo\n\n**Usuario**: \"genera el changelog de esta semana\"\n\n**Salida**:\n\n```markdown\n# Actualizaciones - Semana del 2026-01-07 al 2026-01-14\n\n  ## Nuevas funcionalidades\n\n  - Soporte A2A end-to-end: bindings HTTP+JSON y JSON-RPC, scaffolding gRPC, almacenamiento de tareas, suscripciones y push config para interoperar entre agentes.\n  - Discovery avanzado: nuevos providers, registro y soporte de AgentCard para descubrimiento de agentes y reintentos.\n  - Gobernanza configurable: loader y motor de politicas con integracion en demos y ejemplo de politica deny.\n  - Planner mas rico: condiciones avanzadas y auditoria; mejora de hooks de auditoria.\n\n  ## Mejoras\n\n  - Experiencia de demo y UI: streaming web, estilos finales de UI, defaults de discovery y guias de ejecucion mas claras.\n  - CLI y operaciones: comandos avanzados, overrides de config via CLI y barrido runtime.\n  - Observabilidad: propagacion de trace context en A2A gRPC.\n\n  ## Correcciones\n\n  - Runner y scripts: arreglos en argumentos y expansion de config del demo runner; flag verbose consistente.\n  - A2A y tareas: correcciones en manejo de task id y validacion de recursos/operaciones terminales.\n\n  ## Documentacion\n\n  - Arquitectura y roadmap: actualizaciones de estado A2A/planner y avances de roadmap.e\n  - Demos y ejemplos: referencias de ejecucion de agentes y ajustes en ejemplos MCP.\n\n```\n\n## Consejos\n\n- Ejecuta la skill desde la raíz de tu repositorio git.\n- Especifica rangos de fechas para changelogs más acotados.\n- Usa tu propio fichero `ESTILO_CHANGELOG.md` para un formato consistente. Si no se especifica, se usa [ESTILO_CHANGELOG.md](references/ESTILO_CHANGELOG.md) por defecto.\n- Revisa y ajusta el changelog generado antes de publicarlo.\n- Guarda la salida directamente en tu fichero `CHANGELOG.md`.\n\n## Casos de Uso Relacionados\n\n- Crear las notas de una release en GitHub.\n- Escribir las descripciones de actualización para tiendas de aplicaciones.\n- Generar correos electrónicos de actualización para usuarios.\n- Crear publicaciones para anunciar novedades en redes sociales.\n"},"lastSynced":"2026-03-06T13:12:14.174Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing automated changelog generation from git commits.","zh":"非常适合需要从 git 提交记录自动生成变更日志的开发者代理。","ja":"git コミットから自動的に変更ログを生成する必要がある Developer Agents に最適です。","ko":"git 커밋에서 자동으로 변경 로그를 생성해야 하는 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan generación automática de registros de cambios desde confirmaciones de git.","fr":"Parfait pour les Agents de Développeur ayant besoin de génération automatisée de journaux des modifications à partir de validations git.","de":"Perfekt für Entwickleragenten, die eine automatisierte Generierung von Änderungsprotokollen aus git-Commits benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de geração automatizada de changelog a partir de commits do git.","ru":"Идеально подходит для агентов разработчиков, которым требуется автоматизированная генерация changelog из коммитов git.","ar":"مثالي لعميل التطوير الذي يحتاج إلى генера генерация تلقائية لسجل التغييرات من الالتزامات git."},"recommendation":{"en":"Empowers agents to transform technical git commits into user-friendly changelogs, providing clear release notes and update summaries using git protocols and generating notifications for App Store and Play Store updates.","zh":"赋予代理将技术 git 提交转化为用户友好的变更日志的能力，提供清晰的发布说明和更新摘要，使用 git 协议，并为 App Store 和 Play Store 更新生成通知。","ja":"エージェントが技術的な git コミットをユーザー フレンドリな変更ログに変換する能力を提供し、明確なリリース ノートと更新のサマリーを提供し、git プロトコルを使用し、App Store と Play Store の更新について通知を生成します。","ko":"에이전트가 기술적인 git 커밋을 사용자 친화적인 변경 로그로 변환할 수 있는 능력을 부여하여, 명확한 릴리스 노트와 업데이트 요약을 제공하고, git 프로토콜을 사용하며, App Store 및 Play Store 업데이트에 대한 알림을 생성합니다.","es":"Habilita a los agentes a transformar confirmaciones técnicas de git en registros de cambios legibles para el usuario, proporcionando notas de lanzamiento y resúmenes de actualizaciones claras utilizando protocolos git y generando notificaciones para actualizaciones de App Store y Play Store.","fr":"Permet aux agents de transformer les validations techniques git en journaux des modifications conviviaux pour l''utilisateur, fournissant des notes de publication et des résumés de mises à jour clairs en utilisant les protocoles git et en générant des notifications pour les mises à jour de l''App Store et du Play Store.","de":"Ermöglicht es Agenten, technische git-Commits in benutzerfreundliche Änderungsprotokolle umzuwandeln, wodurch klare Versionshinweise und Update-Zusammenfassungen unter Verwendung von git-Protokollen bereitgestellt werden und Benachrichtigungen für App-Store- und Play-Store-Updates generiert werden.","pt":"Habilita os agentes a transformar commits técnicos do git em changelogs amigáveis ao usuário, fornecendo notas de lançamento claras e resumos de atualizações usando protocolos git e gerando notificações para atualizações da App Store e Play Store.","ru":"Наделяет агентов возможностью преобразовывать технические коммиты git в понятные пользователю changelogs, обеспечивая ясные заметки о выпуске и сводки обновлений с использованием протоколов git и генерируя уведомления для обновлений App Store и Play Store.","ar":"تمكين العميل من تحويل الالتزامات الفنية git إلى سجلات تغييرات صديقة للمستخدم، وتوفير ملاحظات إصدار واضحة وخلاصات تحديث باستخدام بروتوكولات git وتوليد الإشعارات لتحديثات متجر التطبيقات ومتجر جوجل بلاي."},"useCases":{"en":["Generating release notes for software updates","Creating weekly or monthly product update summaries","Documenting changes for customer notifications"],"zh":["为软件更新生成发布说明","创建每周或每月产品更新摘要","为客户通知记录更改"],"ja":["ソフトウェア更新のリリース ノートを生成する","週次または月次の製品更新サマリーを作成する","顧客通知のために変更を文書化する"],"ko":["소프트웨어 업데이트에 대한 릴리스 노트 생성","주간 또는 월간 제품 업데이트 요약 생성","고객 알림을 위한 변경 기록"],"es":["Generar notas de lanzamiento para actualizaciones de software","Crear resúmenes de actualización de producto semanales o mensuales","Documentar cambios para notificaciones de clientes"],"fr":["Générer des notes de publication pour les mises à jour logicielles","Créer des résumés de mise à jour de produit hebdomadaires ou mensuels","Documenter les modifications pour les notifications de clients"],"de":["Generieren von Versionshinweisen für Software-Updates","Erstellen von wöchentlichen oder monatlichen Produkt-Update-Zusammenfassungen","Dokumentieren von Änderungen für Kundenbenachrichtigungen"],"pt":["Geração de notas de lançamento para atualizações de software","Criação de resumos de atualizações de produto semanais ou mensais","Documentação de alterações para notificações ao cliente"],"ru":["Генерация заметок о выпуске для обновлений программного обеспечения","Создание сводок обновлений продукта еженедельно или ежемесячно","Документирование изменений для уведомлений клиентов"],"ar":["توليد ملاحظات الإصدار لتحديثات البرامج","إنشاء ملخصات تحديث المنتج أسبوعيًا أو شهريًا","توثيق التغييرات لإشعارات العملاء"]},"limitations":{"en":["Requires access to git commit history","Limited to generating changelogs from git commits"],"zh":["需要访问 git 提交历史记录","仅限从 git 提交生成变更日志"],"ja":["git コミット履歴へのアクセスが必要","git コミットからの変更ログの生成のみ"],"ko":["git 커밋 기록에 대한 액세스가 필요","git 커밋에서 변경 로그를 생성하는 것만 가능"],"es":["Requiere acceso al historial de confirmaciones de git","Limitado a la generación de registros de cambios desde confirmaciones de git"],"fr":["Requiert l''accès à l''historique des validations git","Limité à la génération de journaux des modifications à partir de validations git"],"de":["Erfordert Zugriff auf die git-Commit-Historie","Begrenzt auf die Generierung von Änderungsprotokollen aus git-Commits"],"pt":["Requer acesso ao histórico de commits do git","Limitado à geração de changelogs a partir de commits do git"],"ru":["Требует доступа к истории коммитов git","Ограничен генерацией changelogs из коммитов git"],"ar":["يتطلب الوصول إلى سجل الالتزامات git","محدود بالتوليد سجلات التغييرات من الالتزامات git"]},"version":4},"contentHash":"82a4a9fccb848558de4bf37899a65ee94ecc859efebfa34f2dd63798efb553e4","qualityScore":30}');
