INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shoji-sws/hatena-md-skill/hatena-blog-markdown-extractor', 'hatena-blog-markdown-extractor', 'shoji-sws', 'hatena-md-skill', 'community', 'hatena-blog-markdown-extractor shoji-sws hatena-md-skill community The hatena-blog-markdown-extractor skill extracts Hatena Blog article content to Markdown format, benefiting developers and bloggers. It automatically removes unnecessary elements and converts HTML to Markdown. Hatena Blog Markdown Extractor 是一个用于从はてなブログ中提取 Markdown 格式内容的工具，支持 HTML 到 Markdown 转换和自定义输出目录 Hatena Blog Markdown Extractor ははてなブログから Markdown 形式のコンテンツを抽出するツールで、HTML から Markdown への変換やカスタム出力ディレクトリをサポート Hatena Blog Markdown Extractor는 はてなブログ에서 마크다운 형식의 콘텐츠를 추출하는 도구로, HTML에서 마크다운으로의 변환 및 사용자 지정 출력 디렉토리를 지원 El skill hatena-blog-markdown-extractor extrae contenido de Hatena Blog en formato Markdown. Convierte HTML a Markdown y elimina elementos innecesarios Le skill hatena-blog-markdown-extractor extrait du contenu Hatena Blog au format Markdown. Il convertit HTML en Markdown et supprime les éléments inutiles Das Skill hatena-blog-markdown-extractor extrahiert Inhalt von Hatena Blog im Markdown-Format. Es wandelt HTML in Markdown um und entfernt unnötige Elemente O Extrator de Markdown do Hatena Blog é uma ferramenta que converte conteúdo de URLs do Hatena Blog em Markdown ИИ Агент для извлечения контента из Hatena Blog в формате Markdown مستخرج ماركداون من مدونة هاتينا هو أداة لتحويل المحتوى من رابط مدونة هاتينا إلى ماركداون hatena-blog-markdown-extractor setup guide how to use hatena-blog-markdown-extractor hatena-blog-markdown-extractor alternative hatena-blog-markdown-extractor vs markdown converter hatena-blog-markdown-extractor install hatena blog to markdown conversion Hatena Blog Markdown Extractor AI 工具 はてなブログ Markdown 格式 HTML 到 Markdown 转换 自定义输出目录 CLI 工具 Extracts article content from Hatena Blog URLs Converts HTML to Markdown format Preserves image URLs as full paths Automatically removes sidebars, headers, footers, and ads Generates Markdown files with front matter hatena-blog-markdown-extractor is a skill that extracts Hatena Blog article content to Markdown format, preserving image URLs and removing unwanted elements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zskulcsar/code-stats/go-clean-architecture', 'community', 'zskulcsar', 'code-stats', 'zskulcsar/code-stats', 'go-clean-architecture', 0, 0, 30, '2026-03-06T12:59:22.269Z', '2026-03-06T15:04:27.464Z', 'f7a6a0920578a56d3d493542a24c48836b99fed6736c20db0303aa9eeafde2d5', '{"id":"zskulcsar/code-stats/go-clean-architecture","name":"go-clean-architecture","description":{"en":"The go-clean-architecture skill enables statistical analysis of source code in Go and Python, benefiting developers who need to separate concerns through distinct layers. It emphasizes domain logic and validation","zh":"Go Clean Architecture是一种强调分层和依赖的软件架构，通过Domain Layer、Repository interfaces等实现业务逻辑的分离","ja":"Go Clean Architectureは、Domain LayerやRepository interfacesを通じてビジネスロジックを分離するソフトウェアアーキテクチャです","ko":"Go Clean Architecture는 Domain Layer와 Repository interfaces를 통해 비즈니스 로직을 분리하는 소프트웨어 아키텍처입니다","es":"La arquitectura limpia en Go separa las preocupaciones en capas distintas con dependencias hacia el dominio","fr":"L''architecture propre en Go sépare les préoccupations en couches distinctes avec des dépendances vers le domaine","de":"Die Clean Architecture in Go trennt die Bedenken in unterschiedliche Schichten mit Abhängigkeiten zum Domänen-Modell","pt":"A arquitetura limpa em Go é uma abordagem que separa as preocupações em camadas distintas, com dependências apontando para dentro em direção ao domínio.","ru":"Чистая архитектура в Go - это подход, который разделяет проблемы на отдельные слои, с зависимостями, указывающими внутрь к домену.","ar":"هندسة گو النظيفة هي نهج يفصل المشاكل إلى طبقات منفصلة، مع зависимости تشير داخلًا نحو المجال."},"seo":{"title":{"en":"go-clean-architecture: Setup Guide for AI Agents | AI Age...","zh":"Go Clean Architecture_SETUP GUIDE","ja":"Go Clean Architectureベストプラクティス","ko":"Go Clean Architecture 구현 가이드","es":"