INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Shin0205go/auto-mineflayer-mcp-server/enchanting', 'enchanting', 'Shin0205go', 'auto-mineflayer-mcp-server', 'community', 'enchanting Shin0205go auto-mineflayer-mcp-server community The enchanting skill enables AI agents to create and configure enchanting tables, leveraging materials like diamonds, obsidian, and books to enhance equipment. This skill benefits AI agents seeking to optimize their Minecraft gameplay. Minecraft Enchanting Minecraft Enchanting Minecraft Enchanting El sistema de enchanting en Minecraft permite mejorar los objetos del juego. Nuestra guía cubre la creación de la mesa de enchanting y la configuración de los estantes para alcanzar el nivel máximo de enchanting. Le système d''enchanting dans Minecraft permet d''améliorer les objets du jeu. Notre guide couvre la création de la table d''enchanting et la configuration des étagères pour atteindre le niveau maximum d''enchanting. Das Enchanting-System in Minecraft ermöglicht die Verbesserung der Spielobjekte. Unsere Anleitung behandelt die Erstellung des Enchanting-Tisches und die Konfiguration der Regale, um das maximale Enchanting-Niveau zu erreichen. O encantamento é uma habilidade que permite fortalecer equipamentos em jogos, utilizando uma tabela de encantamento e prateleiras para maximizar o nível de encantamento Энчантинг - это навык, который позволяет усилить оборудование в играх, используя таблицу энчантинга и полки для максимизации уровня энчантинга سحر الإيحاء هو مهارة تسمح بتعزيز المعدات في الألعاب، باستخدام جدول سحر الإيحاء والرفوف لزيادة أقصى مستوى لسحر الإيحاء how to use enchanting enchanting setup guide enchanting table configuration minecraft enchanting tutorial enchanting vs vanilla minecraft enchanting install for ai agents enchanting alternative for minecraft what is enchanting in minecraft enchanting bookshelf setup enchanting skill for ai agents Minecraft Enchanting Enchanting Table Minecraft AI CLI Enchanting Minecraft Enchanting Enchanting Setup Guide Creates enchanting tables using diamonds, obsidian, and books Configures bookshelves for maximum level 30 enchanting Supports enchanting table placement with specific block spacing Utilizes Minecraft crafting commands, such as `minecraft_craft` Requires specific materials, including diamonds and obsidian Enables AI agents to optimize enchanting setups for improved gameplay Enchanting is a skill that allows AI agents to enhance equipment using an enchanting system, requiring specific materials and configurations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MK-vet/bact-mdr-profiler/selfcheck', 'community', 'MK-vet', 'bact-mdr-profiler', 'MK-vet/bact-mdr-profiler', 'selfcheck', 0, 0, 30, '2026-02-25T14:32:41Z', '2026-03-07T03:59:12.262Z', '4370d59fd99b5f5bc921750722e8efdff0231e846490b63972bfa50eb381702e', '{"id":"MK-vet/bact-mdr-profiler/selfcheck","name":"selfcheck","description":{"en":"The selfcheck skill enables multidrug resistance profiling with causal discovery for bacterial AMR data, benefiting researchers and scientists. It reports self-check status and individual checks.","zh":"BactMDRProfiler的自检功能允许您运行`python -m bactmdrprofiler.cli --self-check`命令进行状态检查。该功能提供详细的检查报告","ja":"BactMDRProfilerのセルフチェック機能は、`python -m bactmdrprofiler.cli --self-check`コマンドを実行して状態を確認します。詳細なチェックレポートを提供","ko":"BactMDRProfiler의 셀프 체크 기능은 `python -m bactmdrprofiler.cli --self-check` 명령어를 실행하여 상태를 확인합니다. 자세한 체크 결과를 제공","es":"Selfcheck es una función de BactMDRProfiler que permite la detección de resistencia a medicamentos en bacterias. Utiliza causal discovery para analizar datos de AMR.","fr":"Selfcheck est une fonction de BactMDRProfiler qui permet la détection de la résistance aux médicaments chez les bactéries. Elle utilise la découverte causale pour analyser les données de résistance aux antimicrobiens (AMR).","de":"Selfcheck ist eine Funktion von BactMDRProfiler, die die Erkennung von Medikamentenresistenzen bei Bakterien ermöglicht. Sie verwendet kausale Entdeckung, um AMR-Daten zu analysieren.","pt":"O selfcheck é uma ferramenta de linha de comando que executa verificação de status e relatórios de profilagem de resistência a múltiplos medicamentos em dados de AMR bacteriana.","ru":"Selfcheck - это инструмент командной строки, который выполняет проверку статуса и отчеты профилирования мультидругой резистентности в данных бактериальной AMR с помощью ИИ Агентов.","ar":"selfcheck هو أداة سطر أوامر تقوم بتشغيل تحقق الحالة وتقارير تحليل المقاومة المتعددة للأدوية في بيانات AMR البكتيرية باستخدام وكلاء الذكاء الاصطناعي."},"seo":{"title":{"en":"selfcheck: Multidrug Resistance Profiling Setup Guide | A...","zh":"自检设置指南 - BactMDRProfiler","ja":"セルフチェック設定ガイド - BactMDRProfilerのAIエージェント","ko":"셀프 체크 설정 가이드 - BactMDRProfiler의 AI 도구","es":"Guía de configuración de selfcheck para perfiles de resis...","fr":"Guide de mise en place de selfcheck pour les profils de r...","de":"Einrichtungsleitfaden für selfcheck bei der Erstellung vo...","pt":"Guia de Configuração do selfcheck: Ferramenta de Perfil d...","ru":"Настройка selfcheck: Профилирование Мультидругой Резистен...","ar":"دليل إعداد selfcheck: أداة профايل المقاومة المتعددة للأد..."},"description":{"en":"Discover how to run self-checks with BactMDRProfiler. Learn to report self-check status and individual checks with our expert guide.","zh":"了解BactMDRProfiler的自检功能，运行`python -m bactmdrprofiler.cli --self-check`命令进行状态检查","ja":"BactMDRProfilerのセルフチェック機能を実行する方法を紹介します。`python -m bactmdrprofiler.cli --self-check`コマンドで状態を確認","ko":"BactMDRProfiler의 셀프 체크 기능을 사용하여 상태를 확인합니다. `python -m bactmdrprofiler.cli --self-check` 명령어를 실행","es":"Aprenda a utilizar selfcheck para perfiles de resistencia a medicamentos con BactMDRProfiler y descubra su función en la lucha contra la resistencia a los an...","fr":"Découvrez comment utiliser selfcheck pour les profils de résistance aux médicaments avec BactMDRProfiler et son rôle dans la lutte contre la résistance aux a...","de":"Erfahren Sie, wie Sie selfcheck für Medikamentenresistenzprofile mit BactMDRProfiler verwenden und seine Funktion im Kampf gegen Antibiotikaresistenzen","pt":"Aprenda a configurar o selfcheck para profilagem de resistência a múltiplos medicamentos em dados de AMR bacteriana","ru":"Узнайте, как настроить selfcheck для профилирования мультидругой резистентности в данных бактериальной AMR с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد selfcheck لتحليل المقاومة المتعددة للأدوية في بيانات AMR البكتيرية باستخدام وكلاء الذكاء الاصطناعي"},"definition":{"en":"selfcheck is a command-line interface for running self-checks with BactMDRProfiler, providing multidrug resistance profiling capabilities.","zh":"自检是BactMDRProfiler中的一个功能，用于检查状态并提供详细报告","ja":"セルフチェックは、BactMDRProfilerの機能の1つで、状態を確認し、詳細なレポートを提供","ko":"셀프 체크는 BactMDRProfiler의 기능 중 하나로, 상태를 확인하고 자세한 결과를 제공","es":"Selfcheck es una herramienta de línea de comandos que informa sobre el estado de la función de autocomprobación en BactMDRProfiler","fr":"Selfcheck est un outil en ligne de commande qui fournit des informations sur l''état de la fonction d''auto-vérification dans BactMDRProfiler","de":"Selfcheck ist ein Kommandozeilen-Tool, das Informationen über den Status der Selbstprüffunktion in BactMDRProfiler liefert","pt":"O selfcheck é uma ferramenta de perfil de resistência a múltiplos medicamentos que utiliza descoberta causal para dados de AMR bacteriana.","ru":"Selfcheck - это инструмент профилирования мультидругой резистентности, который использует причинно-следственную связь для данных бактериальной AMR.","ar":"selfcheck هو أداة профايل المقاومة المتعددة للأدوية التي تستخدم الاكتشاف السببي لبيانات AMR البكتيرية."},"features":{"en":["Runs self-checks using the `python -m bactmdrprofiler.cli --self-check` command","Reports self-check status and individual checks","Provides detailed information on any failures","Utilizes BactMDRProfiler for multidrug resistance profiling","Supports causal discovery for bacterial AMR data"],"zh":["运行`python -m bactmdrprofiler.cli --self-check`命令进行状态检查","提供详细的检查报告","支持BactMDRProfiler的多重耐药性 profiling","使用Python的CLI命令"],"ja":["`python -m bactmdrprofiler.cli --self-check`コマンドを実行して状態を確認","詳細なチェックレポートを提供","BactMDRProfilerの多重耐薬性profilingをサポート","PythonのCLIコマンドを使用"],"ko":["`python -m bactmdrprofiler.cli --self-check` 명령어를 실행하여 상태를 확인","자세한 체크 결과를 제공","BactMDRProfiler의 다중 耐약성 profiling을 지원","Python의 CLI 명령어를 사용"],"es":["Detección de resistencia a medicamentos en bacterias","Análisis de datos de AMR utilizando causal discovery","Informes de estado de la función de autocomprobación","Uso de la línea de comandos para ejecutar comandos","Compatibilidad con Python para la ejecución de scripts","Integración con BactMDRProfiler para perfiles de resistencia a medicamentos"],"fr":["Détection de la résistance aux médicaments chez les bactéries","Analyse des données de résistance aux antimicrobiens (AMR) à l''aide de la découverte causale","Rapports d''état de la fonction d''auto-vérification","Utilisation de la ligne de commande pour exécuter des commandes","Compatibilité avec Python pour l''exécution de scripts","Intégration avec BactMDRProfiler pour les profils de résistance aux médicaments"],"de":["Erkennung von Medikamentenresistenzen bei Bakterien","Analyse von AMR-Daten mithilfe kausaler Entdeckung","Berichte zum Status der Selbstprüffunktion","Verwendung der Kommandozeile zur Ausführung von Befehlen","Kompatibilität mit Python für die Ausführung von Skripten","Integration mit BactMDRProfiler für Medikamentenresistenzprofile"],"pt":["Execução de verificação de status via linha de comando","Relatórios de profilagem de resistência a múltiplos medicamentos","Utilização de descoberta causal para dados de AMR bacteriana","Suporte à execução de comandos via Python","Integração com a ferramenta BactMDRProfiler"],"ru":["Выполнение проверки статуса через командную строку","Отчеты профилирования мультидругой резистентности","Использование причинно-следственной связи для данных бактериальной AMR","Поддержка выполнения команд через Python","Интеграция с инструментом BactMDRProfiler и ИИ Агентами"],"ar":["تشغيل تحقق الحالة عبر سطر الأوامر","تقارير تحليل المقاومة المتعددة للأدوية","استخدام الاكتشاف السببي لبيانات AMR البكتيرية","دعم تشغيل الأوامر عبر Python","التكامل مع أداة BactMDRProfiler ووكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use selfcheck","selfcheck alternative","selfcheck setup guide","what is selfch