INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MK-vet/bact-mdr-profiler/selfcheck', 'selfcheck', 'MK-vet', 'bact-mdr-profiler', 'community', 'selfcheck MK-vet bact-mdr-profiler community The selfcheck skill enables multidrug resistance profiling with causal discovery for bacterial AMR data, benefiting researchers and scientists. It reports self-check status and individual checks. BactMDRProfiler的自检功能允许您运行`python -m bactmdrprofiler.cli --self-check`命令进行状态检查。该功能提供详细的检查报告 BactMDRProfilerのセルフチェック機能は、`python -m bactmdrprofiler.cli --self-check`コマンドを実行して状態を確認します。詳細なチェックレポートを提供 BactMDRProfiler의 셀프 체크 기능은 `python -m bactmdrprofiler.cli --self-check` 명령어를 실행하여 상태를 확인합니다. 자세한 체크 결과를 제공 Selfcheck es una función de BactMDRProfiler que permite la detección de resistencia a medicamentos en bacterias. Utiliza causal discovery para analizar datos de AMR. Selfcheck est une fonction de BactMDRProfiler qui permet la détection de la résistance aux médicaments chez les bactéries. Elle utilise la découverte causale pour analyser les données de résistance aux antimicrobiens (AMR). Selfcheck ist eine Funktion von BactMDRProfiler, die die Erkennung von Medikamentenresistenzen bei Bakterien ermöglicht. Sie verwendet kausale Entdeckung, um AMR-Daten zu analysieren. O selfcheck é uma ferramenta de linha de comando que executa verificação de status e relatórios de profilagem de resistência a múltiplos medicamentos em dados de AMR bacteriana. Selfcheck - это инструмент командной строки, который выполняет проверку статуса и отчеты профилирования мультидругой резистентности в данных бактериальной AMR с помощью ИИ Агентов. selfcheck هو أداة سطر أوامر تقوم بتشغيل تحقق الحالة وتقارير تحليل المقاومة المتعددة للأدوية في بيانات AMR البكتيرية باستخدام وكلاء الذكاء الاصطناعي. how to use selfcheck selfcheck alternative selfcheck setup guide what is selfcheck selfcheck vs BactMDRProfiler selfcheck install multidrug resistance profiling bacterial AMR data analysis causal discovery with selfcheck BactMDRProfiler 自检 状态检查 Python CLI 多重耐药性 profiling AI工具 自检设置 Runs self-checks using the `python -m bactmdrprofiler.cli --self-check` command Reports self-check status and individual checks Provides detailed information on any failures Utilizes BactMDRProfiler for multidrug resistance profiling Supports causal discovery for bacterial AMR data selfcheck is a command-line interface for running self-checks with BactMDRProfiler, providing multidrug resistance profiling capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('optimistic-updt/sync-agents/implement-plan', 'community', 'optimistic-updt', 'sync-agents', 'optimistic-updt/sync-agents', 'implement-plan', 0, 0, 30, '2026-02-20T03:50:23Z', '2026-03-07T13:08:45.360Z', '14a8d30d0913596f5b6d0116eef3e2128e46f0fd0a17d566dbf64a64b6b6cf91', '{"id":"optimistic-updt/sync-agents/implement-plan","name":"implement-plan","description":{"en":"The implement-plan skill enables AI agents to sync agent scripts and basic workflows, reading plans and original tickets to ensure complete context. This skill benefits developers and technical teams.","zh":"实现计划涉及阅读和理解技术计划，包括检查现有检查标记和成功标准","ja":"実装計画には、技術計画を読み込み、既存のチェックマークと成功基準を理解することが含まれます","ko":"실행 계획에는 기술 계획을 읽고 이해하는 것이 포함되며, 기존 체크마크와 성공 기준을 확인합니다","es":"Implementa planes técnicos aprobados con nuestra guía, que incluye la sincronización de scripts y flujos de trabajo básicos","fr":"Implémentez des plans techniques approuvés avec notre guide, qui comprend la synchronisation de scripts et de flux de travail de base","de":"Implementieren Sie genehmigte technische Pläne mit unserer Anleitung, die die Synchronisierung von Skripten und grundlegenden Workflows umfasst","pt":"Implemente planos técnicos com sincronização de scripts e fluxo de trabalho básico. Leia planos completamente e verifique checkmarks existentes.","ru":"Реализуйте технические планы с синхронизацией сценариев и основным потоком работы. Прочитайте планы полностью и проверьте существующие чекмарки.","ar":"نفذ خطط فنية مع مزامنة السكريبتات وال Fluxo الأساسي. اقرأ الخطط بالكامل وتحقق من العلامات الموجودة."},"seo":{"title":{"en":"Implement-Plan: Sync Agent Script Setup Guide | AI Agent ...","zh":"实现计划_setup指南 - AI智能代理","ja":"実装計画設定ガイド - AIエージェント","ko":"실행 계획 설정 가이드 - AI 에이전트","es":"Guía de implementación de planes: sincronización de scrip...","fr":"Guide d''implémentation de plans : synchronisation de scri...","de":"Implementierungsleitfaden für Pläne: Synchronisierung von...","pt":"Guia de Implementação de Planos: Sincronização de Scripts...","ru":"Реализация Плана: Синхронизация Сценариев и Основной Пото...","ar":"دليل تنفيذ الخطة: مزامنة سكريبتات و Fluxo الأساسي للأدوات..."},"description":{"en":"Unlock efficient workflow synchronization with implement-plan. Learn how to read plans, sync scripts, and achieve success criteria. Get started now!","zh":"了解如何实现技术计划，包括阅读计划、检查现有检查标记和成功标准","ja":"技術計画を実施する方法について学びます。計画の読み方、既存のチェックマークの確認、成功基準など","ko":"기술 계획을実施하는 방법에 대해 알아보세요. 계획阅读, 기존 체크마크 확인, 성공 기준 등","es":"Aprende a implementar planes técnicos aprobados con nuestra guía paso a paso, incluyendo la sincronización de scripts y flujos de trabajo básicos","fr":"Découvrez comment implémenter des plans techniques approuvés avec notre guide étape par étape, y compris la synchronisation de scripts et de flux de travail ...","de":"Erfahren Sie, wie Sie genehmigte technische Pläne mit unserer Schritt-für-Schritt-Anleitung implementieren, einschließlich der Synchronisierung von Skripten ...","pt":"Aprenda a implementar planos técnicos aprovados com sincronização de scripts e fluxo de trabalho básico para Ferramentas de Inteligência Artificial","ru":"Узнайте, как реализовать утвержденные технические планы с синхронизацией сценариев и основным потоком работы для ИИ Агентов","ar":"تعرف على كيفية تنفيذ الخطط الفنية المعتمدة مع مزامنة السكريبتات وال Fluxo الأساسي للأدوات الذكية"},"definition":{"en":"Implement-plan is a technical skill that involves reading and executing approved plans from docs/changes/<plan_path>/plan.md, ensuring successful workflow implementation.","zh":"实现计划是指根据技术计划文档实施具体的技术变更","ja":"実装計画とは、技術計画書に基づいて具体的な技術変更を実施すること","ko":"실행 계획은 기술 계획 문서에 따라 구체적인 기술 변경을実施하는 것을 의미합니다","es":"La implementación de planes es el proceso de sincronización de scripts y flujos de trabajo para cumplir con los planes técnicos aprobados","fr":"L''implémentation de plans est le processus de synchronisation de scripts et de flux de travail pour répondre aux plans techniques approuvés","de":"Die Implementierung von Plänen ist der Prozess der Synchronisierung von Skripten und Workflows, um die genehmigten technischen Pläne zu erfüllen","pt":"Implementação de plano é o processo de sincronização de scripts e fluxo de trabalho para execução de planos técnicos aprovados","ru":"Реализация плана - это процесс синхронизации сценариев и основного потока работы для выполнения утвержденных технических планов","ar":"تنفيذ الخطة هو عملية مزامنة السكريبتات وال Fluxo الأساسي لتنفيذ الخطط الفنية المعتمدة"},"features":{"en":["Reads plans from docs/changes/<plan_path>/plan.md","Checks for existing checkmarks (- [x]) in plans","Reads original tickets and all mentioned files","Ensures complete context by reading files fully without limit/offset parameters","Supports deep analysis of plan phases and success criteria"],"zh":["阅读技术计划文档","检查现有检查标记和成功标准","理解计划的各个阶段和变更","使用CLI读取文件","完全读取文件内容，不使用limit/offset参数"],"ja":["技術計画書を読み込む","既存のチェックマークと成功基準を確認する","計画の各段階と変更を理解する","CLIを使用してファイルを読み取る","ファイルの内容を完全に読み取る、limit/offsetパラメータを使用しない"],"ko":["기술 계획 문서를 읽습니다","기존 체크마크와 성공 기준을 확인합니다","계획의 각 단계와 변경을 이해합니다","CLI를 사용하여 파일을 읽습니다","파일 내용을 완전히 읽습니다. limit/offset 파라미터를 사용하지 않습니다"],"es":["Sincronización de scripts de agentes","Implementación de flujos de trabajo básicos","Lectura completa de archivos y planes","Análisis de los componentes del plan","Verificación de los criterios de éxito","Integración con herramientas de desarrollo"],"fr":["Synchronisation de scripts d''agents","Implémentation de flux de travail de base","Lecture complète de fichiers et de plans","Analyse des composants du plan","Vérification des critères de succès","Intégration avec des outils de développement"],"de":["Synchronisierung von Skripten von Agenten","Implementierung von grundlegenden Workflows","Vollständige Lektüre von Dateien und Plänen","Analyse der Komponenten des Plans","Überprüfung der Erfolgskriterien","Integration mit Entwicklungstools"],"pt":["Sincronização de scripts","Fluxo de trabalho básico","Leitura completa de planos","Verificação de checkmarks existentes","Integração com documentos técnicos"],"ru":["Синхронизация сценариев","Основной поток работы","Полное чтение планов","Проверка существующих чекмарков","Интеграция с техническими документами"],"ar":["مزامنة السكريبتات","ال Fluxo الأساسي","قراءة الخطط بالكامل","التحقق من العلامات الموجودة","التكامل مع الوثائق الفنية"]},"keywords":{"en":["how to use implement-plan","implement-plan setup guide","what is implement-plan","implement-plan alternative","implement-plan vs workflow automation","implement-plan install","sync agent script with implement-plan","implement-plan for AI agents","technical plan implementation with implement-plan"],"zh":["AI智能代理","技术计划","实现计划","计划文档","CLI","技术变更","成功标准","检查标记"],"ja":["AIエージェント","技術計画","実装計画","計画書","CLI","技術変更","成功基準","チェックマーク"],"ko":["AI 에이전트","기술 계획","실행 계획","계획 문서","CLI","기술 변경","성공 기준","체크마크"],"es":["implementación de planes","sincronización de scripts","flujos de trabajo básicos","desarrollo de software","herramientas de desarrollo","planificación técnica","implementación de planes técnicos","synchronización de agentes","desarrollo de aplicaciones","integración de sistemas"],"fr":["implémentation de plans","synchronisation de scripts","flux de travail de base","développement de logiciels","outils de développement","planification technique","implémentation de plans techniques","synchronisation d''agents","développement d''applications","intégration de systèmes"],"de":["Implementierung von Plänen","Synchronisierung von Skripten","grundlegende Workflows","Software-Entwicklung","Entwicklungstools","technische Planung","Implementierung von technischen Plänen","Synchronisierung von Agenten","Anwendungs-Entwicklung","System-Integration"],"pt":["implementação de plano","sincronização de scripts","fluxo de trabalho básico","Ferramentas de Inteligência Artificial","planos técnicos aprovados","leitura completa de planos","verificação de checkmarks existentes"],"ru":["реализация плана","синхронизация сценариев","основной поток работы","ИИ Агенты","утвержденные технические планы","полное чтение планов","проверка существующих чекмарков"],"ar":["تنفيذ الخطة","مزامنة السكريبتات","ال Fluxo الأساسي","الأدوات الذكية","الخطط الفنية المعتمدة","قراءة الخطط بالكامل","التحقق من العلامات الموجودة"]}},"owner":"optimistic-updt","repo":"sync-agents","repoPath":"optimistic-updt/sync-agents","stars":0,"forks":0,"updatedAt":"2026-02-20T03:50:23Z","topics":[],"category":"community","skillMd":{"name":"implement-plan","description":"Implement technical plans from docs/changes/<plan_path>/plan.md with verification","bodyPreview":"# Implement Plan\n\nYou are tasked with implementing an approved technical plan from `docs/changes/<plan_path>/plan.md`. These plans contain phases with specific changes and success criteria.\n\n## Getting Started\n\nWhen given a plan path:\n\n- Read the plan completely and check for any existing checkmarks (- [x])\n- Read the original ticket and all files mentioned in the plan\n- **Read files fully** - never use limit/offset parameters, you need complete context\n- Think deeply about how the pieces fit to","body":"# Implement Plan\n\nYou are tasked with implementing an approved technical plan from `docs/changes/<plan_path>/plan.md`. These plans contain phases with specific changes and success criteria.\n\n## Getting Started\n\nWhen given a plan path:\n\n- Read the plan completely and check for any existing checkmarks (- [x])\n- Read the original ticket and all files mentioned in the plan\n- **Read files fully** - never use limit/offset parameters, you need complete context\n- Think deeply about how the pieces fit together\n- Create a todo list to track your progress\n- Start implementing if you understand what needs to be done\n\nIf no plan path provided, ask for one.\n\n## Implementation Philosophy\n\nPlans are carefully designed, but reality can be messy. Your job is to:\n\n- Follow the plan''s intent while adapting to what you find\n- Implement each phase fully before moving to the next\n- Verify your work makes sense in the broader codebase context\n- Update checkboxes in the plan as you complete sections\n\nWhen things don''t match the plan exactly, think about why and communicate clearly. The plan is your guide, but your judgment matters too.\n\nIf you encounter a mismatch:\n\n- STOP and think deeply about why the plan can''t be followed\n- Present the issue clearly:\n\n  ```\n  Issue in Phase [N]:\n  Expected: [what the plan says]\n  Found: [actual situation]\n  Why this matters: [explanation]\n\n  How should I proceed?\n  ```\n\n## Verification Approach\n\nAfter implementing a phase:\n\n- Run the success criteria checks (usually `make check` covers everything)\n- Fix any issues before proceeding\n- Update your progress in both the plan and your todos\n- Check off completed items in the plan file itself using Edit\n- **Pause for human verification**: After completing all automated verification for a phase, pause and inform the human that the phase is ready for manual testing. Use this format:\n\n  ```\n  Phase [N] Complete - Ready for Manual Verification\n\n  Automated verification passed:\n  - [List automated checks that passed]\n\n  Please perform the manual verification steps listed in the plan:\n  - [List manual verification items from the plan]\n\n  Let me know when manual testing is complete so I can proceed to Phase [N+1].\n  ```\n\nIf instructed to execute multiple phases consecutively, skip the pause until the last phase. Otherwise, assume you are just doing one phase.\n\ndo not check off items in the manual testing steps until confirmed by the user.\n\n## If You Get Stuck\n\nWhen something isn''t working as expected:\n\n- First, make sure you''ve read and understood all the relevant code\n- Consider if the codebase has evolved since the plan was written\n- Present the mismatch clearly and ask for guidance\n\nUse sub-tasks sparingly - mainly for targeted debugging or exploring unfamiliar territory.\n\n## Resuming Work\n\nIf the plan has existing checkmarks:\n\n- Trust that completed work is done\n- Pick up from the first unchecked item\n- Verify previous work only if something seems off\n\nRemember: You''re implementing a solution, not just checking boxes. Keep the end goal in mind and maintain forward momentum.\n"},"lastSynced":"2026-03-07T13:08:45.360Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Agents requiring advanced plan implementation capabilities, particularly those working with markdown files and ticketing systems.","zh":"适用于需要高级计划实施能力的技术代理，特别是那些与markdown文件和工单系统合作的代理。","ja":"テクニカルエージェントが高度な計画実施能力を必要とする場合に適しています。特に、Markdownファイルやチケットシステムと協力するエージェントに適しています。","ko":"고급 계획 구현 기능을 필요로 하는 기술 에이전트에게 적합합니다. 특히 마크다운 파일 및 티켓 시스템과 협력하는 에이전트에게 적합합니다.","es":"Ideal para Agentes Técnicos que requieren capacidades de implementación de planes avanzados, particularmente aquellos que trabajan con archivos markdown y sistemas de ticketing.","fr":"Idéal pour les Agents Techniques nécessitant des capacités de mise en œuvre de plans avancés, en particulier ceux qui travaillent avec des fichiers markdown et des systèmes de ticketing.","de":"Ideal für technische Agenten, die erweiterte Planimplementierungsfähigkeiten erfordern, insbesondere solche, die mit Markdown-Dateien und Ticketingsystemen arbeiten.","pt":"Ideal para Agentes Técnicos que requerem capacidades avançadas de implementação de planos, particularmente aqueles que trabalham com arquivos markdown e sistemas de ticketing.","ru":"Идеально для Технических Агентов, требующих передовых возможностей реализации планов, особенно тех, кто работает с файлами markdown и системами отслеживания заявок.","ar":"مثالي للوكلاء الفنيين الذين يحتاجون إلى قدرات متقدمة لتنفيذ الخطط، خاصة أولئك الذين يعملون مع ملفات markdown وأنظمة التذاكر."},"recommendation":{"en":"Empowers agents to read and execute complex plans outlined in markdown files, ensuring complete context by parsing original tickets and associated files, and checking for existing checkmarks, all while considering the phases and success criteria within the plan.","zh":"赋予代理读取和执行markdown文件中概述的复杂计划的能力，通过解析原始工单和关联文件，检查现有的复选框，并考虑计划中的阶段和成功标准。","ja":"エージェントがMarkdownファイルに概説された複雑な計画を読み取って実行できるようにします。元のチケットや関連ファイルを解析し、既存のチェックマークを確認し、計画内のフェーズや成功基準を考慮することで、完全なコンテキストを確保します。","ko":"에이전트가 마크다운 파일에 개요된 복잡한 계획을 읽고 실행할 수 있도록 합니다. 원본 티켓 및 관련 파일을 파싱하고 기존 체크표시를 확인하며 계획 내 단계 및 성공 기준을 고려하여 완전한 컨텍스트를 보장합니다.","es":"Habilita a los agentes a leer y ejecutar planes complejos descritos en archivos markdown, asegurando un contexto completo al analizar los tickets originales y los archivos asociados, y comprobando la existencia de marcadores, considerando todas las fases y los criterios de éxito dentro del plan.","fr":"Permet aux agents de lire et d''exécuter des plans complexes décrits dans des fichiers markdown, en assurant un contexte complet en analysant les tickets originaux et les fichiers associés, et en vérifiant l''existence de coches, en tenant compte de toutes les phases et des critères de réussite au sein du plan.","de":"Ermächtigt Agenten, komplexe Pläne zu lesen und auszuführen, die in Markdown-Dateien beschrieben sind, indem sie den ursprünglichen Tickets und den zugehörigen Dateien analysieren und überprüfen, ob es vorhandene Markierungen gibt, unter Berücksichtigung aller Phasen und Erfolgskriterien innerhalb des Plans.","pt":"Habilita os agentes a ler e executar planos complexos delineados em arquivos markdown, garantindo o contexto completo ao analisar os tickets originais e arquivos associados, e verificar a existência de marcas de seleção, considerando as fases e os critérios de sucesso dentro do plano.","ru":"Наделяет агентов возможностью читать и выполнять сложные планы, изложенные в файлах markdown, обеспечивая полный контекст путем парсинга исходных заявок и связанных файлов, а также проверки наличия уже существующих отметок, учитывая фазы и критерии успеха внутри плана.","ar":"يمنح الوكلاء القدرة على قراءة وتنفيذ خطط معقدة مكتوبة في ملفات markdown، مع ضمان السياق الكامل من خلال تحليل التذاكر الأصلية والملفات المرتبطة، وفحص وجود علامات اختيار، مع مراعاة المراحل ومعيار النجاح داخل الخطة."},"useCases":{"en":["Implementing approved technical plans from markdown files","Parsing original tickets for complete context","Executing multi-phase plans with specific success criteria"],"zh":["从markdown文件实现批准的技术计划","解析原始工单以获取完整的上下文","执行具有特定成功标准的多阶段计划"],"ja":["Markdownファイルからの承認済みテクニカルプランの実施","完全なコンテキストを得るために元のチケットを解析","特定の成功基準を持つマルチフェーズプランの実行"],"ko":["마크다운 파일의 승인된 기술 계획 구현","완전한 컨텍스트를 얻기 위해 원본 티켓 파싱","특정 성공 기준을 갖는 다단계 계획 실행"],"es":["Implementación de planes técnicos aprobados a partir de archivos markdown","Análisis de tickets originales para obtener un contexto completo","Ejecución de planes multifásicos con criterios de éxito específicos"],"fr":["Mise en œuvre de plans techniques approuvés à partir de fichiers markdown","Analyse de tickets originaux pour obtenir un contexte complet","Exécution de plans multifaisceaux avec des critères de réussite spécifiques"],"de":["Implementierung genehmigter technischer Pläne aus Markdown-Dateien","Analyse von Originaltickets für vollständigen Kontext","Ausführung mehrphasiger Pläne mit spezifischen Erfolgskriterien"],"pt":["Implementação de planos técnicos aprovados a partir de arquivos markdown","Análise de tickets originais para contexto completo","Execução de planos multifásicos com critérios de sucesso específicos"],"ru":["Реализация утвержденных технических планов из файлов markdown","Парсинг исходных заявок для полного контекста","Выполнение многофазных планов с конкретными критериями успеха"],"ar":["تنفيذ خطط فنية موافق عليها من ملفات markdown","تحليل التذاكر الأصلية لسياق كامل","تنفيذ خطط متعددة المراحل بمعايير نجاح محددة"]},"limitations":{"en":["Requires access to plan markdown files and associated tickets","Limited to plans outlined in markdown format","Needs ability to read files fully without limit/offset parameters"],"zh":["需要访问计划的markdown文件和关联的工单","仅限于markdown格式中概述的计划","需要完全读取文件的能力，而不受限制/偏移参数的约束"],"ja":["計画のMarkdownファイルと関連チケットへのアクセスが必要","Markdown形式で概説された計画のみに限定","制限/オフセットパラメータなしでファイルを完全に読み取る機能が必要"],"ko":["계획의 마크다운 파일 및 관련 티켓에 대한 액세스가 필요","마크다운 형식으로 개요된 계획만으로 제한","제한/오프셋 매개 변수 없이 파일을 완전히 읽을 수 있는 기능이 필요"],"es":["Requiere acceso a archivos markdown de planes y tickets asociados","Limitado a planes descritos en formato markdown","Necesita la capacidad de leer archivos completamente sin parámetros de límite/desplazamiento"],"fr":["Nécessite un accès aux fichiers markdown de plans et aux tickets associés","Limité aux plans décrits au format markdown","Nécessite la capacité de lire les fichiers en entier sans paramètres de limite/décalage"],"de":["Benötigt Zugriff auf Markdown-Dateien von Plänen und zugehörigen Tickets","Begrenzt auf in Markdown-Format beschriebene Pläne","Benötigt die Fähigkeit, Dateien vollständig ohne Limit-/Offset-Parameter zu lesen"],"pt":["Requer acesso a arquivos markdown de planos e tickets associados","Limitado a planos delineados no formato markdown","Necessita capacidade de ler arquivos integralmente sem parâmetros de limite/offset"],"ru":["Требует доступа к файлам markdown планов и связанным заявкам","Ограничен планами, изложенными в формате markdown","Требует возможности читать файлы полностью без параметров лимита/смещения"],"ar":["يتطلب الوصول إلى ملفات markdown للخطط والتذاكر المرتبطة","محدود بالخطط المحددة في تنسيق markdown","يحتاج إلى القدرة على قراءة الملفات بالكامل دون معلمات الحد/الازاحة"]},"version":4},"contentHash":"14a8d30d0913596f5b6d0116eef3e2128e46f0fd0a17d566dbf64a64b6b6cf91","qualityScore":30}');
