INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('optimistic-updt/sync-agents/implement-plan', 'implement-plan', 'optimistic-updt', 'sync-agents', 'community', 'implement-plan optimistic-updt sync-agents community The implement-plan skill enables AI agents to sync agent scripts and basic workflows, reading plans and original tickets to ensure complete context. This skill benefits developers and technical teams. 实现计划涉及阅读和理解技术计划，包括检查现有检查标记和成功标准 実装計画には、技術計画を読み込み、既存のチェックマークと成功基準を理解することが含まれます 실행 계획에는 기술 계획을 읽고 이해하는 것이 포함되며, 기존 체크마크와 성공 기준을 확인합니다 Implementa planes técnicos aprobados con nuestra guía, que incluye la sincronización de scripts y flujos de trabajo básicos Implémentez des plans techniques approuvés avec notre guide, qui comprend la synchronisation de scripts et de flux de travail de base Implementieren Sie genehmigte technische Pläne mit unserer Anleitung, die die Synchronisierung von Skripten und grundlegenden Workflows umfasst Implemente planos técnicos com sincronização de scripts e fluxo de trabalho básico. Leia planos completamente e verifique checkmarks existentes. Реализуйте технические планы с синхронизацией сценариев и основным потоком работы. Прочитайте планы полностью и проверьте существующие чекмарки. نفذ خطط فنية مع مزامنة السكريبتات وال Fluxo الأساسي. اقرأ الخطط بالكامل وتحقق من العلامات الموجودة. how to use implement-plan implement-plan setup guide what is implement-plan implement-plan alternative implement-plan vs workflow automation implement-plan install sync agent script with implement-plan implement-plan for AI agents technical plan implementation with implement-plan AI智能代理 技术计划 实现计划 计划文档 CLI 技术变更 成功标准 检查标记 Reads plans from docs/changes/<plan_path>/plan.md Checks for existing checkmarks (- [x]) in plans Reads original tickets and all mentioned files Ensures complete context by reading files fully without limit/offset parameters Supports deep analysis of plan phases and success criteria Implement-plan is a technical skill that involves reading and executing approved plans from docs/changes/<plan_path>/plan.md, ensuring successful workflow implementation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kenccha/processcheck/scout', 'community', 'kenccha', 'processcheck', 'kenccha/processcheck', 'scout', 0, 0, 30, '2026-02-26T20:41:33Z', '2026-03-07T04:07:48.865Z', '507edad2342bf93920917791e49a036d365622fa12f8c73a092922022ea50cf1', '{"id":"kenccha/processcheck/scout","name":"scout","description":{"en":"The Scout skill enables developers to discover new features through competitor analysis and trend research, benefiting AI agent developers and project managers. It streamlines the feature discovery process.","zh":"Scout功能探索是通过竞争对手分析和趋势研究来发现新功能的过程","ja":"Scout AIエージェントは、競争相手分析とトレンド調査を通じて新機能を発見します","ko":"Scout 기능 탐색은 경쟁 제품 분석과 트렌드 조사를 통해 새로운 기능을 발굴하는 과정입니다","es":"Scout es una herramienta de análisis de tendencias y benchmarking que utiliza WebSearch para recopilar información","fr":"Scout est un outil d''analyse de tendances et de benchmarking qui utilise WebSearch pour collecter des informations","de":"Scout ist ein Tool für Trend- und Benchmark-Analysen, das WebSearch zur Informationsbeschaffung nutzt","pt":"O Scout é uma ferramenta de análise de funcionalidades de projeto que ajuda a identificar gaps e melhorar o workflow","ru":"ИИ Агент Scout - это инструмент анализа функций проекта, который помогает выявить пробелы и улучшить рабочий процесс","ar":"مسؤول الكشافة هو أداة لتحليل ميزات المشروع التي تساعد في تحديد الفجوات وتحسين سير العمل"},"seo":{"title":{"en":"Scout: Feature Discovery & Benchmarking Setup Guide | AI ...","zh":"Scout功能探索与竞争对手分析设置指南","ja":"Scout AIエージェントの機能発見とベンチマーキングガイド","ko":"Scout 기능 탐색 및 벤치마킹 설정 가이드","es":"Guía de configuración de Scout para análisis de tendencia...","fr":"Guide de mise en place de Scout pour l''analyse des tendan...","de":"Einrichtungsleitfaden für Scout zur Trend- und Benchmark-...","pt":"Guia de Configuração do Scout: Análise de Funcionalidades...","ru":"Настройка ИИ Агента Scout: Разработка Функций Проекта","ar":"دليل إعداد مسؤول الكشافة: تحليل ميزات المشروع"},"description":{"en":"Unlock new features with Scout! Discover how to analyze competitors, identify trends, and generate improvement proposals with this AI agent skill. Get starte...","zh":"了解Scout功能探索的技术细节，包括竞争对手分析、趋势研究和功能提案","ja":"Scout AIエージェントの機能発見とベンチマーキングについての技術情報をご覧ください","ko":"Scout 기능 탐색 및 벤치마킹의 기술 세부 정보를 확인하세요","es":"Aprende a configurar Scout para analizar tendencias y realizar benchmarking en proyectos de gestión","fr":"Découvrez comment configurer Scout pour analyser les tendances et effectuer un benchmarking dans les projets de gestion","de":"Erfahren Sie, wie Sie Scout für Trend- und Benchmark-Analysen in Management-Projekten einrichten","pt":"Aprenda a configurar o Scout para analisar funcionalidades de projeto e melhorar o seu workflow com as últimas tendências em gerenciamento de projetos","ru":"Узнайте, как настроить ИИ Агента Scout для анализа функций проекта и улучшения вашего рабочего процесса с последними тенденциями в управлении проектами","ar":"تعرف على كيفية إعداد مسؤول الكشافة لتحليل ميزات المشروع وتحسين سير العمل باستخدام أحدث التوجهات في إدارة المشاريع"},"definition":{"en":"Scout is a feature discovery and benchmarking skill that analyzes competitors and trends to identify new features and generate improvement proposals.","zh":"Scout功能探索是一种通过分析竞争对手和趋势来发现新功能的技术过程","ja":"Scout AIエージェントは、競争相手分析とトレンド調査を通じて新機能を発見する技術プロセスです","ko":"Scout 기능 탐색은 경쟁 제품과 트렌드를 분석하여 새로운 기능을 발굴하는 기술 프로세스입니다","es":"Scout es un agente de inteligencia artificial que analiza tendencias y realiza benchmarking en proyectos de gestión","fr":"Scout est un agent d''intelligence artificielle qui analyse les tendances et effectue un benchmarking dans les projets de gestion","de":"Scout ist ein künstlicher Intelligenz-Agent, der Trends analysiert und Benchmarking in Management-Projekten durchführt","pt":"O Scout é uma ferramenta de análise de funcionalidades de projeto que utiliza técnicas de pesquisa web e análise de tendências","ru":"ИИ Агент Scout - это инструмент анализа функций проекта, который использует методы веб-поиска и анализа тенденций","ar":"مسؤول الكشافة هو أداة لتحليل ميزات المشروع التي تستخدم تقنيات البحث على الويب وتحليل التوجهات"},"features":{"en":["Analyzes competitors and trends using WebSearch","Reads existing features and proposals from CLAUDE.md and docs/feature-review-2026.md","Generates improvement proposals based on gap analysis","Supports investigation of specific topics using $ARGUMENTS","Integrates with ProcessCheck to identify new feature opportunities"],"zh":["竞争对手分析","趋势研究","功能提案","WebSearch集成","自动化工作流","移动/响应式体验"],"ja":["競争相手分析","トレンド調査","機能提案","WebSearch統合","自動化ワークフロー","モバイル/レスポンシブ体験"],"ko":["경쟁 제품 분석","트렌드 조사","기능 제안","WebSearch 통합","자동화 워크플로우","모바일/반응형 경험"],"es":["Análisis de tendencias con WebSearch","Benchmarking de productos de gestión","Análisis de brechas en la funcionalidad actual","Generación de informes de recomendaciones","Integración con navegación y componentes JavaScript","Análisis de experiencias móviles y responsivas"],"fr":["Analyse des tendances avec WebSearch","Benchmarking de produits de gestion","Analyse des lacunes dans la fonctionnalité actuelle","Génération de rapports de recommandations","Intégration avec la navigation et les composants JavaScript","Analyse d''expériences mobiles et responsives"],"de":["Trend-Analyse mit WebSearch","Benchmarking von Management-Produkten","Analyse von Funktionslücken in der aktuellen Funktionalität","Erstellung von Empfehlungsberichten","Integration mit Navigation und JavaScript-Komponenten","Analyse von mobilen und responsiven Erfahrungen"],"pt":["Análise de funcionalidades de projeto utilizando técnicas de pesquisa web","Identificação de gaps e melhorias no workflow","Análise de tendências em gerenciamento de projetos","Integração com ferramentas de gerenciamento de projetos","Suporte a múltiplos formatos de arquivo","Interface de usuário intuitiva"],"ru":["Анализ функций проекта с использованием методов веб-поиска","Выявление пробелов и улучшение рабочего процесса","Анализ тенденций в управлении проектами","Интеграция с инструментами управления проектами","Поддержка нескольких форматов файлов","Интуитивно понятный интерфейс пользователя"],"ar":["تحليل ميزات المشروع باستخدام تقنيات البحث على الويب","تحديد الفجوات وتحسين سير العمل","تحليل التوجهات في إدارة المشاريع","التكامل مع أدوات إدارة المشاريع","دعم عدة صيغ ملفات","واجهة مستخدم متوافقة"]},"keywords":{"en":["how to use scout","scout alternative","scout setup guide","what is scout","scout vs competitor analysis","scout feature discovery","scout benchmarking","scout AI agent skill"],"zh":["Scout功能探索","AI工具","竞争对手分析","趋势研究","功能提案","WebSearch","自动化工作流","移动开发"],"ja":["Scout AIエージェント","AIエージェント","競争相手分析","トレンド調査","機能提案","WebSearch","自動化ワークフロー","モバイル開発"],"ko":["Scout 기능 탐색","AI 에이전트","경쟁 제품 분석","트렌드 조사","기능 제안","WebSearch","자동화 워크플로우","모바일 개발"],"es":["herramientas de inteligencia artificial","análisis de tendencias","benchmarking de gestión","WebSearch","navegación JavaScript","experiencias móviles","gestión de proyectos","agente de inteligencia artificial"],"fr":["outils d''intelligence artificielle","analyse des tendances","benchmarking de gestion","WebSearch","navigation JavaScript","expériences mobiles","gestion de projets","agent d''intelligence artificielle"],"de":["künstliche Intelligenz-Tools","Trend-Analyse","Benchmarking von Management","WebSearch","JavaScript-Navigation","mobile Erfahrungen","Projektmanagement","künstlicher Intelligenz-Agent"],"pt":["análise de funcionalidades de projeto","gerenciamento de projetos","ferramentas de análise de projeto","tendências em gerenciamento de projetos","otimização de workflow","ferramentas de produtividade","desenvolvimento de projetos","gestão de projetos","análise de gaps"],"ru":["анализ функций проекта","управление проектами","инструменты анализа проекта","тенденции в управлении проектами","оптимизация рабочего процесса","инструменты производительности","разработка проектов","управление проектами","анализ пробелов"],"ar":["تحليل ميزات المشروع","إدارة المشاريع","أدوات تحليل المشروع","التوجهات في إدارة المشاريع","تحسين سير العمل","أدوات الإنتاجية","تنمية المشاريع","إدارة المشاريع","تحليل الفجوات"]}},"owner":"kenccha","repo":"processcheck","repoPath":"kenccha/processcheck","stars":0,"forks":0,"updatedAt":"2026-02-26T20:41:33Z","topics":[],"category":"community","skillMd":{"name":"scout","description":"경쟁 PM 도구(Jira, Asana, Monday.com, Notion, ClickUp, Linear 등)를 조사하여 ProcessCheck에 추가할 새 기능 아이디어를 발굴. Use when the user asks to find new features, research competitors, or explore PM trends.","bodyPreview":"# Feature Scout — 기능 탐색 & 벤치마킹\n\n## 임무\nProcessCheck에 추가할 만한 새 기능을 경쟁 제품 분석과 트렌드 조사를 통해 발굴.\n\n## 조사 대상 (인자가 있으면 해당 주제, 없으면 전체)\n$ARGUMENTS\n\n## 작업 순서\n\n### 1. 현재 기능 파악\n먼저 아래 파일을 읽어서 이미 있는 기능과 기존 제안을 확인:\n- `CLAUDE.md` — 프로젝트 개요, 확정 디자인, Known Gaps\n- `docs/feature-review-2026.md` — 기존 10개 개선안\n- `processcheck-html/js/components.js` — 네비게이션 (현재 페이지 목록)\n\n### 2. 경쟁 제품 & 트렌드 조사\nWebSearch로 최신 정보 수집:\n- 프로젝트 관리 도구 최신 기능/트렌드\n- AI 기반 PM 기능 (자동 요약, 예측, 추천)\n- 워크플로우 자동화, 리포팅, 협업 기능\n- 모바일/반응형 경험\n\n### 3. 갭 분석 & 제안서 작성","body":"# Feature Scout — 기능 탐색 & 벤치마킹\n\n## 임무\nProcessCheck에 추가할 만한 새 기능을 경쟁 제품 분석과 트렌드 조사를 통해 발굴.\n\n## 조사 대상 (인자가 있으면 해당 주제, 없으면 전체)\n$ARGUMENTS\n\n## 작업 순서\n\n### 1. 현재 기능 파악\n먼저 아래 파일을 읽어서 이미 있는 기능과 기존 제안을 확인:\n- `CLAUDE.md` — 프로젝트 개요, 확정 디자인, Known Gaps\n- `docs/feature-review-2026.md` — 기존 10개 개선안\n- `processcheck-html/js/components.js` — 네비게이션 (현재 페이지 목록)\n\n### 2. 경쟁 제품 & 트렌드 조사\nWebSearch로 최신 정보 수집:\n- 프로젝트 관리 도구 최신 기능/트렌드\n- AI 기반 PM 기능 (자동 요약, 예측, 추천)\n- 워크플로우 자동화, 리포팅, 협업 기능\n- 모바일/반응형 경험\n\n### 3. 갭 분석 & 제안서 작성\n각 기능에 대해 아래 형식으로 정리:\n\n```markdown\n### [기능명] — [우선순위 HIGH/MEDIUM/LOW]\n\n**현재**: (있는지/없는지/부분 구현)\n**문제**: (왜 필요한지)\n**레퍼런스**: (어떤 도구가 어떻게 구현했는지 + URL)\n**구현 제안**: (ProcessCheck에서 어떻게 만들지 — 구체적으로)\n**영향 범위**: (변경될 파일/페이지)\n**난이도**: LOW/MEDIUM/HIGH\n```\n\n### 4. 결과 저장\n`docs/` 디렉토리에 마크다운 파일로 저장.\n\n## 제약 조건\n- ProcessCheck = 전자 제품 개발 프로세스 관리 (일반 PM과 도메인이 다름)\n- Firebase 서버리스 + GitHub Pages 정적 배포\n- 한국어 UI, 3역할(실무자/매니저/기획조정실), 6 Phase 구조\n"},"lastSynced":"2026-03-07T04:07:48.865Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and AutoGPT needing advanced feature discovery and trend analysis capabilities through competitor research and web search.","zh":"适合于Claude Code和AutoGPT等需要高级特性发现和趋势分析能力的AI代理，通过竞争对手研究和网络搜索实现。","ja":"Claude CodeやAutoGPTなどの高度な機能の発見とトレンド分析機能が必要なAIエージェントに適しています。競合他社の調査やWeb検索を通じてこれを実現します。","ko":"클라우드 코드와 오토GPT 같은 고급 기능 발견과 트렌드 분석 기능이 필요한 AI 에이전트에게 적합합니다. 경쟁사 연구와 웹 검색을 통해 이를 실현합니다.","es":"Ideal para agentes de IA como Claude Code y AutoGPT que necesitan capacidades avanzadas de descubrimiento de características y análisis de tendencias a través de la investigación de la competencia y la búsqueda en la web.","fr":"Idéal pour les agents IA comme Claude Code et AutoGPT nécessitant des capacités avancées de découverte de fonctionnalités et d''analyse de tendances via la recherche concurrentielle et la recherche sur le web.","de":"Ideal für KI-Agents wie Claude Code und AutoGPT, die erweiterte Funktions- und Trendanalysefähigkeiten durch Wettbewerbsforschung und Websuche benötigen.","pt":"Ideal para Agentes de IA como Claude Code e AutoGPT que necessitam de capacidades avançadas de descoberta de recursos e análise de tendências por meio de pesquisa de concorrentes e busca na web.","ru":"Идеально для агентов ИИ, таких как Claude Code и AutoGPT, которым необходимы продвинутые возможности обнаружения функций и анализа тенденций посредством исследования конкурентов и поиска в Интернете.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude Code و AutoGPT الذين يحتاجون إلى إمكانيات متقدمة لاكتشاف الميزات وتحليل الاتجاهات من خلال بحث المنافسين والبحث على الويب."},"recommendation":{"en":"Empowers agents to uncover new features and trends using WebSearch, analyzing competitor products, and identifying gaps in current project features, leveraging files like CLAUDE.md and docs/feature-review-2026.md for informed decision-making.","zh":"赋予代理能力，利用WebSearch发现新功能和趋势，分析竞争对手产品，找出当前项目功能的差距，并利用CLAUDE.md和docs/feature-review-2026.md等文件进行明智的决策。","ja":"WebSearchを利用して新しい機能やトレンドを発見し、競合他社の製品を分析し、現在のプロジェクト機能のギャップを特定し、CLAUDE.mdやdocs/feature-review-2026.mdなどのファイルを利用して情報に基づいた意思決定を行うことが代理者に可能になります。","ko":"웹 검색을 통해 새로운 기능과 트렌드를 발견하고 경쟁사 제품을 분석하며 현재 프로젝트 기능의 격차를 식별하며 CLAUDE.md와 docs/feature-review-2026.md 같은 파일을 활용하여 정보에 기반한 의사 결정을 에이전트가 수행할 수 있도록 합니다.","es":"Habilita a los agentes a descubrir nuevas características y tendencias utilizando WebSearch, analizando productos de la competencia e identificando lagunas en las características actuales del proyecto, utilizando archivos como CLAUDE.md y docs/feature-review-2026.md para la toma de decisiones informadas.","fr":"Permet aux agents de découvrir de nouvelles fonctionnalités et tendances en utilisant WebSearch, en analysant les produits des concurrents et en identifiant les lacunes dans les fonctionnalités actuelles du projet, en utilisant des fichiers tels que CLAUDE.md et docs/feature-review-2026.md pour une prise de décision éclairée.","de":"Ermöglicht es Agents, neue Funktionen und Trends mit WebSearch zu entdecken, Konkurrenzprodukte zu analysieren und Lücken in den aktuellen Projektfunktionen zu identifizieren, um mit Hilfe von Dateien wie CLAUDE.md und docs/feature-review-2026.md fundierte Entscheidungen zu treffen.","pt":"Habilita os agentes a descobrir novos recursos e tendências usando WebSearch, analisando produtos de concorrentes e identificando lacunas nos recursos atuais do projeto, aproveitando arquivos como CLAUDE.md e docs/feature-review-2026.md para tomada de decisões informadas.","ru":"Наделяет агентов возможностью обнаруживать новые функции и тенденции с помощью WebSearch, анализируя продукты конкурентов и выявляя пробелы в текущих функциях проекта, используя файлы типа CLAUDE.md и docs/feature-review-2026.md для принятия обоснованных решений.","ar":"تمكّن الوكلاء من اكتشاف ميزات جديدة واتجاهات باستخدام WebSearch، وبالتحليل منتجات المنافسين وتحديد الفجوات في الميزات الحالية للمشروع، وتستفيد من الملفات مثل CLAUDE.md و docs/feature-review-2026.md لاتخاذ قرارات مستنيرة."},"useCases":{"en":["Discovering new project features through competitor analysis","Researching trends in AI-based project management tools","Analyzing gaps in current features for enhancement proposals"],"zh":["通过竞争对手分析发现新的项目功能","研究基于AI的项目管理工具的趋势","分析当前功能的差距以提出增强建议"],"ja":["競合他社の分析を通じて新しいプロジェクト機能を発見する","AIベースのプロジェクト管理ツールのトレンドを調査する","現在の機能のギャップを分析して強化提案を行う"],"ko":["경쟁사 분석을 통해 새로운 프로젝트 기능을 발견하는 것","AI 기반 프로젝트 관리 도구의 트렌드를 조사하는こと","현재 기능의 격차를 분석하여 강화 제안을 하는 것"],"es":["Descubrir nuevas características de proyecto a través del análisis de la competencia","Investigar tendencias en herramientas de gestión de proyectos basadas en IA","Analizar lagunas en las características actuales para propuestas de mejora"],"fr":["Découvrir de nouvelles fonctionnalités de projet via l''analyse de la concurrence","Rechercher des tendances dans les outils de gestion de projet basés sur l''IA","Analyser les lacunes dans les fonctionnalités actuelles pour des propositions d''amélioration"],"de":["Entdecken neuer Projektmerkmale durch Konkurrenzanalyse","Trends in KI-basierten Projektmanagement-Tools recherchieren","Lücken in den aktuellen Funktionen für Verbesserungsvorschläge analysieren"],"pt":["Descobrir novos recursos do projeto por meio da análise de concorrentes","Pesquisar tendências em ferramentas de gerenciamento de projetos baseadas em IA","Analizar lacunas nos recursos atuais para propostas de melhoria"],"ru":["Обнаружение новых функций проекта посредством анализа конкурентов","Изучение тенденций в инструментах управления проектами на основе ИИ","Анализ пробелов в текущих функциях для предложений по улучшению"],"ar":["اكتشاف ميزات جديدة للمشروع من خلال تحليل المنافسين","البحث في الاتجاهات في أدوات إدارة المشاريع القائمة على الذكاء الاصطناعي","تحليل الفجوات في الميزات الحالية لاقتراحات التحسين"]},"limitations":{"en":["Requires access to specific files like CLAUDE.md and docs/feature-review-2026.md","Dependent on WebSearch for latest trend and competitor data"],"zh":["需要访问特定文件，如CLAUDE.md和docs/feature-review-2026.md","依赖于WebSearch来获取最新的趋势和竞争对手数据"],"ja":["CLAUDE.mdやdocs/feature-review-2026.mdなどの特定のファイルへのアクセスが必要","最新のトレンドや競合他社データの取得にWebSearchに依存する"],"ko":["CLAUDE.md와 docs/feature-review-2026.md 같은 특정 파일에 접근해야 하는 것","최신 트렌드와 경쟁사 데이터를 얻는 데 웹 검색에 의존하는 것"],"es":["Requiere acceso a archivos específicos como CLAUDE.md y docs/feature-review-2026.md","Depende de WebSearch para los últimos datos de tendencias y competidores"],"fr":["Nécessite un accès à des fichiers spécifiques tels que CLAUDE.md et docs/feature-review-2026.md","Dépend de WebSearch pour les dernières données de tendances et de concurrents"],"de":["Erfordert Zugriff auf bestimmte Dateien wie CLAUDE.md und docs/feature-review-2026.md","Hängt von WebSearch für die neuesten Trend- und Wettbewerberdaten ab"],"pt":["Exige acesso a arquivos específicos como CLAUDE.md e docs/feature-review-2026.md","Depende de WebSearch para os dados mais recentes de tendências e concorrentes"],"ru":["Требует доступа к конкретным файлам, таким как CLAUDE.md и docs/feature-review-2026.md","Зависит от WebSearch для получения последних данных о тенденциях и конкурентах"],"ar":["يتطلب الوصول إلى ملفات محددة مثل CLAUDE.md و docs/feature-review-2026.md","يعتمد على WebSearch للحصول على أحدث بيانات الاتجاهات والمنافسين"]},"version":4},"contentHash":"507edad2342bf93920917791e49a036d365622fa12f8c73a092922022ea50cf1","qualityScore":30}');
